# 书籍管理器 - 负责书籍的创建、管理和切换
class BooksManager:
    """书籍管理器 - 管理所有书籍的创建、存储和切换"""
    
    def __init__(self):
        self.books_dir = Path("books")
        self.books_file = self.books_dir / "books.json"
        self.current_book = None
        self.books = self.load_books()
        
    def _ensure_books_dir(self):
        """确保书籍目录存在"""
        self.books_dir.mkdir(parents=True, exist_ok=True)
    
    def load_books(self):
        """加载所有书籍信息"""
        self._ensure_books_dir()
        if not self.books_file.exists():
            return {}
        
        try:
            with open(self.books_file, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception as e:
            print(f"加载书籍列表失败: {e}")
            return {}
    
    def save_books(self):
        """保存所有书籍信息"""
        self._ensure_books_dir()
        try:
            with open(self.books_file, 'w', encoding='utf-8') as f:
                json.dump(self.books, f, ensure_ascii=False, indent=2)
            return True
        except Exception as e:
            print(f"保存书籍列表失败: {e}")
            return False
    
    def create_book(self, name, book_type="小说", description=""):
        """创建新书籍"""
        book_id = f"book_{int(time.time())}"
        book_info = {
            "id": book_id,
            "name": name,
            "type": book_type,
            "description": description,
            "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "last_modified": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        }
        
        # 创建书籍目录
        book_dir = self.books_dir / book_id
        book_dir.mkdir(parents=True, exist_ok=True)
        
        # 添加到书籍列表
        self.books[book_id] = book_info
        self.save_books()
        
        return book_id
    
    def get_book_info(self, book_id):
        """获取书籍信息"""
        return self.books.get(book_id)
    
    def get_all_books(self):
        """获取所有书籍"""
        return self.books
    
    def update_book_info(self, book_id, name=None, book_type=None, description=None):
        """更新书籍信息"""
        if book_id not in self.books:
            return False
        
        if name:
            self.books[book_id]["name"] = name
        if book_type:
            self.books[book_id]["type"] = book_type
        if description:
            self.books[book_id]["description"] = description
        
        self.books[book_id]["last_modified"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        
        return self.save_books()
    
    def delete_book(self, book_id):
        """删除书籍"""
        if book_id not in self.books:
            return False
        
        # 删除书籍目录
        book_dir = self.books_dir / book_id
        if book_dir.exists():
            import shutil
            shutil.rmtree(book_dir)
        
        # 从书籍列表中删除
        del self.books[book_id]
        return self.save_books()
    
    def set_current_book(self, book_id):
        """设置当前书籍"""
        if book_id not in self.books:
            return False
        
        self.current_book = book_id
        return True
    
    def get_current_book(self):
        """获取当前书籍"""
        return self.current_book
    
    def get_current_book_info(self):
        """获取当前书籍信息"""
        if not self.current_book:
            return None
        return self.get_book_info(self.current_book)
    
    def get_book_dir(self, book_id):
        """获取书籍存储目录"""
        return self.books_dir / book_id
    
    def get_current_book_dir(self):
        """获取当前书籍存储目录"""
        if not self.current_book:
            return None
        return self.get_book_dir(self.current_book)

# 数据库管理器 - 负责所有追踪数据的持久化
class DatabaseManager:
    """数据库管理器 - 将所有追踪数据写入到数据库文件夹"""

    def __init__(self, base_path="database", book_id=None):
        if book_id:
            # 如果指定了书籍ID，将数据存储在书籍目录下
            books_manager = get_books_manager()
            book_dir = books_manager.get_book_dir(book_id)
            self.base_path = book_dir / "database"
        else:
            self.base_path = Path(base_path)
        self.subfolders = {
            "spatial": self.base_path / "spatial",
            "character": self.base_path / "character",
            "relationship": self.base_path / "relationship",
            "event": self.base_path / "event",
            "quest": self.base_path / "quest",
            "branch": self.base_path / "branch",
            "profile": self.base_path / "profile",
            "timeline": self.base_path / "timeline",
            "logs": self.base_path / "logs"
        }
        self._ensure_directories()
        self.write_lock = threading.RLock()

    def _ensure_directories(self):
        """确保所有数据库目录存在"""
        for folder_path in self.subfolders.values():
            folder_path.mkdir(parents=True, exist_ok=True)

    def write_json(self, category, filename, data, chapter_info=None):
        """写入JSON数据到数据库"""
        print(f"[DEBUG] write_json被调用 - category: {category}, filename: {filename}, chapter_info: {chapter_info}")
        
        # 尝试获取锁，设置超时
        acquired = False
        try:
            acquired = self.write_lock.acquire(timeout=60)  # 60秒超时
            if not acquired:
                print(f"[ERROR] write_json获取锁超时 - category: {category}, filename: {filename}")
                return False
            
            print(f"[DEBUG] write_json获取锁成功 - category: {category}, filename: {filename}")
            
            try:
                folder_path = self.subfolders.get(category)
                if not folder_path:
                    print(f"[DEBUG] write_json失败 - 找不到category: {category}")
                    return False

                # 避免使用Path的__truediv__操作符，改用字符串拼接构建完整路径
                file_path = str(folder_path) + '/' + filename + '.json'
                print(f"[DEBUG] 准备写入文件: {file_path}")
                
                # 如果有章节信息，将其添加到数据中
                if chapter_info:
                    if isinstance(data, dict):
                        data_with_chapter = {
                            "_chapter_info": chapter_info,
                            **data
                        }
                    else:
                        data_with_chapter = {
                            "_chapter_info": chapter_info,
                            "data": data
                        }
                    data_to_write = data_with_chapter
                else:
                    data_to_write = data
                
                with open(file_path, 'w', encoding='utf-8') as f:
                    json.dump(data_to_write, f, ensure_ascii=False, indent=2)
                print(f"[DEBUG] 文件写入成功")

                # 暂时注释掉日志记录，避免无限递归
                # if category != "logs":
                #     self._log_operation(category, filename, "write", len(str(data)))
                return True
            except Exception as e:
                print(f"数据库写入错误 [{category}/{filename}]: {str(e)}")
                # 移除traceback.print_exc()避免递归
                return False
        finally:
            if acquired:
                self.write_lock.release()
                print(f"[DEBUG] write_json释放锁 - category: {category}, filename: {filename}")

    def read_json(self, category, filename, context_text="", filter_enabled=True, 
                  stage_filter=None, character_filter=None, importance_filter=None, 
                  chapter_filter=None, timestamp_range=None):
        """
        从数据库读取JSON数据，并根据多维度条件进行智能筛选
        
        Args:
            category: 数据类别
            filename: 文件名
            context_text: 上下文文本（用于提取角色信息）
            filter_enabled: 是否启用过滤
            stage_filter: 剧情阶段筛选（如"early", "middle", "late"）
            character_filter: 角色筛选列表
            importance_filter: 重要性筛选（如"关键事件", "重要转折"）
            chapter_filter: 章节筛选（章节号或章节名）
            timestamp_range: 时间戳范围筛选（tuple: (min_timestamp, max_timestamp)）
        """
        try:
            folder_path = self.subfolders.get(category)
            if not folder_path:
                return None

            # 使用字符串路径和os.path.exists检查文件是否存在
            file_path = str(folder_path) + '/' + filename + '.json'
            if not os.path.exists(file_path):
                return None

            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            
            # 如果启用过滤，进行多维度数据过滤
            if filter_enabled:
                # 提取角色信息（如果未提供角色筛选列表）
                if not character_filter and context_text:
                    import re
                    potential_characters = re.findall(r'[一-龥]{2,}', context_text)
                    common_words = ["时候", "地方", "今天", "明天", "这里", "那里", "他们", "她们", "我们"]
                    character_filter = [char for char in potential_characters if char not in common_words]
                
                # 根据类别进行多维度过滤
                if category == "character":
                    data = self._filter_character_data(data, character_filter, stage_filter, timestamp_range)
                
                elif category == "relationship":
                    data = self._filter_relationship_data(data, character_filter, stage_filter, timestamp_range)
                
                elif category == "spatial":
                    data = self._filter_spatial_data(data, character_filter, stage_filter, timestamp_range)
                
                elif category == "event":
                    data = self._filter_event_data(data, character_filter, importance_filter, stage_filter, timestamp_range)
                
                elif category == "quest":
                    data = self._filter_quest_data(data, stage_filter, timestamp_range)
                
                elif category == "branch":
                    data = self._filter_branch_data(data, stage_filter, timestamp_range)
                
                elif category == "timeline":
                    data = self._filter_timeline_data(data, stage_filter, timestamp_range)
            
            # 返回处理后的数据
            return data
        
        except Exception as e:
            print(f"数据库读取错误 [{category}/{filename}]: {str(e)}")
            return None
    
    def _filter_character_data(self, data, character_filter=None, stage_filter=None, timestamp_range=None):
        """筛选角色数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选角色信息
        if "characters" in data:
            filtered_characters = {}
            for char_name, char_data in data["characters"].items():
                # 角色筛选
                if character_filter and char_name not in character_filter:
                    continue
                
                # 时间戳筛选
                if timestamp_range and "timestamp" in char_data:
                    char_timestamp = char_data["timestamp"]
                    if char_timestamp < timestamp_range[0] or char_timestamp > timestamp_range[1]:
                        continue
                
                filtered_characters[char_name] = char_data
            filtered_data["characters"] = filtered_characters
        
        # 筛选行为记录
        if "actions" in data:
            filtered_actions = {}
            for char_name, actions in data["actions"].items():
                if character_filter and char_name not in character_filter:
                    continue
                
                # 时间戳筛选
                filtered_action_list = []
                for action in actions:
                    if timestamp_range and "timestamp" in action:
                        if action["timestamp"] < timestamp_range[0] or action["timestamp"] > timestamp_range[1]:
                            continue
                    filtered_action_list.append(action)
                
                if filtered_action_list:
                    filtered_actions[char_name] = filtered_action_list
            filtered_data["actions"] = filtered_actions
        
        # 筛选对话记录
        if "dialogues" in data:
            filtered_dialogues = {}
            for char_name, dialogues in data["dialogues"].items():
                if character_filter and char_name not in character_filter:
                    continue
                
                # 时间戳筛选
                filtered_dialogue_list = []
                for dialogue in dialogues:
                    if timestamp_range and "timestamp" in dialogue:
                        if dialogue["timestamp"] < timestamp_range[0] or dialogue["timestamp"] > timestamp_range[1]:
                            continue
                    filtered_dialogue_list.append(dialogue)
                
                if filtered_dialogue_list:
                    filtered_dialogues[char_name] = filtered_dialogue_list
            filtered_data["dialogues"] = filtered_dialogues
        
        # 保留其他字段
        for key in ["tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data
    
    def _filter_relationship_data(self, data, character_filter=None, stage_filter=None, timestamp_range=None):
        """筛选关系数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选关系
        if "relationships" in data:
            filtered_relationships = {}
            for key, value in data["relationships"].items():
                try:
                    char1, char2 = key.split('|')
                    # 角色筛选
                    if character_filter and char1 not in character_filter and char2 not in character_filter:
                        continue
                    
                    # 时间戳筛选
                    if timestamp_range and isinstance(value, list) and len(value) > 0:
                        latest_record = value[-1]
                        if "timestamp" in latest_record:
                            if latest_record["timestamp"] < timestamp_range[0] or latest_record["timestamp"] > timestamp_range[1]:
                                continue
                    
                    filtered_relationships[key] = value
                except:
                    continue
            filtered_data["relationships"] = filtered_relationships
        
        # 筛选关系历史
        if "relationship_history" in data:
            filtered_history = {}
            for key, value in data["relationship_history"].items():
                try:
                    char1, char2 = key.split('|')
                    # 角色筛选
                    if character_filter and char1 not in character_filter and char2 not in character_filter:
                        continue
                    
                    # 时间戳筛选
                    filtered_history_list = []
                    for history_item in value:
                        if timestamp_range and "timestamp" in history_item:
                            if history_item["timestamp"] < timestamp_range[0] or history_item["timestamp"] > timestamp_range[1]:
                                continue
                        filtered_history_list.append(history_item)
                    
                    if filtered_history_list:
                        filtered_history[key] = filtered_history_list
                except:
                    continue
            filtered_data["relationship_history"] = filtered_history
        
        # 筛选角色发展
        if "character_development" in data:
            filtered_development = {}
            for char, value in data["character_development"].items():
                # 角色筛选
                if character_filter and char not in character_filter:
                    continue
                
                # 时间戳筛选
                if timestamp_range and isinstance(value, list) and len(value) > 0:
                    filtered_dev_list = []
                    for dev_item in value:
                        if "timestamp" in dev_item:
                            if dev_item["timestamp"] < timestamp_range[0] or dev_item["timestamp"] > timestamp_range[1]:
                                continue
                        filtered_dev_list.append(dev_item)
                    if filtered_dev_list:
                        filtered_development[char] = filtered_dev_list
                else:
                    filtered_development[char] = value
            filtered_data["character_development"] = filtered_development
        
        # 保留其他字段
        for key in ["backstories", "tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data
    
    def _filter_spatial_data(self, data, character_filter=None, stage_filter=None, timestamp_range=None):
        """筛选空间数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选角色位置
        if "character_locations" in data:
            filtered_locations = {}
            for char_name, locations in data["character_locations"].items():
                # 角色筛选
                if character_filter and char_name not in character_filter:
                    continue
                
                # 时间戳筛选
                filtered_location_list = []
                for location in locations:
                    if timestamp_range and "timestamp" in location:
                        if location["timestamp"] < timestamp_range[0] or location["timestamp"] > timestamp_range[1]:
                            continue
                    filtered_location_list.append(location)
                
                if filtered_location_list:
                    filtered_locations[char_name] = filtered_location_list
            filtered_data["character_locations"] = filtered_locations
        
        # 筛选场景细节
        if "scene_details" in data:
            filtered_data["scene_details"] = data["scene_details"]
        
        # 筛选位置历史
        if "location_history" in data:
            filtered_history = []
            for history_item in data["location_history"]:
                # 时间戳筛选
                if timestamp_range and "timestamp" in history_item:
                    if history_item["timestamp"] < timestamp_range[0] or history_item["timestamp"] > timestamp_range[1]:
                        continue
                filtered_history.append(history_item)
            filtered_data["location_history"] = filtered_history
        
        # 保留其他字段
        for key in ["tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data
    
    def _filter_event_data(self, data, character_filter=None, importance_filter=None, 
                          stage_filter=None, timestamp_range=None):
        """筛选事件数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选事件
        if "events" in data:
            filtered_events = {}
            for event_id, event_data in data["events"].items():
                # 重要性筛选
                if importance_filter:
                    event_importance = event_data.get("data", {}).get("importance", "")
                    if importance_filter not in event_importance:
                        continue
                
                # 角色筛选
                if character_filter:
                    event_desc = event_data.get("data", {}).get("description", "")
                    if not any(char in event_desc for char in character_filter):
                        continue
                
                # 时间戳筛选
                if timestamp_range and "timestamp" in event_data:
                    if event_data["timestamp"] < timestamp_range[0] or event_data["timestamp"] > timestamp_range[1]:
                        continue
                
                filtered_events[event_id] = event_data
            filtered_data["events"] = filtered_events
        
        # 筛选因果链接
        if "causal_links" in data:
            filtered_links = []
            for link in data["causal_links"]:
                # 时间戳筛选
                if timestamp_range and "timestamp" in link:
                    if link["timestamp"] < timestamp_range[0] or link["timestamp"] > timestamp_range[1]:
                        continue
                filtered_links.append(link)
            filtered_data["causal_links"] = filtered_links
        
        # 保留其他字段
        for key in ["event_sequences", "tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data
    
    def _filter_quest_data(self, data, stage_filter=None, timestamp_range=None):
        """筛选任务数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选主线任务
        if "main_quests" in data:
            filtered_main_quests = {}
            for quest_id, quest_data in data["main_quests"].items():
                # 时间戳筛选
                if timestamp_range and "start_chapter" in quest_data:
                    if quest_data["start_chapter"] < timestamp_range[0] or quest_data["start_chapter"] > timestamp_range[1]:
                        continue
                filtered_main_quests[quest_id] = quest_data
            filtered_data["main_quests"] = filtered_main_quests
        
        # 筛选支线任务
        if "side_quests" in data:
            filtered_side_quests = {}
            for quest_id, quest_data in data["side_quests"].items():
                # 时间戳筛选
                if timestamp_range and "start_chapter" in quest_data:
                    if quest_data["start_chapter"] < timestamp_range[0] or quest_data["start_chapter"] > timestamp_range[1]:
                        continue
                filtered_side_quests[quest_id] = quest_data
            filtered_data["side_quests"] = filtered_side_quests
        
        # 保留其他字段
        for key in ["quest_progress", "quest_objectives", "tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data
    
    def _filter_branch_data(self, data, stage_filter=None, timestamp_range=None):
        """筛选分支数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选分支点 - 支持列表和字典两种格式
        if "branch_points" in data:
            branch_points = data["branch_points"]
            if isinstance(branch_points, list):
                # 列表格式
                filtered_points = []
                for branch_data in branch_points:
                    if timestamp_range and "timestamp" in branch_data:
                        if branch_data["timestamp"] < timestamp_range[0] or branch_data["timestamp"] > timestamp_range[1]:
                            continue
                    filtered_points.append(branch_data)
                filtered_data["branch_points"] = filtered_points
            elif isinstance(branch_points, dict):
                # 字典格式
                filtered_branches = {}
                for branch_id, branch_data in branch_points.items():
                    if timestamp_range and "timestamp" in branch_data:
                        if branch_data["timestamp"] < timestamp_range[0] or branch_data["timestamp"] > timestamp_range[1]:
                            continue
                    filtered_branches[branch_id] = branch_data
                filtered_data["branch_points"] = filtered_branches
        
        # 保留其他字段
        for key in ["branches", "branch_outcomes", "alternate_paths", "convergence_points", "tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data
    
    def _filter_timeline_data(self, data, stage_filter=None, timestamp_range=None):
        """筛选时间线数据"""
        if not isinstance(data, dict):
            return data
        
        filtered_data = {}
        
        # 筛选时间事件
        if "timeline_events" in data:
            filtered_events = []
            for event in data["timeline_events"]:
                # 时间戳筛选
                if timestamp_range and "position" in event:
                    if event["position"] < timestamp_range[0] or event["position"] > timestamp_range[1]:
                        continue
                filtered_events.append(event)
            filtered_data["timeline_events"] = filtered_events
        
        # 保留其他字段
        for key in ["current_time_point", "tracking_log"]:
            if key in data:
                filtered_data[key] = data[key]
        
        return filtered_data

    def append_log(self, log_type, data):
        """追加日志到数据库"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        log_filename = f"{log_type}_{timestamp}"
        return self.write_json("logs", log_filename, data)

    def _log_operation(self, category, filename, operation, data_size):
        """记录数据库操作日志"""
        log_entry = {
            "timestamp": datetime.now().isoformat(),
            "category": category,
            "filename": filename,
            "operation": operation,
            "data_size": data_size
        }
        self.append_log("database_operation", log_entry)


class SmartFilterManager:
    """
    智能筛选管理器 - 根据剧情阶段自动计算筛选参数
    用于优化追踪数据的读取，避免无差别读取全部数据
    
    核心功能：
    1. 已提及内容筛选 - 排除当前章节已详细描述的内容
    2. 角色出场频率筛选 - 避免角色频繁重复出现
    3. 角色状态筛选 - 根据角色当前状态筛选合理的行为
    4. 剧情相关性筛选 - 根据剧情发展阶段筛选相关内容
    """
    
    def __init__(self, db_manager=None):
        self.db_manager = db_manager or get_database_manager()
        self.stage_cache = {}
        self.chapter_timestamp_map = {}
        self.mentioned_content_cache = {}
        self.character_appearance_count = {}
        
    def calculate_filter_params(self, context_text="", current_chapter=None, 
                                current_time_point=None, stage=None):
        """
        根据上下文计算筛选参数
        
        Args:
            context_text: 当前上下文文本
            current_chapter: 当前章节号
            current_time_point: 当前时间点
            stage: 剧情阶段（"early", "middle", "late" 或自定义）
        
        Returns:
            dict: 包含所有筛选参数的字典
        """
        params = {
            "character_filter": None,
            "importance_filter": None,
            "timestamp_range": None,
            "stage_filter": stage
        }
        
        # 从上下文提取角色
        if context_text:
            params["character_filter"] = self._extract_characters_from_context(context_text)
        
        # 计算时间戳范围
        if current_chapter is not None or stage:
            params["timestamp_range"] = self._calculate_timestamp_range(
                current_chapter, stage, current_time_point
            )
        
        # 根据阶段设置重要性筛选
        if stage:
            params["importance_filter"] = self._get_importance_by_stage(stage)
        
        return params
    
    def _extract_characters_from_context(self, context_text):
        """从上下文文本中提取角色名称"""
        import re
        
        # 提取中文人名（2-5个汉字）
        potential_characters = re.findall(r'[一-龥]{2,5}', context_text)
        
        # 常见非角色词汇过滤
        common_words = {
            "时候", "地方", "今天", "明天", "这里", "那里", 
            "他们", "她们", "我们", "你们", "自己", "什么",
            "怎么", "为什么", "哪里", "怎样", "多少", "几个",
            "许多", "一些", "所有", "大家", "别人", "人家",
            "先生", "小姐", "夫人", "老爷", "少爷", "小姐",
            "此时", "彼时", "当时", "那时", "这时", "那会",
            "忽然", "突然", "终于", "竟然", "居然", "果然",
            "可是", "但是", "然而", "不过", "只是", "因为",
            "所以", "因此", "于是", "后来", "之后", "之前"
        }
        
        characters = []
        for char in potential_characters:
            if char not in common_words and len(char) >= 2:
                characters.append(char)
        
        # 去重并保持顺序
        seen = set()
        unique_characters = []
        for char in characters:
            if char not in seen:
                seen.add(char)
                unique_characters.append(char)
        
        return unique_characters[:20]  # 最多返回20个角色
    
    def _calculate_timestamp_range(self, current_chapter=None, stage=None, 
                                   current_time_point=None):
        """
        计算时间戳范围
        根据当前章节或剧情阶段确定应该读取的数据范围
        """
        if current_chapter is not None:
            # 基于章节计算：读取当前章节及前3章的数据
            min_timestamp = max(0, current_chapter - 3)
            max_timestamp = current_chapter + 1
            return (min_timestamp, max_timestamp)
        
        if stage:
            # 基于阶段计算
            stage_ranges = {
                "early": (0, 5),      # 早期阶段：前5个时间戳
                "middle": (3, 15),    # 中期阶段：时间戳3-15
                "late": (10, 100),    # 后期阶段：时间戳10以后
                "recent": (-5, 100),  # 最近：最近5个时间戳到最新
                "all": (0, 10000)     # 全部数据
            }
            return stage_ranges.get(stage, (0, 10000))
        
        if current_time_point:
            # 基于时间点计算（需要从时间线数据推断）
            timeline_data = self.db_manager.read_json("timeline", "tracker_data", 
                                                      filter_enabled=False)
            if timeline_data and "timeline_events" in timeline_data:
                for i, event in enumerate(timeline_data["timeline_events"]):
                    if event.get("time") == current_time_point:
                        # 返回当前时间点前后各3个位置
                        return (max(0, i - 3), i + 4)
        
        # 默认返回最近的数据范围
        return (0, 100)
    
    def _get_importance_by_stage(self, stage):
        """根据剧情阶段获取重要性筛选条件"""
        importance_map = {
            "early": None,                    # 早期：读取所有事件
            "middle": "关键",                  # 中期：只读取关键事件
            "late": "关键事件",                # 后期：只读取关键事件
            "climax": "关键事件/重要转折",      # 高潮：只读取关键和转折事件
            "resolution": "关键事件"           # 结局：只读取关键事件
        }
        return importance_map.get(stage, None)
    
    def get_smart_filter_for_continuation(self, existing_content, outline_content=None,
                                          current_chapter=None):
        """
        为续写生成智能筛选参数
        这是主要入口方法，用于续写场景
        
        Args:
            existing_content: 已有章节内容
            outline_content: 大纲内容（可选）
            current_chapter: 当前章节号
        
        Returns:
            dict: 筛选参数字典
        """
        # 分析已有内容，提取关键信息
        stage = self._detect_story_stage(existing_content, current_chapter)
        characters = self._extract_characters_from_context(existing_content)
        
        # 获取当前时间点
        current_time_point = self._detect_current_time_point(existing_content)
        
        # 计算时间戳范围
        timestamp_range = self._calculate_timestamp_range(
            current_chapter=current_chapter,
            stage=stage,
            current_time_point=current_time_point
        )
        
        # 如果有大纲，提取大纲中的关键角色
        if outline_content:
            outline_characters = self._extract_characters_from_context(outline_content)
            characters = list(set(characters + outline_characters))[:30]
        
        return {
            "character_filter": characters,
            "importance_filter": self._get_importance_by_stage(stage),
            "timestamp_range": timestamp_range,
            "stage_filter": stage,
            "current_time_point": current_time_point
        }
    
    def _detect_story_stage(self, content, current_chapter=None):
        """
        检测故事阶段
        基于内容特征和章节号判断当前处于故事的哪个阶段
        """
        if current_chapter is not None:
            # 基于章节号判断（假设总章节数约30-50章）
            if current_chapter <= 5:
                return "early"
            elif current_chapter <= 15:
                return "middle"
            elif current_chapter <= 25:
                return "late"
            else:
                return "climax"
        
        # 基于内容特征判断
        stage_indicators = {
            "early": ["初遇", "相遇", "开始", "第一次", "新来", "刚到", "初识"],
            "middle": ["发展", "深入", "逐渐", "越来越", "渐渐", "开始明白"],
            "late": ["最终", "最后", "终于", "结局", "尾声", "即将"],
            "climax": ["高潮", "危机", "转折", "关键时刻", "生死", "决战"]
        }
        
        content_lower = content.lower() if content else ""
        
        for stage, indicators in stage_indicators.items():
            for indicator in indicators:
                if indicator in content_lower:
                    return stage
        
        return "middle"  # 默认中期
    
    def _detect_current_time_point(self, content):
        """从内容中检测当前时间点"""
        import re
        
        time_patterns = [
            r'(清晨|上午|中午|下午|傍晚|晚上|深夜|凌晨)',
            r'(第[一二三四五六七八九十]+天)',
            r'(\d+月\d+[日号])',
            r'(春天|夏天|秋天|冬天|春季|夏季|秋季|冬季)'
        ]
        
        for pattern in time_patterns:
            matches = re.findall(pattern, content)
            if matches:
                return matches[-1]  # 返回最后一个匹配（最新的时间点）
        
        return None
    
    def filter_data_by_relevance(self, data, category, filter_params):
        """
        根据相关性筛选数据
        这是高级筛选方法，会根据数据类型自动选择最佳筛选策略
        
        Args:
            data: 原始数据
            category: 数据类别
            filter_params: 筛选参数
        
        Returns:
            筛选后的数据
        """
        if not data or not filter_params:
            return data
        
        # 使用DatabaseManager的筛选方法
        if category == "character":
            return self.db_manager._filter_character_data(
                data, 
                filter_params.get("character_filter"),
                filter_params.get("stage_filter"),
                filter_params.get("timestamp_range")
            )
        elif category == "relationship":
            return self.db_manager._filter_relationship_data(
                data,
                filter_params.get("character_filter"),
                filter_params.get("stage_filter"),
                filter_params.get("timestamp_range")
            )
        elif category == "spatial":
            return self.db_manager._filter_spatial_data(
                data,
                filter_params.get("character_filter"),
                filter_params.get("stage_filter"),
                filter_params.get("timestamp_range")
            )
        elif category == "event":
            return self.db_manager._filter_event_data(
                data,
                filter_params.get("character_filter"),
                filter_params.get("importance_filter"),
                filter_params.get("stage_filter"),
                filter_params.get("timestamp_range")
            )
        elif category == "quest":
            return self.db_manager._filter_quest_data(
                data,
                filter_params.get("stage_filter"),
                filter_params.get("timestamp_range")
            )
        elif category == "timeline":
            return self.db_manager._filter_timeline_data(
                data,
                filter_params.get("stage_filter"),
                filter_params.get("timestamp_range")
            )
        
        return data
    
    def extract_mentioned_content(self, content, max_items=50):
        """
        从内容中提取已提及的内容
        用于后续筛选，避免重复提及
        
        Args:
            content: 文本内容
            max_items: 最大提取数量
        
        Returns:
            dict: 包含已提及的角色、事件、地点等
        """
        import re
        
        mentioned = {
            "characters": [],
            "events": [],
            "locations": [],
            "objects": [],
            "relationships": [],
            "actions": []
        }
        
        if not content:
            return mentioned
        
        # 提取已提及的角色
        character_patterns = [
            r'([一-龥]{2,5})(?:说|道|问|答|想|看|走|来|去|站|坐|笑|哭)',
            r'([一-龥]{2,5})(?:的|之)',
            r'([一-龥]{2,5})对([一-龥]{2,5})',
            r'([一-龥]{2,5})和([一-龥]{2,5})',
        ]
        
        for pattern in character_patterns:
            matches = re.findall(pattern, content)
            for match in matches:
                if isinstance(match, tuple):
                    for char in match:
                        if len(char) >= 2 and char not in mentioned["characters"]:
                            mentioned["characters"].append(char)
                else:
                    if len(match) >= 2 and match not in mentioned["characters"]:
                        mentioned["characters"].append(match)
        
        # 提取已提及的地点
        location_patterns = [
            r'在([一-龥]{2,10})(?:里|中|外|上|下|旁|边)',
            r'来到([一-龥]{2,10})',
            r'离开([一-龥]{2,10})',
            r'回到([一-龥]{2,10})',
        ]
        
        for pattern in location_patterns:
            matches = re.findall(pattern, content)
            for match in matches:
                if match not in mentioned["locations"]:
                    mentioned["locations"].append(match)
        
        # 提取已提及的事件
        event_patterns = [
            r'([一-龥]{2,20})事件',
            r'发生了([一-龥]{2,20})',
            r'([一-龥]{2,20})之后',
        ]
        
        for pattern in event_patterns:
            matches = re.findall(pattern, content)
            for match in matches:
                if match not in mentioned["events"]:
                    mentioned["events"].append(match)
        
        # 提取已提及的关系
        relationship_patterns = [
            r'([一-龥]{2,5})是([一-龥]{2,5})的(父亲|母亲|兄弟|姐妹|朋友|敌人|恋人)',
            r'([一-龥]{2,5})与([一-龥]{2,5})(?:是|成为)(朋友|敌人|恋人)',
        ]
        
        for pattern in relationship_patterns:
            matches = re.findall(pattern, content)
            for match in matches:
                rel_str = f"{match[0]}-{match[2]}-{match[1]}" if len(match) == 3 else f"{match[0]}-{match[1]}"
                if rel_str not in mentioned["relationships"]:
                    mentioned["relationships"].append(rel_str)
        
        # 限制数量
        for key in mentioned:
            mentioned[key] = mentioned[key][:max_items]
        
        return mentioned
    
    def calculate_character_appearance_frequency(self, content, character_name):
        """
        计算角色在内容中的出场频率
        
        Args:
            content: 文本内容
            character_name: 角色名
        
        Returns:
            dict: 包含出场次数、提及频率等信息
        """
        import re
        
        if not content or not character_name:
            return {"count": 0, "frequency": 0.0, "is_overexposed": False}
        
        # 统计角色名出现次数
        count = len(re.findall(character_name, content))
        
        # 计算提及频率（每1000字提及次数）
        content_length = len(content)
        frequency = (count / content_length * 1000) if content_length > 0 else 0
        
        # 判断是否过度曝光（每1000字超过5次）
        is_overexposed = frequency > 5.0
        
        return {
            "count": count,
            "frequency": frequency,
            "is_overexposed": is_overexposed,
            "character_name": character_name
        }
    
    def filter_by_mentioned_content(self, data, mentioned_content, category):
        """
        根据已提及内容筛选数据
        排除当前章节已详细描述的内容
        
        Args:
            data: 原始数据
            mentioned_content: 已提及内容字典
            category: 数据类别
        
        Returns:
            筛选后的数据
        """
        if not data or not mentioned_content:
            return data
        
        if category == "character":
            return self._filter_character_by_mentioned(data, mentioned_content)
        elif category == "event":
            return self._filter_event_by_mentioned(data, mentioned_content)
        elif category == "spatial":
            return self._filter_spatial_by_mentioned(data, mentioned_content)
        elif category == "relationship":
            return self._filter_relationship_by_mentioned(data, mentioned_content)
        
        return data
    
    def _filter_character_by_mentioned(self, data, mentioned_content):
        """筛选角色数据，排除已详细描述的角色"""
        if not isinstance(data, dict) or "characters" not in data:
            return data
        
        mentioned_characters = mentioned_content.get("characters", [])
        filtered_data = data.copy()
        
        # 不完全排除已提及的角色，但标记其出场频率
        if "characters" in filtered_data:
            for char_name in filtered_data["characters"]:
                if char_name in mentioned_characters:
                    # 标记为已提及
                    filtered_data["characters"][char_name]["already_mentioned"] = True
                    # 计算出场频率
                    freq_info = self.character_appearance_count.get(char_name, {"frequency": 0})
                    filtered_data["characters"][char_name]["appearance_frequency"] = freq_info.get("frequency", 0)
                    filtered_data["characters"][char_name]["is_overexposed"] = freq_info.get("is_overexposed", False)
        
        return filtered_data
    
    def _filter_event_by_mentioned(self, data, mentioned_content):
        """筛选事件数据，排除已详细描述的事件"""
        if not isinstance(data, dict) or "events" not in data:
            return data
        
        mentioned_events = mentioned_content.get("events", [])
        filtered_data = data.copy()
        
        # 排除已提及的事件
        if "events" in filtered_data:
            filtered_events = {}
            for event_id, event_data in filtered_data["events"].items():
                event_desc = event_data.get("description", "") or event_data.get("data", {}).get("description", "")
                
                # 检查事件是否已被提及
                is_mentioned = False
                for mentioned_event in mentioned_events:
                    if mentioned_event in event_desc or event_desc in mentioned_event:
                        is_mentioned = True
                        break
                
                if not is_mentioned:
                    filtered_events[event_id] = event_data
                else:
                    # 标记为已提及，但不完全排除
                    event_data["already_mentioned"] = True
                    filtered_events[event_id] = event_data
            
            filtered_data["events"] = filtered_events
        
        return filtered_data
    
    def _filter_spatial_by_mentioned(self, data, mentioned_content):
        """筛选空间数据，排除已详细描述的地点"""
        if not isinstance(data, dict):
            return data
        
        mentioned_locations = mentioned_content.get("locations", [])
        filtered_data = data.copy()
        
        # 标记已提及的地点
        if "scene_details" in filtered_data:
            for location in filtered_data["scene_details"]:
                if location in mentioned_locations:
                    for scene in filtered_data["scene_details"][location]:
                        scene["already_mentioned"] = True
        
        return filtered_data
    
    def _filter_relationship_by_mentioned(self, data, mentioned_content):
        """筛选关系数据，排除已详细描述的关系"""
        if not isinstance(data, dict) or "relationships" not in data:
            return data
        
        mentioned_relationships = mentioned_content.get("relationships", [])
        filtered_data = data.copy()
        
        # 标记已提及的关系
        if "relationships" in filtered_data:
            for rel_key in filtered_data["relationships"]:
                for mentioned_rel in mentioned_relationships:
                    if mentioned_rel in rel_key or rel_key in mentioned_rel:
                        for rel_record in filtered_data["relationships"][rel_key]:
                            rel_record["already_mentioned"] = True
                        break
        
        return filtered_data
    
    def filter_by_character_state(self, data, character_states):
        """
        根据角色状态筛选数据
        确保角色的行为符合其当前状态
        
        Args:
            data: 原始数据
            character_states: 角色状态字典 {角色名: 状态}
        
        Returns:
            筛选后的数据
        """
        if not data or not character_states:
            return data
        
        # 这里主要筛选行为和对话，确保符合角色状态
        if "characters" in data:
            for char_name, char_data in data["characters"].items():
                if char_name in character_states:
                    current_state = character_states[char_name]
                    
                    # 标记角色当前状态
                    char_data["current_state"] = current_state
                    
                    # 根据状态筛选行为
                    if "actions" in char_data:
                        char_data["actions"] = self._filter_actions_by_state(
                            char_data["actions"], current_state
                        )
                    
                    # 根据状态筛选对话
                    if "dialogues" in char_data:
                        char_data["dialogues"] = self._filter_dialogues_by_state(
                            char_data["dialogues"], current_state
                        )
        
        return data
    
    def _filter_actions_by_state(self, actions, state):
        """根据角色状态筛选行为"""
        # 定义不同状态下合理的行为类型
        state_action_map = {
            "健康": ["行走", "说话", "战斗", "工作", "休息"],
            "受伤": ["休息", "治疗", "缓慢移动", "说话"],
            "生病": ["休息", "治疗", "虚弱说话"],
            "愤怒": ["争吵", "战斗", "冲动行为", "大声说话"],
            "悲伤": ["哭泣", "沉默", "回忆", "独处"],
            "快乐": ["欢笑", "庆祝", "友好交流", "轻松行为"],
            "紧张": ["警惕", "观察", "准备", "小声说话"],
            "恐惧": ["逃跑", "躲藏", "颤抖", "求救"]
        }
        
        allowed_actions = state_action_map.get(state, [])
        
        # 如果没有定义该状态的行为，返回所有行为
        if not allowed_actions:
            return actions
        
        # 标记不合理的行为，但不完全排除
        for action in actions:
            action_text = action.get("action", "") if isinstance(action, dict) else str(action)
            is_reasonable = any(allowed in action_text for allowed in allowed_actions)
            if isinstance(action, dict):
                action["is_reasonable_for_state"] = is_reasonable
        
        return actions
    
    def _filter_dialogues_by_state(self, dialogues, state):
        """根据角色状态筛选对话"""
        # 定义不同状态下合理的对话语气
        state_tone_map = {
            "健康": ["正常", "轻松", "严肃", "友好"],
            "受伤": ["虚弱", "痛苦", "坚强", "平静"],
            "生病": ["虚弱", "痛苦", "平静"],
            "愤怒": ["激动", "尖锐", "冷漠", "讽刺"],
            "悲伤": ["低沉", "哽咽", "平静", "回忆"],
            "快乐": ["欢快", "轻松", "兴奋", "友好"],
            "紧张": ["急促", "警惕", "低声", "紧张"],
            "恐惧": ["颤抖", "急促", "低声", "求救"]
        }
        
        allowed_tones = state_tone_map.get(state, [])
        
        # 如果没有定义该状态的语气，返回所有对话
        if not allowed_tones:
            return dialogues
        
        # 标记不合理的对话，但不完全排除
        for dialogue in dialogues:
            dialogue_text = dialogue.get("content", "") if isinstance(dialogue, dict) else str(dialogue)
            tone = dialogue.get("tone", "") if isinstance(dialogue, dict) else ""
            
            is_reasonable = not tone or tone in allowed_tones
            if isinstance(dialogue, dict):
                dialogue["is_reasonable_for_state"] = is_reasonable
        
        return dialogues
    
    def get_smart_filter_for_continuation_v2(self, existing_content, outline_content=None,
                                              current_chapter=None, character_states=None):
        """
        为续写生成智能筛选参数（增强版）
        包含已提及内容筛选、角色出场频率筛选、角色状态筛选
        
        Args:
            existing_content: 已有章节内容
            outline_content: 大纲内容（可选）
            current_chapter: 当前章节号
            character_states: 角色状态字典（可选）
        
        Returns:
            dict: 筛选参数字典
        """
        # 获取基础筛选参数
        base_params = self.get_smart_filter_for_continuation(
            existing_content, outline_content, current_chapter
        )
        
        # 提取已提及内容
        mentioned_content = self.extract_mentioned_content(existing_content)
        
        # 计算角色出场频率
        if mentioned_content["characters"]:
            for char_name in mentioned_content["characters"]:
                freq_info = self.calculate_character_appearance_frequency(existing_content, char_name)
                self.character_appearance_count[char_name] = freq_info
        
        # 添加新的筛选参数
        enhanced_params = {
            **base_params,
            "mentioned_content": mentioned_content,
            "character_appearance_count": self.character_appearance_count,
            "character_states": character_states or {}
        }
        
        return enhanced_params


