# 改写专用数据库管理器 - 完全独立的追踪系统
class RewriteDatabaseManager:
    """改写专用数据库管理器 - 将所有改写追踪数据写入到色情数据库文件夹"""

    def __init__(self, base_path="色情"):
        self.base_path = Path(base_path)
        self.subfolders = {
            "空间追踪": self.base_path / "空间追踪",
            "角色追踪": self.base_path / "角色追踪", 
            "关系追踪": self.base_path / "关系追踪",
            "事件追踪": self.base_path / "事件追踪",
            "任务追踪": self.base_path / "任务追踪",
            "分支追踪": self.base_path / "分支追踪",
            "人物档案": self.base_path / "人物档案",
            "时间线追踪": self.base_path / "时间线追踪",
            "改写日志": self.base_path / "改写日志",
            "色情内容": self.base_path / "色情内容",
            "改写统计": self.base_path / "改写统计",
            "版本管理": self.base_path / "版本管理"
        }
        self._ensure_directories()
        self.write_lock = threading.RLock()

    def _ensure_directories(self):
        """确保所有数据库目录存在"""
        for folder_path in self.subfolders.values():
            folder_path.mkdir(parents=True, exist_ok=True)

    def write_json(self, category, filename, data, chapter_info=None):
        """写入JSON数据到数据库"""
        print(f"[改写数据库] write_json被调用 - 分类: {category}, 文件名: {filename}, 章节信息: {chapter_info}")
        
        # 尝试获取锁，设置超时
        acquired = False
        try:
            acquired = self.write_lock.acquire(timeout=60)  # 60秒超时
            if not acquired:
                print(f"[改写数据库错误] write_json获取锁超时 - 分类: {category}, 文件名: {filename}")
                return False
            
            print(f"[改写数据库] write_json获取锁成功 - 分类: {category}, 文件名: {filename}")
            
            try:
                folder_path = self.subfolders.get(category)
                if not folder_path:
                    print(f"[改写数据库] write_json失败 - 找不到分类: {category}")
                    return False

                # 避免使用Path的__truediv__操作符，改用字符串拼接构建完整路径
                file_path = str(folder_path) + '/' + filename + '.json'
                print(f"[改写数据库] 准备写入文件: {file_path}")
                
                # 如果有章节信息，将其添加到数据中
                if chapter_info:
                    if isinstance(data, dict):
                        data_with_chapter = {
                            "_章节信息": chapter_info,
                            **data
                        }
                    else:
                        data_with_chapter = {
                            "_章节信息": chapter_info,
                            "数据": data
                        }
                    data_to_write = data_with_chapter
                else:
                    data_to_write = data
                
                with open(file_path, 'w', encoding='utf-8') as f:
                    json.dump(data_to_write, f, ensure_ascii=False, indent=2)
                print(f"[改写数据库] 文件写入成功")

                return True
            except Exception as e:
                print(f"改写数据库写入错误 [{category}/{filename}]: {str(e)}")
                return False
        finally:
            if acquired:
                self.write_lock.release()
                print(f"[改写数据库] write_json释放锁 - 分类: {category}, 文件名: {filename}")

    def read_json(self, category, filename, context_text="", filter_enabled=True):
        """从数据库读取JSON数据，并根据上下文进行过滤"""
        try:
            folder_path = self.subfolders.get(category)
            if not folder_path:
                return None

            # 使用字符串路径和os.path.exists检查文件是否存在
            file_path = str(folder_path) + '/' + filename + '.json'
            if not os.path.exists(file_path):
                return None

            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)            
            
            # 如果启用过滤且有上下文文本，进行数据过滤
            if filter_enabled and context_text:
                import re
                
                # 提取角色信息
                potential_characters = re.findall(r'[一-龥]{2,}', context_text)
                common_words = ["时候", "地方", "今天", "明天", "这里", "那里", "他们", "她们", "我们"]
                characters = [char for char in potential_characters if char not in common_words]
                
                # 根据类别进行过滤
                if category == "角色追踪":
                    # 只保留需要的角色信息
                    if isinstance(data, dict) and "角色们" in data:
                        filtered_characters = {}
                        for char in characters:
                            if char in data["角色们"]:
                                filtered_characters[char] = data["角色们"][char]
                        data["角色们"] = filtered_characters
                
                elif category == "关系追踪":
                    # 只保留需要的角色关系
                    if isinstance(data, dict):
                        # 过滤关系
                        if "关系们" in data:
                            filtered_relationships = {}
                            for key, value in data["关系们"].items():
                                # 检查关系中的角色是否在需求列表中
                                char1, char2 = key.split('|')
                                if char1 in characters or char2 in characters:
                                    filtered_relationships[key] = value
                            data["关系们"] = filtered_relationships
                        
                        # 过滤关系历史
                        if "关系历史" in data:
                            filtered_history = {}
                            for key, value in data["关系历史"].items():
                                char1, char2 = key.split('|')
                                if char1 in characters or char2 in characters:
                                    filtered_history[key] = value
                            data["关系历史"] = filtered_history
                        
                        # 过滤角色发展
                        if "角色发展" in data:
                            filtered_development = {}
                            for char, value in data["角色发展"].items():
                                if char in characters:
                                    filtered_development[char] = value
                            data["角色发展"] = filtered_development
                
                elif category == "空间追踪":
                    # 过滤空间数据，排除环境描写
                    if isinstance(data, dict):
                        # 移除环境描写相关字段
                        for field in ["环境描写", "氛围"]:
                            if field in data:
                                del data[field]
                
                elif category == "事件追踪":
                    # 保留所有事件信息，但根据上下文过滤相关事件
                    if isinstance(data, dict) and "事件们" in data and context_text:
                        # 提取上下文相关的事件
                        import re
                        potential_characters = re.findall(r'[一-龥]{2,}', context_text)
                        common_words = ["时候", "地方", "今天", "明天", "这里", "那里", "他们", "她们", "我们"]
                        characters = [char for char in potential_characters if char not in common_words]
                        
                        # 过滤与上下文相关的事件
                        filtered_events = {}
                        for event_id, event_data in data["事件们"].items():
                            event_desc = event_data["数据"].get("描述", "")
                            # 检查事件描述中是否包含上下文相关的角色
                            if any(char in event_desc for char in characters):
                                filtered_events[event_id] = event_data
                        
                        # 如果没有匹配到相关事件，保留所有事件
                        if filtered_events:
                            data["事件们"] = filtered_events
            
            # 返回处理后的数据
            return data
        
        except Exception as e:
            print(f"改写数据库读取错误 [{category}/{文件名}]: {str(e)}")
            return None

    def append_log(self, log_type, data):
        """追加日志到数据库"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        log_filename = f"{log_type}_{timestamp}"
        return self.write_json("改写日志", log_filename, data)

    def get_rewrite_stats(self):
        """获取改写统计信息"""
        try:
            stats = {
                "总改写次数": 0,
                "各风格统计": {},
                "各方向统计": {},
                "最近改写": []
            }
            
            # 统计改写日志
            logs_folder = self.subfolders["改写日志"]
            if logs_folder.exists():
                log_files = [f for f in logs_folder.glob("*.json")]
                stats["总改写次数"] = len(log_files)
                
                # 分析最近几次改写
                recent_logs = sorted(log_files, key=lambda x: x.stat().st_mtime, reverse=True)[:5]
                for log_file in recent_logs:
                    try:
                        with open(log_file, 'r', encoding='utf-8') as f:
                            log_data = json.load(f)
                        if isinstance(log_data, dict) and "改写信息" in log_data:
                            rewrite_info = log_data["改写信息"]
                            stats["最近改写"].append({
                                "时间": log_file.stem.split('_', 1)[1] if '_' in log_file.stem else "未知",
                                "风格": rewrite_info.get("风格", "未知"),
                                "方向": rewrite_info.get("方向", "未知"),
                                "章节": rewrite_info.get("章节", "未知")
                            })
                    except Exception as e:
                        print(f"分析改写日志失败 {log_file}: {e}")
            
            return stats
        except Exception as e:
            print(f"获取改写统计失败: {e}")
            return {"总改写次数": 0, "各风格统计": {}, "各方向统计": {}, "最近改写": []}

