# ═══════════════════════════════════════════════════════════════════════════════
# 正常改写处理器 - 完全独立的正常改写逻辑处理单元
# ═══════════════════════════════════════════════════════════════════════════════

class NormalRewriteProcessor:
    """
    正常改写处理器 - 独立的功能单元
    专注于正常的文学改写，不涉及任何色情元素
    拥有独立的输入验证、处理规则和输出控制机制
    """
    
    _实例 = None
    
    def __new__(cls):
        if cls._实例 is None:
            cls._实例 = super().__new__(cls)
            cls._实例._初始化()
        return cls._实例
    
    def _初始化(self):
        self.追踪管理器 = get_rewrite_tracking_manager()
        self.请求历史 = []
        self.响应缓存 = {}
        self.统计信息 = {
            "总请求数": 0,
            "成功响应数": 0,
            "失败响应数": 0,
            "平均响应时间": 0,
            "缓存命中率": 0,
            "改写模式": "正常改写"
        }
        self._缓存大小限制 = 100
        self._最大重试次数 = 3
        self._允许的改写方向 = ["文学润色", "风格转换", "细节增强", "情感深化", "节奏优化", "语言精炼"]
        print("[正常改写处理器] 初始化完成")
    
    def 验证输入(self, original_content, style, direction, custom_requirement):
        """
        独立的输入验证机制
        确保输入符合正常改写的要求
        """
        验证结果 = {"有效": True, "错误信息": []}
        
        if not original_content or not original_content.strip():
            验证结果["有效"] = False
            验证结果["错误信息"].append("原文内容不能为空")
        
        if not style or not style.strip():
            验证结果["有效"] = False
            验证结果["错误信息"].append("改写风格不能为空")
        
        if direction and direction not in self._允许的改写方向:
            验证结果["有效"] = False
            验证结果["错误信息"].append(f"无效的改写方向：{direction}，允许的方向：{self._允许的改写方向}")
        
        色情关键词 = ["色情", "情色", "成人", "18+", "NTR", "出轨", "调教", "乱伦", "群交", "露出", "交换", "多人", "后宫", "虐恋", "SM", "束缚", "羞辱", "支配", "臣服"]
        if custom_requirement:
            for 关键词 in 色情关键词:
                if 关键词 in custom_requirement:
                    验证结果["有效"] = False
                    验证结果["错误信息"].append(f"自定义要求中包含不允许的关键词：{关键词}，请使用色情改写模式")
                    break
        
        return 验证结果
    
    def 获取处理规则(self):
        """
        独立的处理规则
        定义正常改写的核心规则和约束
        """
        return {
            "核心原则": [
                "保持原文核心内容不变",
                "润色语言表达，使其更流畅自然",
                "优化细节描写，增强画面感",
                "调整节奏和氛围，提升阅读体验",
                "确保改写后的内容符合指定风格"
            ],
            "禁止行为": [
                "禁止改变故事走向和人物命运",
                "禁止删除或大幅修改核心情节",
                "禁止改变人物性格和关系",
                "禁止凭空添加与原文无关的新情节",
                "禁止改变原文的时间线和空间设定",
                "禁止添加任何色情、暴力、低俗内容"
            ],
            "风格要求": {
                "文学润色": "优化语言表达，提升文字质感",
                "风格转换": "将原文转换为指定的写作风格",
                "细节增强": "丰富细节描写，让场景更生动",
                "情感深化": "增强情感表达的深度和层次",
                "节奏优化": "调整句式和段落结构，优化阅读节奏",
                "语言精炼": "删除冗余表达，提升文字密度"
            }
        }
    
    def 处理改写请求(self, original_content, style="出版小说", custom_requirement="", next_chapter="", direction="文学润色", existing_chapters="", **kwargs):
        """
        处理正常改写请求
        完全独立的处理流程
        """
        start_time = time.time()
        self.统计信息["总请求数"] += 1
        
        验证结果 = self.验证输入(original_content, style, direction, custom_requirement)
        if not 验证结果["有效"]:
            错误信息 = "; ".join(验证结果["错误信息"])
            print(f"[正常改写处理器] 输入验证失败：{错误信息}")
            self._记录请求失败("validation_error", 错误信息)
            return None
        
        try:
            session_id = self.追踪管理器.开始改写会话(original_content, style, direction, custom_requirement)
            
            cache_key = self._生成缓存键(original_content, style, custom_requirement, next_chapter, direction)
            if cache_key in self.响应缓存:
                self.统计信息["缓存命中率"] = (self.统计信息.get("缓存命中率", 0) * (self.统计信息["总请求数"] - 1) + 1) / self.统计信息["总请求数"]
                cached_response = self.响应缓存[cache_key]
                print(f"[正常改写处理器] 命中缓存，返回缓存结果 - 会话ID: {session_id}")
                return cached_response
            
            rewrite_prompt = self._构建改写提示词(original_content, style, custom_requirement, next_chapter, direction, existing_chapters)
            
            self._记录请求开始(session_id, original_content, style, direction, custom_requirement)
            
            rewritten_content = self._调用AI生成(rewrite_prompt, style, custom_requirement=custom_requirement, **kwargs)
            
            if rewritten_content:
                self.追踪管理器.追踪改写内容(rewritten_content, {"原文长度": len(original_content), "改写长度": len(rewritten_content)})
                
                consistency_issues = self.追踪管理器.分析改写一致性(original_content, rewritten_content)
                if consistency_issues:
                    print(f"[正常改写处理器] 警告：检测到一致性问题 - {consistency_issues}")
                
                self.追踪管理器.结束改写会话(True, rewritten_content)
                
                self._添加到缓存(cache_key, rewritten_content)
                
                response_time = time.time() - start_time
                self._记录请求成功(session_id, response_time, len(rewritten_content))
                
                return rewritten_content
            else:
                self.追踪管理器.结束改写会话(False, "", "AI生成返回空内容")
                self._记录请求失败(session_id, "AI生成返回空内容")
                return None
                
        except Exception as e:
            error_msg = str(e)
            print(f"[正常改写处理器] 错误：改写请求处理失败 - {error_msg}")
            
            if self.追踪管理器.当前改写会话:
                self.追踪管理器.结束改写会话(False, "", error_msg)
            
            self._记录请求失败("unknown", error_msg)
            return None
    
    def _生成缓存键(self, original_content, style, custom_requirement, next_chapter, direction):
        import hashlib
        content_str = f"NORMAL|{original_content}|{style}|{custom_requirement}|{next_chapter}|{direction}"
        return hashlib.md5(content_str.encode('utf-8')).hexdigest()
    
