    def _模拟生成(self, prompt, style):
        """模拟生成（用于测试或备用）"""
        import re
        original_match = re.search(r'原文内容：(.*?)改写风格', prompt, re.DOTALL)
        if original_match:
            original_content = original_match.group(1).strip()
            rewritten = original_content.replace("。", "，身体微微颤抖着。").replace("，", "，肌肤相亲，")
            return f"{rewritten}\n\n（这是一个模拟的色情改写结果）"
        return "模拟生成失败：无法提取原文内容"
    
    def _记录请求开始(self, session_id, original_content, style, direction, custom_requirement):
        """记录请求开始"""
        request_info = {
            "会话ID": session_id,
            "原文长度": len(original_content),
            "风格": style,
            "方向": direction,
            "自定义要求": custom_requirement[:100] if custom_requirement else "无",
            "改写模式": "色情改写"
        }
        
        self.请求历史.append({
            "时间": datetime.now().isoformat(),
            "类型": "请求开始",
            "信息": request_info
        })
        
        print(f"[色情改写处理器] 请求开始 - 会话ID: {session_id}, 风格: {style}, 方向: {direction}")
    
    def _记录请求成功(self, session_id, response_time, content_length):
        """记录请求成功"""
        self.统计信息["成功响应数"] += 1
        
        total_time = self.统计信息.get("总响应时间", 0) + response_time
        self.统计信息["总响应时间"] = total_time
        self.统计信息["平均响应时间"] = total_time / self.统计信息["成功响应数"]
        
        success_info = {
            "会话ID": session_id,
            "响应时间": response_time,
            "内容长度": content_length,
            "改写模式": "色情改写"
        }
        
        self.请求历史.append({
            "时间": datetime.now().isoformat(),
            "类型": "请求成功",
            "信息": success_info
        })
        
        print(f"[色情改写处理器] 请求成功 - 会话ID: {session_id}, 响应时间: {response_time:.2f}s, 内容长度: {content_length}")
    
    def _记录请求失败(self, session_id, error_message):
        """记录请求失败"""
        self.统计信息["失败响应数"] += 1
        
        failure_info = {
            "会话ID": session_id,
            "错误信息": error_message[:200],
            "改写模式": "色情改写"
        }
        
        self.请求历史.append({
            "时间": datetime.now().isoformat(),
            "类型": "请求失败",
            "信息": failure_info
        })
        
        print(f"[色情改写处理器] 请求失败 - 会话ID: {session_id}, 错误: {error_message}")
    
    def _添加到缓存(self, cache_key, content):
        """添加到缓存"""
        if len(self.响应缓存) >= self._缓存大小限制:
            oldest_key = next(iter(self.响应缓存))
            del self.响应缓存[oldest_key]
        
        self.响应缓存[cache_key] = {
            "内容": content,
            "时间": datetime.now().isoformat(),
            "长度": len(content),
            "改写模式": "色情改写"
        }
    
    def 获取统计信息(self):
        """获取统计信息"""
        return self.统计信息.copy()
    
    def 获取请求历史(self, limit=50):
        """获取请求历史"""
        return self.请求历史[-limit:] if self.请求历史 else []
    
    def 清除缓存(self):
        """清除缓存"""
        self.响应缓存.clear()
        print("[色情改写处理器] 缓存已清除")
    
    def 获取缓存状态(self):
        """获取缓存状态"""
        return {
            "缓存项数": len(self.响应缓存),
            "缓存大小限制": self._缓存大小限制,
            "缓存命中率": self.统计信息.get("缓存命中率", 0),
            "改写模式": "色情改写"
        }


