        色情关键词 = ["色情", "情色", "成人", "18+", "NTR", "出轨", "调教", "乱伦", "群交", "露出", "交换", "多人", "后宫", "虐恋", "SM", "束缚", "羞辱", "支配", "臣服", "鸡巴", "肉棒", "小穴", "骚逼"]
        if requirements:
            for 关键词 in 色情关键词:
                if 关键词 in requirements:
                    验证结果["有效"] = False
                    验证结果["错误信息"].append(f"自定义要求中包含不允许的关键词：{关键词}，请使用色情生成模式")
                    break
        
        return 验证结果
    
