class SpatialTracker:
    """空间逻辑追踪器 - 追踪角色位置、场景细节和环境一致性"""

    def __init__(self):
        self.character_locations = {}
        self.scene_details = {}
        self.location_history = []
        self.environmental_consistency = []
        self._spatial_cache = {}  # 空间缓存
        self._location_patterns = None  # 编译的正则模式
        self._init_location_patterns()
    
    def _init_location_patterns(self):
        """初始化位置匹配模式"""
        import re
        self._location_patterns = [
            re.compile(r'在([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
            re.compile(r'来到([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
            re.compile(r'前往([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
            re.compile(r'回到([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
            re.compile(r'走进([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
            re.compile(r'离开([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
            re.compile(r'位于([^，。？！！？、：；""''【】()（）]+)', re.UNICODE),
        ]
        self._transition_words = ['然后', '接着', '之后', '于是', '随后', '过了一会儿', '不一会儿', '很快', '立刻', '马上']
    
    def _get_cached_locations(self, text_hash):
        """获取缓存的位置信息"""
        return self._spatial_cache.get(text_hash)
    
    def _cache_locations(self, text_hash, locations):
        """缓存位置信息"""
        if len(self._spatial_cache) > 1000:
            keys_to_remove = list(self._spatial_cache.keys())[:100]
            for k in keys_to_remove:
                del self._spatial_cache[k]
        self._spatial_cache[text_hash] = locations

    def update_character_location(self, character_name, location, time_point=None):
        """更新角色位置"""
        if character_name not in self.character_locations:
            self.character_locations[character_name] = []

        location_record = {
            "location": location,
            "time_point": time_point,
            "timestamp": len(self.character_locations[character_name])
        }
        self.character_locations[character_name].append(location_record)
        return location_record

    def get_character_location(self, character_name):
        """获取角色当前位置"""
        if character_name in self.character_locations and self.character_locations[character_name]:
            return self.character_locations[character_name][-1]
        return None

    def get_all_character_locations(self):
        """获取所有角色的当前位置"""
        return {
            char: self.get_character_location(char)
            for char in self.character_locations
        }

    def add_scene_detail(self, scene_key, details):
        """添加场景细节"""
        if scene_key not in self.scene_details:
            self.scene_details[scene_key] = []
        self.scene_details[scene_key].append({
            "details": details,
            "version": len(self.scene_details[scene_key])
        })

    def get_scene_details(self, scene_key):
        """获取场景细节"""
        if scene_key in self.scene_details and self.scene_details[scene_key]:
            return self.scene_details[scene_key][-1]
        return None

    def check_location_consistency(self, character_name, claimed_location):
        """检查位置一致性"""
        current = self.get_character_location(character_name)
        if current and current["location"] != claimed_location:
            return {
                "consistent": False,
                "previous_location": current["location"],
                "claimed_location": claimed_location,
                "issue": f"角色'{character_name}'声称在'{claimed_location}'，但之前记录在'{current['location']}'"
            }
        return {"consistent": True}

    def add_environmental_check(self, check_type, result, details):
        """添加环境一致性检查结果"""
        self.environmental_consistency.append({
            "check_type": check_type,
            "result": result,
            "details": details,
            "timestamp": len(self.environmental_consistency)
        })

    def get_spatial_summary(self):
        """获取空间逻辑摘要"""
        return {
            "character_locations": self.get_all_character_locations(),
            "scene_count": len(self.scene_details),
            "environmental_checks": len(self.environmental_consistency)
        }
    
    def extract_locations_fast(self, text):
        """快速提取位置信息（使用缓存）"""
        import hashlib
        text_hash = hashlib.md5(text.encode('utf-8')).hexdigest()
        cached = self._get_cached_locations(text_hash)
        if cached:
            return cached
        
        locations = []
        for pattern in self._location_patterns:
            matches = pattern.findall(text)
            locations.extend(matches)
        
        self._cache_locations(text_hash, locations)
        return locations
    
    def check_travel合理性(self, from_loc, to_loc, text):
        """检查移动合理性"""
        if not from_loc or from_loc == to_loc:
            return True
        
        distance_keywords = {
            'far': ['很远', '距离', '千里', '万里', '几个小时', '几天', '长途', '旅程'],
            'near': ['附近', '不远', '几步', '很快就', '一下就']
        }
        
        text_lower = text.lower()
        for kw in distance_keywords['far']:
            if kw in text:
                return True
        for kw in distance_keywords['near']:
            if kw in text:
                return True
        
        if from_loc in to_loc or to_loc in from_loc:
            return True
        
        return False

    def reset(self):
        """重置追踪器"""
        self.character_locations = {}
        self.scene_details = {}
        self.location_history = []
        self.environmental_consistency = []
        self._spatial_cache = {}
    
    def update_from_content(self, content):
        """从内容中更新空间追踪信息"""
        import re
        
        locations = self.extract_locations_fast(content)
        
        for location in locations:
            self.location_history.append({
                "location": location,
                "timestamp": len(self.location_history)
            })
        
        scene_patterns = [
            r'([^，。？！！？、：；""''【】()（）]+)的([^，。？！！？、：；""''【】()（）]+)',
            r'在([^，。？！！？、：；""''【】()（）]+)',
            r'来到([^，。？！！？、：；""''【】()（）]+)'
        ]
        
        for pattern in scene_patterns:
            matches = re.findall(pattern, content)
            for match in matches:
                if len(match) >= 2:
                    scene_key = f"{match[0]}_{match[1]}"
                    self.add_scene_detail(scene_key, {"description": f"{match[0]}的{match[1]}"})
                elif len(match) == 1:
                    scene_key = match[0]
                    self.add_scene_detail(scene_key, {"description": match[0]})
        
        self._init_location_patterns()


class CharacterBehaviorValidator:
    """角色行为逻辑自洽性校验器 - 确保人物设定与行为表现高度统一"""
    
    def __init__(self):
        self.character_profiles = {}
        self.behavior_patterns = {}
        self.consistency_checks = []
        self._compiled_patterns = {}
        self._behavior_cache = {}
        self._max_cache_size = 2000
        self._personality_vectors = {}
        self._behavior_predictions = {}
        self._cross_scene_checks = []
        self._motivation_behavior_map = {}
        self._abnormal_behaviors = []
        self._init_behavior_patterns()
        self._init_motivation_mapping()
    
    def _init_behavior_patterns(self):
        """初始化行为模式库"""
        import re
        self.behavior_categories = {
            'emotional': ['愤怒', '悲伤', '喜悦', '恐惧', '惊讶', '厌恶', '平静', '激动', '绝望', '期待', '焦虑', '欣慰', '苦涩', '释然'],
            'action': ['攻击', '防御', '逃跑', '等待', '观察', '思考', '决定', '犹豫', '后退', '前进', '躲避', '直面', '反击', '防守', '包抄', '撤退'],
            'social': ['对话', '争吵', '安慰', '威胁', '请求', '拒绝', '说服', '欺骗', '试探', '质问', '解释', '沉默', '倾听', '打断', '附和'],
            'cognitive': ['分析', '推理', '判断', '猜测', '回忆', '预见', '顿悟', '困惑', '确认', '质疑', '假设', '验证'],
            'physical': ['奔跑', '行走', '坐下', '站立', '躺卧', '倚靠', '握手', '拥抱', '推搡', '挣脱', '紧握', '轻抚']
        }
        
        self.personality_traits = {
            '外向型': {'keywords': ['开朗', '活泼', '健谈', '热情', '主动', '大方', '善交', '活跃'], 'behavior_tendency': ['主动', '热情', '善交']},
            '内向型': {'keywords': ['沉默', '安静', '内敛', '沉稳', '寡言', '孤僻', '独处', '深思'], 'behavior_tendency': ['沉默', '观察', '深思']},
            '勇敢型': {'keywords': ['勇敢', '无畏', '果断', '刚毅', '坚强', '坚定', '英勇', '无畏'], 'behavior_tendency': ['直面', '反击', '前进']},
            '谨慎型': {'keywords': ['谨慎', '小心', '细致', '周全', '三思', '保守', '稳妥', '稳重'], 'behavior_tendency': ['观察', '等待', '分析']},
            '暴躁型': {'keywords': ['急躁', '易怒', '冲动', '火爆', '粗犷', '直率', '激烈', '火爆'], 'behavior_tendency': ['攻击', '争吵', '果断']},
            '温和型': {'keywords': ['温和', '温柔', '善良', '体贴', '善解', '耐心', '柔和', '宽容'], 'behavior_tendency': ['安慰', '倾听', '解释']},
            '理性型': {'keywords': ['理性', '冷静', '客观', '分析', '逻辑', '理智', '推理', '判断'], 'behavior_tendency': ['分析', '推理', '判断']},
            '感性型': {'keywords': ['感性', '情感', '直觉', '感受', '共情', '敏感', '体会', '领悟'], 'behavior_tendency': ['感受', '共情', '顿悟']},
            '固执型': {'keywords': ['固执', '坚持', '执着', '坚定', '倔强', '顽强', '不懈', '顽固'], 'behavior_tendency': ['决定', '坚持', '直面']},
            '灵活型': {'keywords': ['灵活', '变通', '适应', '随机', '多变', '机动', '敏捷', '巧变'], 'behavior_tendency': ['躲避', '变化', '前进']}
        }
        
        self._compiled_patterns = {
            'emotional_reaction': re.compile(
                r'([^\s，,。？！!?；:："\'\'【】()（）]+)(?:感到|觉得|表现出|显得|被|一脸|心中|眼里|表情|神色)(' + 
                '|'.join(self.behavior_categories['emotional']) + ')',
                re.UNICODE
            ),
            'action_pattern': re.compile(
                r'([^\s，,。？！!?；:："\'\'【】()（）]+)(?:立刻|马上|迅速|缓缓|慢慢|突然|犹豫了一下|果断地|坚定地|默默地|轻轻地)(' +
                '|'.join(self.behavior_categories['action']) + ')',
                re.UNICODE
            ),
            'physical_action': re.compile(
                r'([^\s，,。？！!?；:："\'\'【】()（）]+)(?:缓缓地|慢慢地|迅速地|突然|轻轻地|用力地|慢慢地)(' +
                '|'.join(self.behavior_categories['physical']) + ')',
                re.UNICODE
            ),
            'dialogue_style': re.compile(
                r'([^\s，,。？！!?；:："\'\'【】()（）]+)(?:说|道|问道|答道|喊道|低声道|大声道|轻声道|冷笑道|苦笑道)',
                re.UNICODE
            ),
            'cognitive_process': re.compile(
                r'([^\s，,。？！!?；:："\'\'【】()（）]+)(?:想|思考|寻思|思忖|盘算|估量|推测|意识到|明白|理解|领悟)',
                re.UNICODE
            )
        }
        
        self._intensity_modifiers = {
            '极其': 1.5, '非常': 1.3, '相当': 1.2, '十分': 1.2, '格外': 1.3,
            '稍微': 0.7, '略': 0.8, '有点': 0.7, '略微': 0.8,
            '突然': 1.4, '渐渐': 0.8, '慢慢': 0.8
        }
    
    def _init_motivation_mapping(self):
        """初始化动机-行为映射关系"""
        self._motivation_behavior_map = {
            '复仇': ['攻击', '谋划', '追踪', '质问', '直面'],
            '求生': ['逃跑', '躲避', '防御', '求助', '反击'],
            '求爱': ['追求', '表白', '示好', '关心', '等待'],
            '求知': ['观察', '研究', '询问', '推理', '分析'],
            '保护': ['防御', '直面', '救援', '牺牲', '守护'],
            '逃离': ['逃跑', '躲避', '隐藏', '离开', '挣脱'],
            '权力': ['争夺', '控制', '打压', '收买', '展示'],
            '自由': ['突破', '反抗', '逃离', '追求', '挑战'],
            '正义': ['揭露', '对抗', '保护', '审判', '阻止'],
            '贪婪': ['夺取', '欺骗', '囤积', '占有', '控制']
        }
    
    def _calculate_personality_vector(self, personality_traits):
        """计算性格特征向量"""
        vector = {trait: 0.0 for trait in self.personality_traits}
        for trait in personality_traits:
            if trait in self.personality_traits:
                vector[trait] += 1.0
                for related in self.personality_traits[trait]['behavior_tendency']:
                    if related not in vector:
                        vector[related] = 0.0
        
        total = sum(vector.values()) or 1.0
        for key in vector:
            vector[key] = round(vector[key] / total, 3)
        
        return vector
    
    def _predict_behavior(self, character_name, context):
        """基于历史行为模式预测当前行为"""
        if character_name not in self._behavior_predictions:
            self._behavior_predictions[character_name] = {'history': [], 'patterns': {}}
        
        predictions = self._behavior_predictions[character_name]
        
        if len(predictions['history']) < 3:
            return {'confidence': 'low', 'predicted_behaviors': [], 'reason': '历史数据不足'}
        
        behavior_freq = {}
        for entry in predictions['history'][-20:]:
            for behavior in entry.get('behaviors', []):
                behavior_freq[behavior] = behavior_freq.get(behavior, 0) + 1
        
        sorted_behaviors = sorted(behavior_freq.items(), key=lambda x: x[1], reverse=True)[:5]
        
        return {
            'confidence': 'high' if len(predictions['history']) > 10 else 'medium',
            'predicted_behaviors': [b[0] for b in sorted_behaviors],
            'confidence_score': min(len(predictions['history']) / 20, 1.0)
        }
    
    def register_character(self, name, profile):
        """注册角色配置"""
        personality = profile.get('personality', [])
        self.character_profiles[name] = {
            'personality': personality,
            'habits': profile.get('habits', []),
            'speech_style': profile.get('speech_style', []),
            'behavior_traits': profile.get('behavior_traits', []),
            'forbidden_actions': profile.get('forbidden_actions', []),
            'core_motivations': profile.get('core_motivations', []),
            'registered_at': len(self.consistency_checks),
            'first_appearance': profile.get('first_appearance', ''),
            'background': profile.get('background', ''),
            'values': profile.get('values', []),
            'fears': profile.get('fears', []),
            'desires': profile.get('desires', [])
        }
        
        self._personality_vectors[name] = self._calculate_personality_vector(personality)
        self.behavior_patterns[name] = []
    
    def _analyze_behaviors_in_text(self, text):
        """分析文本中的行为"""
        behaviors = {'emotional': [], 'action': [], 'physical': [], 'dialogue': [], 'cognitive': []}
        
        for behavior_type, pattern in self._compiled_patterns.items():
            matches = pattern.findall(text)
            if matches:
                for match in matches:
                    if len(match) >= 2:
                        character = match[0].strip()
                        behavior = match[1].strip()
                        entry = {'character': character, 'behavior': behavior, 'raw': ''.join(match)}
                        if 'emotional' in behavior_type:
                            behaviors['emotional'].append(entry)
                        elif 'action' in behavior_type:
                            behaviors['action'].append(entry)
                        elif 'physical' in behavior_type:
                            behaviors['physical'].append(entry)
                        elif 'dialogue' in behavior_type:
                            behaviors['dialogue'].append(entry)
                        elif 'cognitive' in behavior_type:
                            behaviors['cognitive'].append(entry)
        
        return behaviors
    
    def validate_behavior(self, character_name, behavior_description, context=""):
        """校验行为是否符合角色设定"""
        if character_name not in self.character_profiles:
            return {'valid': True, 'reason': '角色未注册，跳过校验'}
        
        import hashlib
        cache_key = hashlib.md5(f"{character_name}:{behavior_description}".encode()).hexdigest()
        if cache_key in self._behavior_cache:
            cached = self._behavior_cache[cache_key]
            cached['cache_hit'] = True
            return cached
        
        profile = self.character_profiles[character_name]
        issues = []
        warnings = []
        suggestions = []
        
        for trait in profile.get('forbidden_actions', []):
            if trait in behavior_description:
                issues.append(f"行为'{behavior_description}'可能违反角色禁止设定: {trait}")
        
        habit_matched = False
        for habit in profile.get('habits', []):
            if habit in behavior_description:
                habit_matched = True
                break
        
        if not habit_matched and profile.get('habits'):
            if len(profile['habits']) <= 3:
                warnings.append(f"行为未体现角色常见习惯: {profile['habits']}")
        
        if character_name in self._personality_vectors:
            vector = self._personality_vectors[character_name]
            behaviors = self._analyze_behaviors_in_text(behavior_description)
            
            for trait, weight in vector.items():
                if weight > 0.3 and trait in self.personality_traits:
                    expected = self.personality_traits[trait]['behavior_tendency']
                    matched = False
                    for expected_behavior in expected:
                        for behavior_list in behaviors.values():
                            for b in behavior_list:
                                if expected_behavior in b['behavior']:
                                    matched = True
                                    break
                            if matched:
                                break
                        if matched:
                            break
                    
                    if not matched:
                        suggestions.append(f"基于{trait}性格，建议体现行为: {expected[:2]}")
        
        motivation = profile.get('core_motivations', [])
        if motivation:
            for m in motivation[:2]:
                if m in self._motivation_behavior_map:
                    expected_behaviors = self._motivation_behavior_map[m]
                    matched = False
                    for eb in expected_behaviors:
                        if eb in behavior_description:
                            matched = True
                            break
                    
                    if not matched:
                        warnings.append(f"动机'{m}'驱动下，行为可能不符合预期模式")
        
        check_result = {
            'character': character_name,
            'behavior': behavior_description,
            'valid': len(issues) == 0,
            'issues': issues,
            'warnings': warnings,
            'suggestions': suggestions,
            'timestamp': len(self.consistency_checks),
            'confidence': 'high' if len(issues) == 0 and len(warnings) == 0 else 'medium'
        }
        
        self.consistency_checks.append(check_result)
        
        if len(self._behavior_cache) > self._max_cache_size:
            keys_to_remove = list(self._behavior_cache.keys())[:100]
            for k in keys_to_remove:
                del self._behavior_cache[k]
        self._behavior_cache[cache_key] = check_result.copy()
        check_result.pop('cache_hit', None)
        
        return check_result
    
    def validate_consistency(self, character_name, new_content, old_content=""):
        """整体一致性校验"""
        if character_name not in self.character_profiles:
            return {'consistent': True}
        
        profile = self.character_profiles[character_name]
        issues = []
        warnings = []
        
        import re
        
        new_behaviors = self._analyze_behaviors_in_text(new_content)
        old_behaviors = self._analyze_behaviors_in_text(old_content) if old_content else {'emotional': [], 'action': [], 'physical': [], 'dialogue': [], 'cognitive': []}
        
        for trait in profile.get('personality', []):
            if trait in self.personality_traits:
                expected = self.personality_traits[trait]['behavior_tendency']
                old_matched = self._count_behavior_matches(old_behaviors, expected)
                new_matched = self._count_behavior_matches(new_behaviors, expected)
                
                if old_matched > 0 and new_matched == 0:
                    issues.append(f"角色{trait}特性在新内容中未体现")
                elif old_matched > 0 and new_matched < old_matched * 0.5:
                    warnings.append(f"角色{trait}特性表现强度下降")
        
        for fear in profile.get('fears', []):
            if fear in new_content and fear in old_content:
                fear_pattern = re.compile(fear)
                old_count = len(fear_pattern.findall(old_content))
                new_count = len(fear_pattern.findall(new_content))
                
                if old_count > 0 and new_count == 0:
                    warnings.append(f"角色恐惧'{fear}'在新内容中未体现")
        
        return {
            'consistent': len(issues) == 0,
            'issues': issues,
            'warnings': warnings,
            'character': character_name,
            'consistency_score': self._calculate_consistency_score(issues, warnings)
        }
    
    def _count_behavior_matches(self, behaviors, expected_keywords):
        """计算行为匹配数量"""
        count = 0
        for behavior_list in behaviors.values():
            for b in behavior_list:
                for keyword in expected_keywords:
                    if keyword in b['behavior']:
                        count += 1
                        break
        return count
    
    def _calculate_consistency_score(self, issues, warnings):
        """计算一致性评分"""
        base_score = 100
        base_score -= len(issues) * 15
        base_score -= len(warnings) * 5
        return max(0, min(100, base_score))
    
    def validate_cross_scene_consistency(self, character_name, scene_content, previous_scenes):
        """跨场景行为一致性校验"""
        if character_name not in self.character_profiles:
            return {'consistent': True, 'reason': '角色未注册'}
        
        profile = self.character_profiles[character_name]
        issues = []
        warnings = []
        
        scene_behaviors = self._analyze_behaviors_in_text(scene_content)
        
        for prev_scene in previous_scenes[-3:]:
            prev_behaviors = self._analyze_behaviors_in_text(prev_scene)
            
            for behavior_type in ['emotional', 'action', 'physical']:
                current_set = set(b['behavior'] for b in scene_behaviors.get(behavior_type, []))
                prev_set = set(b['behavior'] for b in prev_behaviors.get(behavior_type, []))
                
                if prev_set and current_set:
                    stability = len(current_set & prev_set) / len(prev_set | current_set)
                    if stability < 0.3:
                        warnings.append(f"{behavior_type}行为模式变化较大 (相似度: {stability:.2%})")
        
        for trait in profile.get('personality', [])[:3]:
            if trait in self.personality_traits:
                expected = self.personality_traits[trait]['behavior_tendency']
                matched_count = self._count_behavior_matches(scene_behaviors, expected)
                if matched_count == 0:
                    issues.append(f"场景中未体现{trait}性格特征")
        
        result = {
            'character': character_name,
            'consistent': len(issues) == 0,
            'issues': issues,
            'warnings': warnings,
            'cross_scene_score': self._calculate_consistency_score(issues, warnings)
        }
        self._cross_scene_checks.append(result)
        return result
    
    def detect_abnormal_behavior(self, character_name, behavior_description, context=""):
        """检测异常行为"""
        if character_name not in self.character_profiles:
            return {'abnormal': False, 'reason': '角色未注册'}
        
        profile = self.character_profiles[character_name]
        abnormal_indicators = []
        
        for fear in profile.get('fears', []):
            if fear in behavior_description:
                pattern = re.compile(f'[^不]*{fear}')
                matches = pattern.findall(behavior_description)
                for match in matches:
                    if not match.startswith('不'):
                        abnormal_indicators.append(f"面对恐惧'{fear}'时行为异常")
                        break
        
        if character_name in self._behavior_predictions:
            prediction = self._predict_behavior(character_name, context)
            if prediction.get('confidence') == 'high':
                predicted = set(prediction.get('predicted_behaviors', []))
                actual = set(self._analyze_behaviors_in_text(behavior_description).get('action', []))
                
                if predicted and actual:
                    deviation = len(actual - predicted) / len(predicted | actual)
                    if deviation > 0.7:
                        abnormal_indicators.append(f"行为偏离预测模式 (偏离度: {deviation:.2%})")
        
        is_abnormal = len(abnormal_indicators) > 0
        result = {
            'abnormal': is_abnormal,
            'character': character_name,
            'indicators': abnormal_indicators,
            'risk_level': 'high' if len(abnormal_indicators) > 2 else 'medium' if abnormal_indicators else 'low'
        }
        
        if is_abnormal:
            self._abnormal_behaviors.append(result)
        
        return result
    
    def update_behavior_history(self, character_name, behaviors):
        """更新行为历史"""
        if character_name not in self._behavior_predictions:
            self._behavior_predictions[character_name] = {'history': [], 'patterns': {}}
        
        self._behavior_predictions[character_name]['history'].append({
            'behaviors': behaviors,
            'timestamp': len(self._behavior_predictions[character_name]['history'])
        })
        
        if len(self._behavior_predictions[character_name]['history']) > 100:
            self._behavior_predictions[character_name]['history'] = \
                self._behavior_predictions[character_name]['history'][-50:]
    
    def get_behavior_summary(self, character_name=None):
        """获取行为校验摘要"""
        if character_name:
            checks = [c for c in self.consistency_checks if c.get('character') == character_name]
            cross_scene = [c for c in self._cross_scene_checks if c.get('character') == character_name]
            abnormal = [a for a in self._abnormal_behaviors if a.get('character') == character_name]
        else:
            checks = self.consistency_checks
            cross_scene = self._cross_scene_checks
            abnormal = self._abnormal_behaviors
        
        avg_score = 0
        if checks:
            scores = [self._calculate_consistency_score(c.get('issues', []), c.get('warnings', [])) for c in checks]
            avg_score = sum(scores) / len(scores)
        
        return {
            'total_checks': len(checks),
            'failed_checks': len([c for c in checks if not c.get('valid', True)]),
            'issues_count': sum(len(c.get('issues', [])) for c in checks),
            'warnings_count': sum(len(c.get('warnings', [])) for c in checks),
            'suggestions_count': sum(len(c.get('suggestions', [])) for c in checks),
            'cross_scene_checks': len(cross_scene),
            'cross_scene_failures': len([c for c in cross_scene if not c.get('consistent', True)]),
            'abnormal_behaviors': len(abnormal),
            'average_consistency_score': round(avg_score, 2),
            'registered_characters': len(self.character_profiles)
        }
    
    def get_personality_report(self, character_name):
        """获取角色性格分析报告"""
        if character_name not in self.character_profiles:
            return {'error': '角色未注册'}
        
        profile = self.character_profiles[character_name]
        vector = self._personality_vectors.get(character_name, {})
        
        sorted_traits = sorted(vector.items(), key=lambda x: x[1], reverse=True)[:5]
        
        predictions = self._predict_behavior(character_name, "")
        
        return {
            'character': character_name,
            'personality_traits': profile.get('personality', []),
            'dominant_traits': [t[0] for t in sorted_traits],
            'trait_vector': vector,
            'core_motivations': profile.get('core_motivations', []),
            'fears': profile.get('fears', []),
            'desires': profile.get('desires', []),
            'behavior_predictions': predictions,
            'consistency_score': self.get_behavior_summary(character_name).get('average_consistency_score', 100)
        }
    
    def reset(self):
        """重置校验器"""
        self.character_profiles = {}
        self.behavior_patterns = {}
        self.consistency_checks = []
        self._behavior_cache.clear()
        self._personality_vectors.clear()
        self._behavior_predictions.clear()
        self._cross_scene_checks.clear()
        self._abnormal_behaviors.clear()


