    def analyze_emotional_curve(self, text, chunk_size=500):
        """分析文本情感曲线"""
        import hashlib
        text_hash = hashlib.md5(text.encode('utf-8')).hexdigest()
        if text_hash in self._performance_cache:
            return self._performance_cache[text_hash]
        
        chunks = self._split_into_chunks(text, chunk_size)
        curve_data = []
        
        for i, chunk in enumerate(chunks):
            emotion_scores = self._analyze_chunk_emotions(chunk)
            overall_score = sum(emotion_scores.values()) / len(emotion_scores) if emotion_scores else 0
            
            curve_data.append({
                'position': i,
                'chunk_index': i,
                'text_preview': chunk[:50] + '...' if len(chunk) > 50 else chunk,
                'emotions': emotion_scores,
                'overall_intensity': overall_score,
                'dominant_emotion': max(emotion_scores, key=emotion_scores.get) if emotion_scores else 'neutral',
                'peak_emotion': max(emotion_scores.items(), key=lambda x: x[1])[0] if emotion_scores else None
            })
        
        curve_summary = {
            'total_chunks': len(chunks),
            'average_intensity': sum(d['overall_intensity'] for d in curve_data) / len(curve_data) if curve_data else 0,
            'peak_intensity': max(d['overall_intensity'] for d in curve_data) if curve_data else 0,
            'emotion_distribution': self._calculate_emotion_distribution(curve_data),
            'curve_data': curve_data
        }
        
        self._performance_cache[text_hash] = curve_summary
        return curve_summary
    
    def _split_into_chunks(self, text, chunk_size):
        """将文本分割为块"""
        chunks = []
        sentences = text.replace('。', '|').replace('！', '|').replace('？', '|').replace('\n', '|').split('|')
        
        current_chunk = ""
        for sentence in sentences:
            sentence = sentence.strip()
            if not sentence:
                continue
                
            if len(current_chunk) + len(sentence) <= chunk_size:
                current_chunk += sentence + "。"
            else:
                if current_chunk:
                    chunks.append(current_chunk)
                current_chunk = sentence + "。"
        
        if current_chunk:
            chunks.append(current_chunk)
        
        return chunks
    
    def _analyze_chunk_emotions(self, chunk):
        """分析单块文本的情感"""
        scores = {}
        
        for emotion, data in self._emotion_patterns.items():
            score = 0
            for keyword in data['keywords']:
                if keyword in chunk:
                    score += 1
                    if len(keyword) > 2:
                        score += 0.5
            
            if score > 0:
                normalized_score = min(score * data['intensity'] / 5, 1.0)
                scores[emotion] = normalized_score
        
        return scores
    
    def _calculate_emotion_distribution(self, curve_data):
        """计算情感分布"""
        distribution = {}
        
        for data in curve_data:
            dominant = data.get('dominant_emotion')
            if dominant and dominant != 'neutral':
                distribution[dominant] = distribution.get(dominant, 0) + 1
        
        total = sum(distribution.values())
        if total > 0:
            distribution = {k: v / total for k, v in distribution.items()}
        
        return distribution
    
    def get_curve_statistics(self, curve_data):
        """获取曲线统计信息"""
        if not curve_data or 'curve_data' not in curve_data:
            return {}
        
        data = curve_data['curve_data']
        intensities = [d['overall_intensity'] for d in data]
        
        return {
            'total_segments': len(data),
            'average_intensity': curve_data.get('average_intensity', 0),
            'peak_intensity': curve_data.get('peak_intensity', 0),
            'intensity_variance': self._calculate_variance(intensities),
            'rising_segments': len([i for i in range(1, len(data)) if data[i]['overall_intensity'] > data[i-1]['overall_intensity']]),
            'falling_segments': len([i for i in range(1, len(data)) if data[i]['overall_intensity'] < data[i-1]['overall_intensity']]),
            'stable_segments': len([i for i in range(1, len(data)) if data[i]['overall_intensity'] == data[i-1]['overall_intensity']])
        }
    
    def _calculate_variance(self, values):
        """计算方差"""
        if len(values) < 2:
            return 0
        mean = sum(values) / len(values)
        return sum((v - mean) ** 2 for v in values) / len(values)
    
    def generate_emotion_report(self, text):
        """生成情感分析报告"""
        curve_data = self.analyze_emotional_curve(text)
        stats = self.get_curve_statistics(curve_data)
        
        return {
            'curve_analysis': curve_data,
            'statistics': stats,
            'reading_suggestions': self._generate_reading_suggestions(curve_data, stats),
            'emotional_peaks': self._find_emotional_peaks(curve_data)
        }
    
    def _generate_reading_suggestions(self, curve_data, stats):
        """生成阅读建议"""
        suggestions = []
        
        if stats.get('average_intensity', 0) > 0.6:
            suggestions.append("本文情感强度较高，适合一次性阅读以获得完整体验")
        
        if stats.get('rising_segments', 0) > stats.get('falling_segments', 0):
            suggestions.append("情感曲线呈上升趋势，高潮将在后期出现")
        else:
            suggestions.append("情感波动较大，注意节奏变化")
        
        return suggestions
    
    def _find_emotional_peaks(self, curve_data):
        """找出情感高峰点"""
        if not curve_data or 'curve_data' not in curve_data:
            return []
        
        data = curve_data['curve_data']
        peaks = []
        
        for i, point in enumerate(data):
            if point['overall_intensity'] > self._emotion_patterns.get(point.get('dominant_emotion'), {}).get('intensity', 0.7):
                peaks.append({
                    'position': i,
                    'intensity': point['overall_intensity'],
                    'dominant_emotion': point['dominant_emotion'],
                    'preview': point['text_preview']
                })
        
        return peaks[:10]
    
    def reset(self):
        """重置分析器"""
        self.emotional_data = []
        self.chapter_curves = {}
        self._performance_cache = {}


