    def update_all_from_content(self, content, file_path=None, chapter_info=None):
        """使用综合AI分析更新所有追踪器"""
        print(f"[DEBUG] NarrativeConsistencyManager.update_all_from_content 开始执行")
        print(f"[DEBUG] 内容长度: {len(content)}")
        print(f"[DEBUG] 文件路径: {file_path}")
        print(f"[DEBUG] 章节信息: {chapter_info}")

        self.narrative_log.append({
            "action": "update_all_from_content",
            "content_length": len(content),
            "use_ai": self.use_ai_tracking,
            "file_path": file_path,
            "chapter_info": chapter_info,
            "timestamp": len(self.narrative_log)
        })

        if self.use_ai_tracking:
            print(f"[DEBUG] 使用综合AI分析更新所有追踪器")
            result = self.analyze_all_trackers_with_ai(content, file_path=file_path, chapter_info=chapter_info)
            if result:
                print(f"[DEBUG] 综合分析成功完成")
                return True
            else:
                print(f"[DEBUG] 综合分析失败，尝试备用方案")
                return self._fallback_update_all(content)
        else:
            print(f"[DEBUG] AI未启用，使用各个追踪器的正则备用方案")
            return self._fallback_update_all(content)

    def _fallback_update_all(self, content):
        """备用方案：逐个调用各个追踪器的正则分析"""
        print(f"[DEBUG] 开始备用方案更新所有追踪器")

        self.spatial_tracker.update_from_content(content, use_ai_if_available=False)
        self.ai_character_tracker.update_from_content(content, use_ai_if_available=False)
        self.relationship_tracker.update_from_content(content, use_ai_if_available=False)
        self.event_tracker.update_from_content(content, use_ai_if_available=False)
        self.quest_tracker.update_from_content(content, use_ai_if_available=False)
        self.branch_tracker.update_from_content(content, use_ai_if_available=False)
        self.timeline_tracker.update_from_content(content, use_ai_if_available=False)

        print(f"[DEBUG] 备用方案更新完成")
        return True

    def check_all_consistencies(self, new_content):
        """检查所有一致性"""
        issues = []

        issues.extend(self._check_spatial_consistency(new_content))
        issues.extend(self._check_character_consistency(new_content))
        issues.extend(self._check_relationship_consistency(new_content))
        issues.extend(self._check_event_consistency(new_content))
        issues.extend(self._check_quest_consistency(new_content))
        issues.extend(self._check_time_consistency(new_content))
        issues.extend(self._check_duplicate_content(new_content))

        self.consistency_issues = issues
        return issues

    def _check_spatial_consistency(self, content):
        """检查空间一致性"""
        issues = []

        import re
        location_patterns = [
            r'在([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)',
            r'来到([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)',
            r'前往([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)',
            r'回到([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)',
            r'走出([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)',
            r'进入([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)'
        ]

        locations_found = []
        for pattern in location_patterns:
            matches = re.findall(pattern, content)
            locations_found.extend(matches)

        for char_name, location_data in self.spatial_tracker.character_locations.items():
            if location_data:
                last_location = location_data[-1].get("location", "")

                for new_location in locations_found:
                    if last_location and new_location != last_location:
                        distance_keywords = ['很远', '距离', '千里', '万里', '几个小时', '几天']
                        has_travel = any(kw in content for kw in distance_keywords)

                        if not has_travel and new_location not in last_location and last_location not in new_location:
                            issues.append({
                                "type": "spatial_inconsistency",
                                "severity": "medium",
                                "character": char_name,
                                "previous_location": last_location,
                                "claimed_location": new_location,
                                "description": f"角色'{char_name}'声称在'{new_location}'，但之前记录在'{last_location}'，且没有合理的移动描述"
                            })

        scene_patterns = [
            r'([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)的([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)',
            r'([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)里',
            r'([^\\s，,。？！!?；:："\'\'【】()\\[\\]]+)中'
        ]
        scenes_found = []
        for pattern in scene_patterns:
            matches = re.findall(pattern, content)
            scenes_found.extend([f"{m[0]}的{m[1]}" if len(m) > 1 else m[0] for m in matches])

        return issues

    def _check_character_consistency(self, content):
        """检查角色一致性"""
        issues = []

        import re

        for char_name in self.relationship_tracker.characters:
            if char_name in content:
                char_data = self.relationship_tracker.characters.get(char_name, {})
                attributes = char_data.get("attributes", [])
                skills = char_data.get("skills", [])

                ability_patterns = []
                for skill in skills:
                    if len(skill) > 2:
                        ability_patterns.append(skill)

                for skill in ability_patterns:
                    if skill in content:
                        if skill not in content.lower():
                            continue

                # 检查角色性格一致性
                if isinstance(char_data, dict):
                    attributes = char_data.get("attributes", {})
                    # 处理attributes可能是列表或字典的情况
                    if isinstance(attributes, list):
                        # 如果是列表，尝试从中提取性格信息
                        personality = ""
                        for attr in attributes:
                            if isinstance(attr, dict) and attr.get("name") == "personality":
                                personality = attr.get("value", "")
                                break
                    else:  # 假设是字典
                        personality = attributes.get("personality", "")
                    
                    if personality:
                        # 提取内容中与该角色相关的行为描述
                        char_behavior_pattern = rf'{char_name}([^\u4e00-\u9fff]*[\u4e00-\u9fff]{{1,20}})(了|着|过)?'
                        behaviors = re.findall(char_behavior_pattern, content)
                        
                        for behavior in behaviors:
                            behavior_desc = behavior[0].strip()
                            if not behavior_desc:
                                continue
                                
                            # 检查行为是否与性格相符
                            conflicting_patterns = []
                            if "温和" in personality:
                                conflicting_patterns.extend(["愤怒", "暴怒", "发火", "咆哮", "暴躁", "呵斥"])
                            if "勇敢" in personality:
                                conflicting_patterns.extend(["害怕", "恐惧", "退缩", "逃避"])
                            if "诚实" in personality:
                                conflicting_patterns.extend(["撒谎", "欺骗", "隐瞒", "狡诈"])
                            if "自私" in personality:
                                conflicting_patterns.extend(["无私", "奉献", "牺牲", "慷慨"])
                            
                            for pattern in conflicting_patterns:
                                if pattern in behavior_desc:
                                    issues.append({
                                        "type": "character_personality_inconsistency",
                                        "severity": "medium",
                                        "character": char_name,
                                        "personality": personality,
                                        "behavior": behavior_desc,
                                        "description": f"角色'{char_name}'的行为'{behavior_desc}'与其性格'{personality}'不符"
                                    })
                
                # 检查角色行为动机合理性
                action_patterns = [
                    rf'{char_name}决定(.+?)[。！？]',
                    rf'{char_name}想要(.+?)[。！？]',
                    rf'{char_name}准备(.+?)[。！？]',
                    rf'{char_name}开始(.+?)[。！？]'
                ]
                
                for pattern in action_patterns:
                    matches = re.findall(pattern, content)
                    for match in matches:
                        action = match.strip()
                        if action:
                            # 检查行为是否有合理动机
                            if "因为" not in action and "为了" not in action and "所以" not in action:
                                # 查找上下文是否有动机说明
                                context_start = max(0, content.find(action) - 100)
                                context_end = min(len(content), content.find(action) + 100)
                                context = content[context_start:context_end]
                                
                                if not any(keyword in context for keyword in ["因为", "为了", "所以", "由于", "原因"]):
                                    issues.append({
                                        "type": "character_motivation_issue",
                                        "severity": "low",
                                        "character": char_name,
                                        "action": action,
                                        "description": f"角色'{char_name}'的行为'{action}'缺少明确的动机说明"
                                    })

        return issues

    def _check_relationship_consistency(self, content):
        """检查角色关系一致性"""
        issues = []

        if self.relationship_tracker.use_ai and self.relationship_tracker.api_key:
            ai_result = self.relationship_tracker.analyze_content_with_ai(content)
            if ai_result and "consistency_issues" in ai_result:
                for issue in ai_result["consistency_issues"]:
                    issues.append({
                        "type": "relationship_inconsistency",
                        "severity": issue.get("severity", "medium"),
                        "description": issue.get("issue", "")
                    })
                return issues

        import re

        relationship_keywords = {
            'friend': ['朋友', '好友', '伙伴', '兄弟', '姐妹'],
            'enemy': ['敌人', '对手', '仇人', '死对头'],
            'lover': ['恋人', '爱人', '情侣', '心上人'],
            'family': ['父亲', '母亲', '儿子', '女儿', '兄弟', '姐妹', '家人']
        }

        for rel_key in self.relationship_tracker.relationships.keys():
            # 分割关系键获取两个角色名
            if '|' in rel_key:
                char1, char2 = rel_key.split('|')
            else:
                # 如果键格式不正确，跳过
                continue
            current_rel = self.relationship_tracker.get_relationship(char1, char2)
            if current_rel:
                rel_type = current_rel.get("type", "")
                intensity = current_rel.get("intensity", 5)

                for new_rel_type, keywords in relationship_keywords.items():
                    for keyword in keywords:
                        if keyword in content and char1 in content and char2 in content:
                            if rel_type != new_rel_type and abs(intensity - 5) > 3:
                                issues.append({
                                    "type": "relationship_inconsistency",
                                    "severity": "medium",
                                    "characters": [char1, char2],
                                    "previous_type": rel_type,
                                    "new_type": new_rel_type,
                                    "description": f"角色'{char1}'和'{char2}'的关系从'{rel_type}'变为'{new_rel_type}'，需确认是否合理"
                                })

        return issues

    def _check_event_consistency(self, content):
        """检查事件一致性"""
        issues = []

        import re

        event_keywords = ['然后', '之后', '于是', '接着', '随后', '就在这时', '突然']
        event_positions = []
        for keyword in event_keywords:
            positions = [(m.start(), keyword) for m in re.finditer(keyword, content)]
            event_positions.extend(positions)

        event_positions.sort(key=lambda x: x[0])

        for event_id, event_data in self.event_tracker.events.items():
            event_time = event_data.get("time", "")
            if event_time:
                time_indicators = ['上午', '下午', '晚上', '清晨', '深夜', '凌晨', '中午']
                for indicator in time_indicators:
                    if indicator in event_time and indicator in content:
                        event_pos = content.find(indicator)
                        for pos, keyword in event_positions:
                            if abs(event_pos - pos) < 100:
                                break

        return issues

    def _check_quest_consistency(self, content):
        """检查任务一致性"""
        issues = []

        import re

        quest_keywords = ['目标', '任务', '目的', '计划', '需要', '必须', '要']
        for quest_id, quest_data in self.quest_tracker.main_quests.items():
            if quest_data.get("status") == "active":
                quest_objectives = quest_data.get("objectives", [])
                for objective in quest_objectives:
                    if objective.get("status") == "completed":
                        if objective.get("description", "") in content:
                            pass

        for quest_id, quest_data in self.quest_tracker.side_quests.items():
            if quest_data.get("status") == "active":
                pass

        return issues

    def _check_time_consistency(self, content):
        """检查时间一致性"""
        issues = []
        
        time_issues = self.timeline_tracker.check_time_consistency(content)
        issues.extend(time_issues)
        
        return issues

    def fix_consistency_issues(self, original_content, issues):
        """根据检测到的问题修正内容"""
        if not issues:
            return original_content
            
        fixed_content = original_content
        
        print(f"[DEBUG] 开始修正内容，共检测到 {len(issues)} 个问题")
        
        # 按问题严重程度排序，优先处理严重问题
        sorted_issues = sorted(issues, key=lambda x: {'high': 0, 'medium': 1, 'low': 2}.get(x.get('severity', 'medium'), 1))
        
        for issue in sorted_issues:
            issue_type = issue.get('type', '')
            description = issue.get('description', '')
            
            print(f"[DEBUG] 处理问题: {description}")
            
            # 根据不同类型的问题进行修正
            if issue_type == 'spatial_inconsistency':
                # 空间一致性问题修正
                character = issue.get('character', '')
                previous_location = issue.get('previous_location', '')
                claimed_location = issue.get('claimed_location', '')
                
                if character and previous_location and claimed_location:
                    # 添加移动描述
                    if f"{character}在{claimed_location}" in fixed_content:
                        fixed_content = fixed_content.replace(
                            f"{character}在{claimed_location}",
                            f"{character}从{previous_location}来到{claimed_location}"
                        )
                    elif f"{character}来到{claimed_location}" in fixed_content:
                        fixed_content = fixed_content.replace(
                            f"{character}来到{claimed_location}",
                            f"{character}从{previous_location}来到{claimed_location}"
                        )
            
            elif issue_type == 'time_inconsistency':
                # 时间一致性问题修正
                time_change = issue.get('description', '')
                if '时间从' in time_change and '跳转到' in time_change:
                    # 提取时间信息
                    import re
                    time_pattern = r'时间从[\'"]([^\'\"]+)[\'\"]跳转到[\'"]([^\'\"]+)[\'\"]'
                    match = re.search(time_pattern, time_change)
                    if match:
                        old_time = match.group(1)
                        new_time = match.group(2)
                        
                        # 添加时间过渡描述
                        if f"{new_time}" in fixed_content:
                            fixed_content = fixed_content.replace(
                                f"{new_time}",
                                f"过了一会儿，到了{new_time}"
                            )
            
            elif issue_type == 'character_personality_inconsistency':
                # 角色性格一致性问题修正
                character = issue.get('character', '')
                personality = issue.get('personality', '')
                behavior = issue.get('behavior', '')
                
                if character and personality and behavior:
                    # 调整行为描述使其与性格相符
                    if '温和' in personality and any(word in behavior for word in ['愤怒', '暴怒', '发火', '咆哮']):
                        # 将激烈行为调整为温和行为
                        behavior_patterns = {
                            '愤怒': '有些不高兴',
                            '暴怒': '有些生气',
                            '发火': '皱了皱眉',
                            '咆哮': '提高了声音'
                        }
                        for old, new in behavior_patterns.items():
                            if old in fixed_content:
                                fixed_content = fixed_content.replace(old, new)
            
            elif issue_type == 'character_motivation_issue':
                # 角色行为动机问题修正
                character = issue.get('character', '')
                action = issue.get('action', '')
                
                if character and action:
                    # 添加动机说明
                    motivation_phrases = {
                        '决定': '因为某种原因决定',
                        '想要': '为了实现某个目标想要',
                        '准备': '考虑到当前情况准备',
                        '开始': '出于某种考虑开始'
                    }
                    
                    for verb, phrase in motivation_phrases.items():
                        pattern = rf'{character}{verb}({action})'
                        import re
                        match = re.search(pattern, fixed_content)
                        if match:
                            fixed_content = re.sub(
                                pattern, 
                                f'{character}{phrase}{action}', 
                                fixed_content
                            )
                            break
        
        print(f"[DEBUG] 内容修正完成")
        return fixed_content

    def _check_duplicate_content(self, content):
        """检查重复内容"""
        issues = []
        
        import re
        from collections import Counter
        
        sentences = re.split(r'[。！？]', content)
        sentences = [s.strip() for s in sentences if s.strip()]
        
        if len(sentences) > 5:
            sentence_counter = Counter(sentences)
            for sentence, count in sentence_counter.items():
                if count > 1 and len(sentence) > 10:
                    issues.append({
                        "type": "duplicate_content",
                        "severity": "high",
                        "description": f"发现重复句子: '{sentence[:30]}...' 出现了 {count} 次",
                        "suggestion": "删除重复内容，保持文本的独特性和可读性"
                    })
        
        paragraph_issues = self._check_paragraph_duplicates(content)
        issues.extend(paragraph_issues)
        
        return issues
    
    def _check_paragraph_duplicates(self, content):
        """检查段落重复"""
        issues = []
        
        import re
        
        paragraphs = content.split('\n\n')
        paragraphs = [p.strip() for p in paragraphs if len(p.strip()) > 50]
        
        for i, para1 in enumerate(paragraphs):
            for j, para2 in enumerate(paragraphs):
                if i < j:
                    similarity = self._calculate_text_similarity(para1, para2)
                    if similarity > 0.8:
                        issues.append({
                            "type": "duplicate_paragraph",
                            "severity": "high",
                            "description": f"第 {i+1} 段和第 {j+1} 段内容高度重复 (相似度: {similarity:.2%})",
                            "suggestion": "合并或重写重复段落，确保内容的多样性"
                        })
        
        return issues
    
    def _calculate_text_similarity(self, text1, text2):
        """计算文本相似度"""
        try:
            import jieba
            
            words1 = set(jieba.cut(text1))
            words2 = set(jieba.cut(text2))
            
            if not words1 or not words2:
                return 0.0
            
            intersection = words1 & words2
            union = words1 | words2
            
            return len(intersection) / len(union) if union else 0.0
        except ImportError:
            # jieba模块不存在时使用简单的字符相似度计算作为备用方案
            print("[WARNING] jieba模块未安装，使用字符级相似度计算作为备用方案")
            set1 = set(text1)
            set2 = set(text2)
            if not set1 or not set2:
                return 0.0
            intersection = set1 & set2
            union = set1 | set2
            return len(intersection) / len(union) if union else 0.0

    def get_comprehensive_summary(self):
        """获取综合摘要"""
        return {
            "spatial": self.spatial_tracker.get_spatial_summary(),
            "characters": {
                "total": len(self.relationship_tracker.characters),
                "relationships": len(self.relationship_tracker.relationships)
            },
            "relationships": self.relationship_tracker.get_relationship_summary(),
            "events": self.event_tracker.get_event_summary(),
            "quests": self.quest_tracker.get_quest_summary(),
            "branches": self.branch_tracker.get_branch_summary(),
            "timeline": self.timeline_tracker.get_timeline_summary(),
            "consistency_issues": len(self.consistency_issues),
            "narrative_log": len(self.narrative_log)
        }
    
    def get_mentioned_content_summary(self, existing_content, max_characters=30, max_events=20):
        """
        提取已提及内容摘要 - 用于防止续写时重复提及已有内容
        
        Args:
            existing_content: 已有章节内容
            max_characters: 最大角色数量
            max_events: 最大事件数量
        
        Returns:
            dict: 包含已提及角色、已发生事件等信息的字典
        """
        mentioned_characters = []
        mentioned_events = []
        mentioned_locations = []
        mentioned_objects = []
        
        try:
            if hasattr(self.relationship_tracker, 'characters') and self.relationship_tracker.characters:
                for char_name in list(self.relationship_tracker.characters.keys())[:max_characters]:
                    char_info = self.relationship_tracker.characters.get(char_name, {})
                    if char_info:
                        mentioned_characters.append({
                            "name": char_name,
                            "category": char_info.get("category", "未知"),
                            "first_appearance": char_info.get("first_appearance", "未知"),
                            "last_mention": char_info.get("last_mention", "未知")
                        })
        except Exception as e:
            print(f"[DEBUG] 提取已提及角色失败: {e}")
        
        try:
            if hasattr(self.event_tracker, 'events') and self.event_tracker.events:
                for event_id, event_data in list(self.event_tracker.events.items())[:max_events]:
                    if isinstance(event_data, dict) and 'data' in event_data:
                        event_info = event_data['data']
                        mentioned_events.append({
                            "id": event_id,
                            "description": event_info.get("description", "未知事件")[:100],
                            "time": event_info.get("time", "未知时间"),
                            "importance": event_info.get("importance", "普通")
                        })
        except Exception as e:
            print(f"[DEBUG] 提取已发生事件失败: {e}")
        
        try:
            if hasattr(self.spatial_tracker, 'character_locations') and self.spatial_tracker.character_locations:
                for char_name, loc_list in self.spatial_tracker.character_locations.items():
                    if loc_list:
                        latest_loc = loc_list[-1] if isinstance(loc_list, list) else loc_list
                        if isinstance(latest_loc, dict):
                            mentioned_locations.append({
                                "character": char_name,
                                "location": latest_loc.get("location", "未知位置")
                            })
        except Exception as e:
            print(f"[DEBUG] 提取已提及位置失败: {e}")
        
        return {
            "mentioned_characters": mentioned_characters,
            "mentioned_events": mentioned_events,
            "mentioned_locations": mentioned_locations,
            "mentioned_objects": mentioned_objects,
            "total_characters": len(mentioned_characters),
            "total_events": len(mentioned_events),
            "total_locations": len(mentioned_locations)
        }

