# 配置管理类 - 用于保存和读取API Key
class ConfigManager:
    def __init__(self):
        self.config = configparser.RawConfigParser(strict=False)
        self.config_file = "novel_generator_config.ini"
        self.load_config()
    
    def load_config(self):
        """加载配置文件"""
        if os.path.exists(self.config_file):
            try:
                # First try UTF-8 encoding
                self.config.read(self.config_file, encoding='utf-8')
            except UnicodeDecodeError:
                # If UTF-8 fails, try GBK encoding (common for Chinese files on Windows)
                self.config.read(self.config_file, encoding='gbk')
            except Exception:
                pass
    
    def save_config(self):
        """保存配置到文件"""
        with open(self.config_file, 'w', encoding='utf-8') as f:
            self.config.write(f)
    
    def get_api_key(self):
        """获取保存的API Key"""
        if 'API' in self.config and 'key' in self.config['API']:
            return self.config['API']['key']
        return None
    
    def save_api_key(self, api_key):
        """保存API Key"""
        if 'API' not in self.config:
            self.config['API'] = {}
        self.config['API']['key'] = api_key
        self.save_config()
    
    def get_background(self):
        """获取背景设置"""
        if 'BACKGROUND' in self.config:
            return dict(self.config['BACKGROUND'])
        return {}
    
    def save_background(self, background_type, color=None, image_path=None):
        """保存背景设置"""
        if 'BACKGROUND' not in self.config:
            self.config['BACKGROUND'] = {}
        
        self.config['BACKGROUND']['type'] = background_type
        if color:
            self.config['BACKGROUND']['color'] = color
        if image_path:
            self.config['BACKGROUND']['image_path'] = image_path
        
        self.save_config()
        
    def get_prompt_templates(self):
        """获取提示词模板"""
        if 'PROMPT_TEMPLATES' in self.config:
            return dict(self.config['PROMPT_TEMPLATES'])
        return {}
    
    def save_prompt_template(self, template_name, template_content):
        """保存提示词模板"""
        if 'PROMPT_TEMPLATES' not in self.config:
            self.config['PROMPT_TEMPLATES'] = {}
        self.config['PROMPT_TEMPLATES'][template_name] = template_content
        self.save_config()
    
    def delete_prompt_template(self, template_name):
        """删除提示词模板"""
        if 'PROMPT_TEMPLATES' in self.config and template_name in self.config['PROMPT_TEMPLATES']:
            del self.config['PROMPT_TEMPLATES'][template_name]
            self.save_config()
    
    def get_user_preferences(self):
        """获取用户偏好设置"""
        if 'USER_PREFERENCES' in self.config:
            return dict(self.config['USER_PREFERENCES'])
        return {}
    
    def save_user_preference(self, preference_name, preference_value):
        """保存用户偏好设置"""
        if 'USER_PREFERENCES' not in self.config:
            self.config['USER_PREFERENCES'] = {}
        self.config['USER_PREFERENCES'][preference_name] = preference_value
        self.save_config()
    
    def get_generation_history(self):
        """获取生成历史记录"""
        if 'GENERATION_HISTORY' in self.config:
            return dict(self.config['GENERATION_HISTORY'])
        return {}
    
    def save_generation_history(self, history_id, history_content):
        """保存生成历史记录"""
        if 'GENERATION_HISTORY' not in self.config:
            self.config['GENERATION_HISTORY'] = {}
        safe_history_id = history_id.replace(':', '-').replace(' ', '_')
        self.config['GENERATION_HISTORY'][safe_history_id] = history_content
        self.save_config()
    
    def delete_generation_history(self, history_id):
        """删除生成历史记录"""
        safe_history_id = history_id.replace(':', '-').replace(' ', '_')
        if 'GENERATION_HISTORY' in self.config and safe_history_id in self.config['GENERATION_HISTORY']:
            del self.config['GENERATION_HISTORY'][safe_history_id]
            self.save_config()
    
    def get_dialog_backgrounds(self):
        """获取弹窗背景设置"""
        if 'DIALOG_BACKGROUNDS' in self.config:
            return dict(self.config['DIALOG_BACKGROUNDS'])
        return {}
    
    def save_dialog_backgrounds(self, dialog_backgrounds):
        """保存弹窗背景设置"""
        if 'DIALOG_BACKGROUNDS' not in self.config:
            self.config['DIALOG_BACKGROUNDS'] = {}
        
        for key, value in dialog_backgrounds.items():
            if isinstance(value, dict):
                serialized = f"{value.get('type', '')}|{value.get('value', '')}"
                self.config['DIALOG_BACKGROUNDS'][key] = serialized
        
        self.save_config()
    
    def save_dialog_background(self, dialog_key, bg_type, value):
        """保存单个弹窗的背景设置"""
        if 'DIALOG_BACKGROUNDS' not in self.config:
            self.config['DIALOG_BACKGROUNDS'] = {}
        
        self.config['DIALOG_BACKGROUNDS'][dialog_key] = f"{bg_type}|{value}"
        self.save_config()
    
    def clear_dialog_background(self, dialog_key):
        """清除指定弹窗的背景设置"""
        if 'DIALOG_BACKGROUNDS' in self.config and dialog_key in self.config['DIALOG_BACKGROUNDS']:
            del self.config['DIALOG_BACKGROUNDS'][dialog_key]
            self.save_config()
    
    def clear_all_dialog_backgrounds(self):
        """清除所有弹窗背景设置"""
        if 'DIALOG_BACKGROUNDS' in self.config:
            del self.config['DIALOG_BACKGROUNDS']
            self.save_config()
    
    def clear_generation_history(self):
        """清空生成历史记录"""
        if 'GENERATION_HISTORY' in self.config:
            del self.config['GENERATION_HISTORY']
            self.save_config()
    
    def save_workspace_state(self, state_data):
        """保存工作区状态（自动保存功能）"""
        if 'WORKSPACE' not in self.config:
            self.config['WORKSPACE'] = {}
        
        for key, value in state_data.items():
            self.config['WORKSPACE'][key] = str(value)
        
        self.save_config()
    
    def load_workspace_state(self):
        """加载工作区状态"""
        if 'WORKSPACE' in self.config:
            return dict(self.config['WORKSPACE'])
        return {}
    
    def clear_workspace_state(self):
        """清空工作区状态"""
        if 'WORKSPACE' in self.config:
            del self.config['WORKSPACE']
            self.save_config()
    
    def get_last_save_time(self):
        """获取上次保存时间"""
        if 'WORKSPACE' in self.config and 'save_time' in self.config['WORKSPACE']:
            return self.config['WORKSPACE']['save_time']
        return None
    
    def get_fine_tune_settings(self):
        """获取微调模式设置"""
        if 'FINE_TUNE' in self.config:
            return {
                'dialogue': int(self.config['FINE_TUNE'].get('dialogue', 5)),
                'inner': int(self.config['FINE_TUNE'].get('inner', 5)),
                'env': int(self.config['FINE_TUNE'].get('env', 5)),
                'pace': int(self.config['FINE_TUNE'].get('pace', 5)),
                'specific': self.config['FINE_TUNE'].get('specific', '')
            }
        return {
            'dialogue': 5,
            'inner': 5,
            'env': 5,
            'pace': 5,
            'specific': ''
        }
    
    def save_fine_tune_settings(self, dialogue, inner, env, pace, specific):
        """保存微调模式设置"""
        if 'FINE_TUNE' not in self.config:
            self.config['FINE_TUNE'] = {}
        
        self.config['FINE_TUNE']['dialogue'] = str(dialogue)
        self.config['FINE_TUNE']['inner'] = str(inner)
        self.config['FINE_TUNE']['env'] = str(env)
        self.config['FINE_TUNE']['pace'] = str(pace)
        self.config['FINE_TUNE']['specific'] = specific
        
        self.save_config()
    
    def get_rewrite_custom_requirement(self):
        """获取自定义改写要求"""
        if 'REWRITE' in self.config and 'custom_requirement' in self.config['REWRITE']:
            return self.config['REWRITE']['custom_requirement']
        return None
    
    def save_rewrite_custom_requirement(self, custom_requirement):
        """保存自定义改写要求"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['custom_requirement'] = custom_requirement
        self.save_config()
    
    def get_rewrite_next_chapter(self):
        """获取下一章开头"""
        if 'REWRITE' in self.config and 'next_chapter' in self.config['REWRITE']:
            return self.config['REWRITE']['next_chapter']
        return None
    
    def save_rewrite_next_chapter(self, next_chapter):
        """保存下一章开头"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['next_chapter'] = next_chapter
        self.save_config()
    
    def get_rewrite_mode(self):
        """获取改写模式"""
        if 'REWRITE' in self.config and 'rewrite_mode' in self.config['REWRITE']:
            return self.config['REWRITE']['rewrite_mode']
        return "色情改写"  # 默认为色情改写
    
    def save_rewrite_mode(self, rewrite_mode):
        """保存改写模式"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['rewrite_mode'] = rewrite_mode
        self.save_config()
    
    def get_rewrite_style(self):
        """获取改写风格"""
        if 'REWRITE' in self.config and 'style' in self.config['REWRITE']:
            return self.config['REWRITE']['style']
        return "色情"  # 默认为色情
    
    def save_rewrite_style(self, style):
        """保存改写风格"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['style'] = style
        self.save_config()
    
    def get_rewrite_direction(self):
        """获取改写方向"""
        if 'REWRITE' in self.config and 'direction' in self.config['REWRITE']:
            return self.config['REWRITE']['direction']
        return "色情描写"  # 默认为色情描写
    
    def save_rewrite_direction(self, direction):
        """保存改写方向"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['direction'] = direction
        self.save_config()
    
    def get_rewrite_input_content(self):
        """获取待改写内容"""
        if 'REWRITE' in self.config and 'input_content' in self.config['REWRITE']:
            return self.config['REWRITE']['input_content']
        return None
    
    def save_rewrite_input_content(self, input_content):
        """保存待改写内容"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['input_content'] = input_content
        self.save_config()
    
    def get_rewrite_content(self):
        """获取已生成的改写内容"""
        if 'REWRITE' in self.config and 'content' in self.config['REWRITE']:
            return self.config['REWRITE']['content']
        return None
    
    def save_rewrite_content(self, content):
        """保存已生成的改写内容"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        self.config['REWRITE']['content'] = content
        self.save_config()
    
    def get_rewrite_existing_chapters(self):
        """获取改写已有章节文件列表"""
        if 'REWRITE' in self.config and 'existing_chapters' in self.config['REWRITE']:
            chapters_str = self.config['REWRITE']['existing_chapters']
            if chapters_str:
                # 使用换行符作为分隔符，避免与文件路径中的字符冲突
                return chapters_str.split('\n')
        return []
    
    def save_rewrite_existing_chapters(self, chapters_list):
        """保存改写已有章节文件列表"""
        if 'REWRITE' not in self.config:
            self.config['REWRITE'] = {}
        # 使用换行符作为分隔符，避免与文件路径中的字符冲突
        self.config['REWRITE']['existing_chapters'] = '\n'.join(chapters_list)
        self.save_config()
    
    def get_name_generation_settings(self):
        """获取名字生成设置"""
        if 'NAME_GENERATION' in self.config:
            return dict(self.config['NAME_GENERATION'])
        return {}
    
    def set_name_generation_settings(self, settings):
        """保存名字生成设置"""
        if 'NAME_GENERATION' not in self.config:
            self.config['NAME_GENERATION'] = {}
        
        for key, value in settings.items():
            self.config['NAME_GENERATION'][key] = str(value)
        
        self.save_config()

# 文件管理类
class FileManager:
    def __init__(self):
        self.outline_dir = "outlines"
        self.detailed_outline_dir = "detailed_outlines"
        self.chapters_dir = "chapters"
        self.packages_dir = "packages"
        self.extracted_content_dir = "extracted_content"
        self.backgrounds_dir = "backgrounds"
        
        # 创建必要的目录
        for directory in [self.outline_dir, self.detailed_outline_dir, 
                         self.chapters_dir, self.packages_dir, 
                         self.extracted_content_dir, self.backgrounds_dir]:
            if not os.path.exists(directory):
                os.makedirs(directory)
    
    def get_files_in_dir(self, directory):
        """获取目录下的所有文件"""
        if not os.path.exists(directory):
            return []
        return [f for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]
    
    def save_file(self, directory, filename, content):
        """保存文件到指定目录"""
        filepath = os.path.join(directory, filename)
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(content)
        return filepath
    
    def load_file(self, filepath):
        """加载文件内容"""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                return f.read()
        except:
            return ""
    
    def get_file_content(self, directory, filename):
        """获取指定目录下文件的内容"""
        filepath = os.path.join(directory, filename)
        return self.load_file(filepath)
    
    def get_file_preview(self, directory, filename, max_length=5000):
        """获取文件预览"""
        content = self.get_file_content(directory, filename)
        if len(content) > max_length:
            return content[:max_length] + "..."
        return content
    
    def get_background_images(self):
        """获取背景图片"""
        if os.path.exists(self.backgrounds_dir):
            return [f for f in os.listdir(self.backgrounds_dir) 
                   if f.lower().endswith(('.png', '.jpg', '.jpeg', '.gif', '.bmp'))]
        return []

class AIHumanizer:
    """
    AI痕迹抹除与人性化优化引擎
    专门用于消除AI生成内容中的机械痕迹，使其达到大神级人类作者的写作水准
    通过专业AI检测工具检验，同时让人类读者认为是人类作者的作品
    """
    
    # 通用的AI痕迹规避规则（适用于所有生成任务）
    DENOISE_PROMPT = """
    ## ⚠️⚠️⚠️ AI痕迹规避铁律（必须严格遵守）⚠️⚠️⚠️
    
    **【禁止】连续否定列举句式**：
    ❌ 绝对禁止"不是A，不是B，是C"这种连续否定句式
    ❌ 绝对禁止"不是A，而是B"这种对比句式
    ❌ 绝对禁止"不是...不是...是..."这种多重否定
    ❌ 绝对禁止"不是A，是B"这种对比句式
    
    **【禁止】滥用"——"破折号**：
    ❌ 绝对禁止用"——"插入解释、说明、补充内容
    ❌ 绝对禁止"内容——解释——内容"这种格式
    ✅ "——"只能用于：①表示声音延长 ②表示语意转折（不能插入解释）
    
    **【禁止】其他AI特征**：
    ❌ 绝对禁止"首先，其次，再次，最后"等机械过渡词
    ❌ 绝对禁止"第一，第二，第三，第四，第五"等列举格式
    ❌ 绝对禁止"也就是说"、"换句话说"、"通俗地说"等过度解释
    ❌ 绝对禁止"然而，但是，所以，因此"等机械转折词开头
    ❌ 绝对禁止"他心想"、"她感到"、"他知道"等直白心理描写
    ❌ 绝对禁止"众所周知"、"可想而知"、"不言而喻"等套话
    
    **【禁止】非人性化写作特征**：
    ❌ 绝对禁止居高临下的说教语气（如"你应该"、"你必须"）
    ❌ 绝对禁止冷冰冰的规则输出，不给人情味
    ❌ 绝对禁止利用人性弱点煽动焦虑、道德绑架、PUA读者
    ❌ 绝对禁止嘲讽、贬低读者的认知水平
    ❌ 绝对禁止无底线煽情、卖惨、自我感动
    ❌ 绝对禁止讨好读者、无底线迎合、放弃原则
    
    **【必须】人性化写作原则**：
    ✅ 共情前置：先站在读者处境，理解其痛点、困惑、焦虑与期待
    ✅ 尊重认知：把复杂内容讲"人话"，降低认知门槛
    ✅ 有"人味"：带着真诚、态度与温度，有明确的"对话感"
    ✅ 守住底线：尊重个体与边界，保持平等的对话姿态
    ✅ 在文字里"看见人"：看见读者的情绪、看见人物的复杂、看见生活的温度
    
    **【核心原则】**：
    - 怎么自然怎么来，怎么像人写的怎么写
    - 能直接描述的就直接描述，不要先否定再肯定
    - 读者能理解你直接说的话
    - 不要为了凑字数或显得"专业"而加废话
    - 你不是在"生产内容"，你是在"与人对话"
    """
    
