    def get_humanization_prompt(self, genre_style="core"):
        """获取指定题材的人性化提示词"""
        if genre_style == "core":
            return self.humanization_prompts.get("humanization_core", self.humanization_prompts["core"])
        return self.humanization_prompts.get(genre_style, self.humanization_prompts["core"])
    
    def get_humanization_core(self):
        """获取人性化写作核心指南 - 供外部调用"""
        return self.humanization_prompts.get("humanization_core", "")
    
    def enhance_system_prompt(self, original_prompt, genre_style="core"):
        """将人性化提示词融入原始系统提示词"""
        humanization = self.get_humanization_prompt(genre_style)
        if humanization not in original_prompt:
            return original_prompt + "\n\n" + humanization
        return original_prompt
    
    def enhance_with_humanization_core(self, original_prompt):
        """将人性化核心指南融入原始系统提示词 - 专用方法"""
        humanization_core = self.get_humanization_core()
        if humanization_core and humanization_core not in original_prompt:
            return original_prompt + "\n\n" + humanization_core
        return original_prompt
    
