# 撤销/重做管理器类
class UndoRedoManager:
    """通用的撤销/重做管理器，支持所有文本控件"""
    
    def __init__(self, max_history=100):
        self.max_history = max_history
        self.widget_history = {}  # 存储每个控件的历史记录
        self.widget_future = {}   # 存储每个控件的重做记录
        
    def record_state(self, widget, widget_name=""):
        """记录控件当前状态"""
        try:
            import hashlib
            widget_id = str(widget)
            current_content = widget.get("1.0", tk.END)
            content_hash = hashlib.md5(current_content.encode()).hexdigest()
            
            # 初始化历史记录
            if widget_id not in self.widget_history:
                self.widget_history[widget_id] = []
                self.widget_future[widget_id] = []
            
            # 检查内容是否发生变化
            history = self.widget_history[widget_id]
            if not history or history[-1]["hash"] != content_hash:
                # 记录新状态
                state = {
                    "content": current_content,
                    "hash": content_hash,
                    "cursor_position": widget.index(tk.INSERT),
                    "widget_name": widget_name
                }
                
                history.append(state)
                
                # 限制历史记录数量
                if len(history) > self.max_history:
                    history.pop(0)
                
                # 清空重做记录（因为有了新的更改）
                self.widget_future[widget_id] = []
                
                return True
            
            return False
            
        except Exception as e:
            print(f"记录状态失败: {e}")
            return False
    
    def can_undo(self, widget):
        """检查是否可以撤销"""
        widget_id = str(widget)
        return (widget_id in self.widget_history and 
                len(self.widget_history[widget_id]) > 1)
    
    def can_redo(self, widget):
        """检查是否可以重做"""
        widget_id = str(widget)
        return (widget_id in self.widget_future and 
                len(self.widget_future[widget_id]) > 0)
    
    def undo(self, widget):
        """执行撤销操作"""
        try:
            widget_id = str(widget)
            if not self.can_undo(widget):
                return False
            
            history = self.widget_history[widget_id]
            if len(history) <= 1:
                return False
            
            # 获取当前状态并添加到重做记录
            current_state = history[-1]
            if widget_id not in self.widget_future:
                self.widget_future[widget_id] = []
            self.widget_future[widget_id].append(current_state)
            
            # 移除当前状态
            history.pop()
            
            # 恢复到上一个状态
            previous_state = history[-1]
            widget.delete("1.0", tk.END)
            widget.insert("1.0", previous_state["content"])
            
            # 恢复光标位置
            try:
                widget.mark_set(tk.INSERT, previous_state["cursor_position"])
                widget.see(tk.INSERT)
            except:
                pass  # 如果光标位置无效，忽略
            
            return True
            
        except Exception as e:
            print(f"撤销操作失败: {e}")
            return False
    
    def redo(self, widget):
        """执行重做操作"""
        try:
            widget_id = str(widget)
            if not self.can_redo(widget):
                return False
            
            future = self.widget_future[widget_id]
            if not future:
                return False
            
            # 获取重做状态
            redo_state = future.pop()
            
            # 记录到历史
            if widget_id not in self.widget_history:
                self.widget_history[widget_id] = []
            self.widget_history[widget_id].append(redo_state)
            
            # 应用重做状态
            widget.delete("1.0", tk.END)
            widget.insert("1.0", redo_state["content"])
            
            # 恢复光标位置
            try:
                widget.mark_set(tk.INSERT, redo_state["cursor_position"])
                widget.see(tk.INSERT)
            except:
                pass  # 如果光标位置无效，忽略
            
            return True
            
        except Exception as e:
            print(f"重做操作失败: {e}")
            return False
    
    def clear_history(self, widget):
        """清空指定控件的历史记录"""
        widget_id = str(widget)
        if widget_id in self.widget_history:
            del self.widget_history[widget_id]
        if widget_id in self.widget_future:
            del self.widget_future[widget_id]
    
    def get_history_info(self, widget):
        """获取控件的历史信息"""
        widget_id = str(widget)
        history_count = len(self.widget_history.get(widget_id, []))
        future_count = len(self.widget_future.get(widget_id, []))
        return {
            "history_count": history_count,
            "future_count": future_count,
            "can_undo": self.can_undo(widget),
            "can_redo": self.can_redo(widget)
        }


# 主应用类
class NovelGeneratorApp:
    def __init__(self, root):
        self.root = root
        
        self.root.title("烽火南境 - 啾咪")
        
        # 先加载配置，检查是否有保存的窗口位置
        temp_config = configparser.ConfigParser(strict=False)
        try:
            # First try UTF-8 encoding
            temp_config.read("novel_generator_config.ini", encoding='utf-8')
        except UnicodeDecodeError:
            # If UTF-8 fails, try GBK encoding (common for Chinese files on Windows)
            temp_config.read("novel_generator_config.ini", encoding='gbk')
        except Exception:
            pass
        
        # 检查是否有保存的窗口位置
        saved_geometry = None
        if 'WORKSPACE' in temp_config and 'window_geometry' in temp_config['WORKSPACE']:
            saved_geometry = temp_config['WORKSPACE']['window_geometry']
        
        if saved_geometry:
            # 使用保存的窗口位置
            try:
                self.root.geometry(saved_geometry)
            except:
                # 如果保存的位置无效，使用默认位置
                screen_width = self.root.winfo_screenwidth()
                screen_height = self.root.winfo_screenheight()
                window_width = int(screen_width * 0.9)
                window_height = int(screen_height * 0.9)
                x = (screen_width - window_width) // 2
                y = (screen_height - window_height) // 2
                self.root.geometry(f"{window_width}x{window_height}+{x}+{y}")
        else:
            # 使用默认窗口大小为屏幕的90%
            screen_width = self.root.winfo_screenwidth()
            screen_height = self.root.winfo_screenheight()
            window_width = int(screen_width * 0.9)
            window_height = int(screen_height * 0.9)
            x = (screen_width - window_width) // 2
            y = (screen_height - window_height) // 2
            self.root.geometry(f"{window_width}x{window_height}+{x}+{y}")
        
        # 设置窗口可调整大小
        self.root.minsize(800, 600)
        
        # 设置窗口半透明
        self.root.attributes('-alpha', 1.25)  # 设置窗口整体透明度
        
        # 设置窗口图标
        try:
            self.root.iconbitmap("icon.ico")
        except:
            pass
        
        # 初始化管理器
        self.config_manager = ConfigManager()
        self.file_manager = FileManager()
        self.ai_service = AIService()
        self.theme_manager = ThemeManager()
        self.narrative_consistency_manager = NarrativeConsistencyManager(db_manager=get_database_manager())
        
        # 当前状态
        self.current_module = None
        self.current_outline_dir = None
        self.current_detailed_outline_dir = None
        self.generated_content = ""
        self.generated_content_type = "chapter"
        self.selected_outline_file = None
        self.selected_detailed_outline_file = None
        self.package_path = None
        self.continuation_mode = False
        self.extracted_content_path = None
        self.current_theme = "bamboo"
        self.current_background = None
        self.background_image = None
        self.background_label = None
        
        # 名字生成设置 - 从配置文件加载，如果没有则使用默认值
        # 优先从 NAME_GENERATION 节加载，避免从 WORKSPACE 节加载的错误格式数据干扰
        try:
            # 直接从 ConfigManager 获取 NAME_GENERATION 节的设置
            loaded_name_settings = {}
            if 'NAME_GENERATION' in self.config_manager.config:
                for key in ['gender', 'country', 'surname_count', 'surname', 'given_name', 'requirements']:
                    if key in self.config_manager.config['NAME_GENERATION']:
                        loaded_name_settings[key] = self.config_manager.config['NAME_GENERATION'][key]
                    else:
                        # 如果某个键不存在，使用默认值
                        default_values = {
                            "gender": "男",
                            "country": "中国", 
                            "surname_count": "单姓",
                            "surname": "",
                            "given_name": "",
                            "requirements": ""
                        }
                        loaded_name_settings[key] = default_values[key]
            
            self.name_generation_settings = loaded_name_settings
        except Exception as e:
            print(f"加载名字生成设置失败: {e}")
            self.name_generation_settings = {
                "gender": "男",
                "country": "中国",
                "surname_count": "单姓",
                "surname": "",
                "given_name": "",
                "requirements": ""
            }
        
        # 窗口引用字典，用于透明度控制
        self.active_windows = {}
        
        # 窗口透明度变量字典，用于保存各窗口的透明度设置
        self.dialog_alpha_vars = {}
        
        # 弹窗背景设置字典，用于保存各弹窗的背景设置
        self.dialog_backgrounds = {}
        
        # 开发者模式
        self.developer_mode = False  # 默认关闭开发者模式
        
        # 检查API Key
        saved_api_key = self.config_manager.get_api_key()
        if saved_api_key:
            self.ai_service.set_api_key(saved_api_key)
            print(f"[DEBUG] API Key已加载: {saved_api_key[:10]}...")  # 只显示前10个字符用于调试
        else:
            print("[DEBUG] 未找到保存的API Key")
        
        # 加载背景设置
        self.load_background_settings()
        
        # 加载保存的主题设置
        saved_theme = self.config_manager.get_user_preferences().get('theme', 'bamboo')
        self.current_theme = saved_theme
        
        # 创建主界面
        self.create_main_interface()
        
        # 应用初始主题
        self.apply_theme(self.current_theme)
        
        # 设置键盘快捷键
        self.setup_keyboard_shortcuts()
        
        # 初始化撤销/重做管理器
        self.undo_redo_manager = UndoRedoManager()
        
        # 自动保存相关
        self.auto_save_enabled = True
        self.auto_save_interval = 60000  # 自动保存间隔（毫秒），默认60秒
        self.auto_save_timer = None
        
        # 加载书籍信息
        self.load_books_state()
        
        # 加载上次保存的工作区状态
        self.load_workspace_state()
        
        # 启动自动保存定时器
        self.start_auto_save()
        
        # 设置窗口关闭事件
        self.root.protocol("WM_DELETE_WINDOW", self.on_window_close)
    
    def start_auto_save(self):
        """启动自动保存定时器"""
        if self.auto_save_enabled and self.auto_save_timer is None:
            self.auto_save_timer = self.root.after(self.auto_save_interval, self.auto_save)
    
    def stop_auto_save(self):
        """停止自动保存定时器"""
        if self.auto_save_timer is not None:
            self.root.after_cancel(self.auto_save_timer)
            self.auto_save_timer = None
    
    def auto_save(self):
        """自动保存当前工作区状态"""
        try:
            books_manager = get_books_manager()
            current_book = books_manager.get_current_book()
            
            if current_book:
                self._save_book_content_silent()
            
            self.save_books_state()
            self.save_workspace_state()
            self.update_status("已自动保存工作区状态")
        except Exception as e:
            print(f"自动保存失败: {e}")
        
        if self.auto_save_enabled:
            self.auto_save_timer = self.root.after(self.auto_save_interval, self.auto_save)
    
    def _save_book_content_silent(self):
        """静默保存书籍内容（不显示提示框）"""
        try:
            books_manager = get_books_manager()
            current_book = books_manager.get_current_book()
            
            if not current_book:
                return
            
            book_dir = books_manager.get_current_book_dir()
            if not book_dir:
                return
            
            book_dir = Path(book_dir)
            book_dir.mkdir(parents=True, exist_ok=True)
            
            generated_content = self.generated_text.get("1.0", tk.END).strip() if hasattr(self, 'generated_text') else ""
            if generated_content and generated_content != "正在生成..." and generated_content != "正在生成出版小说风格章节...":
                content_file = book_dir / "生成内容.txt"
                with open(content_file, 'w', encoding='utf-8') as f:
                    f.write(generated_content)
                self.generated_content = generated_content
            
            if hasattr(self, 'outline_content_text') and self.outline_content_text:
                outline_content = self.outline_content_text.get("1.0", tk.END).strip()
                if outline_content:
                    outline_file = book_dir / "大纲.txt"
                    with open(outline_file, 'w', encoding='utf-8') as f:
                        f.write(outline_content)
            
            if hasattr(self, 'detailed_outline_content_text') and self.detailed_outline_content_text:
                detailed_content = self.detailed_outline_content_text.get("1.0", tk.END).strip()
                if detailed_content:
                    detailed_file = book_dir / "细纲.txt"
                    with open(detailed_file, 'w', encoding='utf-8') as f:
                        f.write(detailed_content)
            
            if hasattr(self, 'writing_requirements_text') and self.writing_requirements_text:
                requirements = self.writing_requirements_text.get("1.0", tk.END).strip()
                if requirements:
                    req_file = book_dir / "写作要求.txt"
                    with open(req_file, 'w', encoding='utf-8') as f:
                        f.write(requirements)
            
            if hasattr(self, 'continuation_requirements_text') and self.continuation_requirements_text:
                cont_req = self.continuation_requirements_text.get("1.0", tk.END).strip()
                if cont_req:
                    cont_file = book_dir / "续写要求.txt"
                    with open(cont_file, 'w', encoding='utf-8') as f:
                        f.write(cont_req)
            
            books_manager.update_book_info(current_book)
            
        except Exception as e:
            print(f"静默保存书籍内容失败: {e}")
    
    def save_workspace_state(self):
        """保存当前工作区状态"""
        state_data = {
            'save_time': datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            'current_module': str(self.current_module) if self.current_module else '',
            'current_theme': str(self.current_theme),
            'generated_content': str(self.generated_content) if self.generated_content else '',
            'continuation_mode': str(self.continuation_mode),
        }
        
        # 保存各个文本区域的内容
        text_widgets = self.get_all_text_widgets()
        for widget_name, widget in text_widgets.items():
            try:
                content = widget.get("1.0", tk.END).strip()
                # 使用base64编码来避免特殊字符问题
                import base64
                encoded_content = base64.b64encode(content.encode('utf-8')).decode('utf-8')
                state_data[f'text_{widget_name}'] = encoded_content
            except Exception as e:
                print(f"保存文本区域 {widget_name} 失败: {e}")
        
        # 保存所有文件路径和目录
        file_paths = {
            'outline_file_path': self.outline_file_path,
            'outline_dir_var': self.outline_dir_var,
            'detailed_outline_file_path': self.detailed_outline_file_path,
            'detailed_outline_dir_var': self.detailed_outline_dir_var,
            'writing_outline_path': self.writing_outline_path,
            'writing_detailed_outline_path': self.writing_detailed_outline_path,
            'package_save_path': self.package_save_path,
            'continuation_outline_path': self.continuation_outline_path,
            'continuation_extracted_content_path': self.continuation_extracted_content_path,
            'continuation_detailed_outline_path': self.continuation_detailed_outline_path,
            'continuation_package_save_path': self.continuation_package_save_path,
            'batch_outline_path': self.batch_outline_path,
            'batch_detailed_outline_path': self.batch_detailed_outline_path,
            'batch_save_path': self.batch_save_path,
        }
        
        for key, var in file_paths.items():
            try:
                if hasattr(var, 'get'):
                    value = var.get()
                    if value:
                        state_data[key] = str(value)
            except Exception as e:
                print(f"保存文件路径 {key} 失败: {e}")
        
        # 保存其他状态
        if hasattr(self, 'selected_outline_file') and self.selected_outline_file:
            state_data['selected_outline_file'] = str(self.selected_outline_file)
        if hasattr(self, 'selected_detailed_outline_file') and self.selected_detailed_outline_file:
            state_data['selected_detailed_outline_file'] = str(self.selected_detailed_outline_file)
        if hasattr(self, 'current_outline_dir') and self.current_outline_dir:
            state_data['current_outline_dir'] = str(self.current_outline_dir)
        if hasattr(self, 'current_detailed_outline_dir') and self.current_detailed_outline_dir:
            state_data['current_detailed_outline_dir'] = str(self.current_detailed_outline_dir)
        
        # 保存续写细纲相关状态
        if hasattr(self, 'continue_outline_file') and self.continue_outline_file:
            state_data['continue_outline_file'] = str(self.continue_outline_file)
        if hasattr(self, 'current_continue_outline_dir') and self.current_continue_outline_dir:
            state_data['current_continue_outline_dir'] = str(self.current_continue_outline_dir)
        
        # 保存续写细纲的变量状态
        if hasattr(self, 'continue_outline_dir_var') and self.continue_outline_dir_var:
            state_data['continue_outline_dir_var'] = self.continue_outline_dir_var.get()
        if hasattr(self, 'continue_outline_genre_var') and self.continue_outline_genre_var:
            state_data['continue_outline_genre_var'] = self.continue_outline_genre_var.get()
        if hasattr(self, 'continue_outline_style_var') and self.continue_outline_style_var:
            state_data['continue_outline_style_var'] = self.continue_outline_style_var.get()
        if hasattr(self, 'continue_mode_var') and self.continue_mode_var:
            state_data['continue_mode_var'] = self.continue_mode_var.get()
        if hasattr(self, 'continue_chapter_count_var') and self.continue_chapter_count_var:
            state_data['continue_chapter_count_var'] = str(self.continue_chapter_count_var.get())
        
        # 保存续写要求文本内容
        if hasattr(self, 'continue_requirements_text') and self.continue_requirements_text:
            try:
                requirements_content = self.continue_requirements_text.get("1.0", tk.END).strip()
                if requirements_content:
                    import base64
                    encoded_content = base64.b64encode(requirements_content.encode('utf-8')).decode('utf-8')
                    state_data['continue_requirements_text'] = encoded_content
            except Exception as e:
                print(f"保存续写要求文本失败: {e}")
        
        # 随机取名设置已通过ConfigManager单独保存，不需要在工作区状态中重复保存
        
        # 保存窗口位置和大小
        try:
            geometry = self.root.geometry()
            state_data['window_geometry'] = geometry
        except Exception as e:
            print(f"保存窗口位置失败: {e}")
        
        # 保存listbox项目
        try:
            listbox_items = self.get_all_listbox_items()
            import json
            for listbox_name, items in listbox_items.items():
                state_data[f'listbox_{listbox_name}'] = json.dumps(items, ensure_ascii=False)
        except Exception as e:
            print(f"保存listbox项目失败: {e}")
        
        # 保存treeview项目
        try:
            treeview_items = self.get_all_treeview_items()
            import json
            for treeview_name, items in treeview_items.items():
                state_data[f'treeview_{treeview_name}'] = json.dumps(items, ensure_ascii=False)
        except Exception as e:
            print(f"保存treeview项目失败: {e}")
        
        self.config_manager.save_workspace_state(state_data)
    
    def load_workspace_state(self):
        """加载上次保存的工作区状态"""
        try:
            state_data = self.config_manager.load_workspace_state()
            
            if not state_data:
                return
            
            # 显示上次保存时间
            last_save_time = state_data.get('save_time')
            if last_save_time:
                print(f"加载上次保存的工作区状态 (保存时间: {last_save_time})")
            
            # 延迟加载，确保界面已经创建完成
            self.root.after(100, lambda: self.restore_workspace_state(state_data))
            
        except Exception as e:
            print(f"加载工作区状态失败: {e}")
    
    def restore_workspace_state(self, state_data):
        """恢复工作区状态"""
        try:
            import base64
            
            # 恢复窗口位置和大小（优先恢复，确保窗口位置正确）
            if 'window_geometry' in state_data:
                try:
                    self.root.geometry(state_data['window_geometry'])
                except Exception as e:
                    print(f"恢复窗口位置失败: {e}")
            
            # 恢复文本区域内容
            text_widgets = self.get_all_text_widgets()
            for widget_name, widget in text_widgets.items():
                key = f'text_{widget_name}'
                if key in state_data:
                    try:
                        encoded_content = state_data[key]
                        content = base64.b64decode(encoded_content.encode('utf-8')).decode('utf-8')
                        widget.delete("1.0", tk.END)
                        widget.insert("1.0", content)
                    except Exception as e:
                        print(f"恢复文本区域 {widget_name} 失败: {e}")
            
            # 恢复所有文件路径和目录
            file_paths = {
                'outline_file_path': self.outline_file_path,
                'outline_dir_var': self.outline_dir_var,
                'detailed_outline_file_path': self.detailed_outline_file_path,
                'detailed_outline_dir_var': self.detailed_outline_dir_var,
                'writing_outline_path': self.writing_outline_path,
                'writing_detailed_outline_path': self.writing_detailed_outline_path,
                'package_save_path': self.package_save_path,
                'continuation_outline_path': self.continuation_outline_path,
                'continuation_extracted_content_path': self.continuation_extracted_content_path,
                'continuation_detailed_outline_path': self.continuation_detailed_outline_path,
                'continuation_package_save_path': self.continuation_package_save_path,
                'batch_outline_path': self.batch_outline_path,
                'batch_detailed_outline_path': self.batch_detailed_outline_path,
                'batch_save_path': self.batch_save_path,
            }
            
            for key, var in file_paths.items():
                try:
                    if key in state_data and hasattr(var, 'set'):
                        var.set(state_data[key])
                except Exception as e:
                    print(f"恢复文件路径 {key} 失败: {e}")
            
            # 恢复其他状态
            if 'generated_content' in state_data:
                self.generated_content = state_data['generated_content']
            
            if 'continuation_mode' in state_data:
                self.continuation_mode = state_data['continuation_mode'].lower() == 'true'
            
            if 'selected_outline_file' in state_data:
                self.selected_outline_file = state_data['selected_outline_file']
            
            if 'selected_detailed_outline_file' in state_data:
                self.selected_detailed_outline_file = state_data['selected_detailed_outline_file']
            
            if 'current_outline_dir' in state_data:
                self.current_outline_dir = state_data['current_outline_dir']
            
            if 'current_detailed_outline_dir' in state_data:
                self.current_detailed_outline_dir = state_data['current_detailed_outline_dir']
            
            # 恢复续写细纲相关状态
            if 'continue_outline_file' in state_data:
                self.continue_outline_file = state_data['continue_outline_file']
                # 更新标签显示
                if hasattr(self, 'continue_outline_label') and self.continue_outline_file:
                    self.continue_outline_label.config(text=self.continue_outline_file)
            
            if 'current_continue_outline_dir' in state_data:
                self.current_continue_outline_dir = state_data['current_continue_outline_dir']
            
            if 'continue_outline_dir_var' in state_data and hasattr(self, 'continue_outline_dir_var'):
                self.continue_outline_dir_var.set(state_data['continue_outline_dir_var'])
            
            if 'continue_outline_genre_var' in state_data and hasattr(self, 'continue_outline_genre_var'):
                self.continue_outline_genre_var.set(state_data['continue_outline_genre_var'])
            
            if 'continue_outline_style_var' in state_data and hasattr(self, 'continue_outline_style_var'):
                self.continue_outline_style_var.set(state_data['continue_outline_style_var'])
            
            if 'continue_mode_var' in state_data and hasattr(self, 'continue_mode_var'):
                self.continue_mode_var.set(state_data['continue_mode_var'])
            
            if 'continue_chapter_count_var' in state_data and hasattr(self, 'continue_chapter_count_var'):
                self.continue_chapter_count_var.set(int(state_data['continue_chapter_count_var']))
            
            # 恢复续写要求文本内容
            if 'continue_requirements_text' in state_data and hasattr(self, 'continue_requirements_text'):
                try:
                    encoded_content = state_data['continue_requirements_text']
                    requirements_content = base64.b64decode(encoded_content.encode('utf-8')).decode('utf-8')
                    self.continue_requirements_text.delete("1.0", tk.END)
                    self.continue_requirements_text.insert("1.0", requirements_content)
                except Exception as e:
                    print(f"恢复续写要求文本失败: {e}")
            
            # 恢复主题
            if 'current_theme' in state_data:
                theme_name = state_data['current_theme']
                if theme_name != self.current_theme:
                    self.apply_theme(theme_name)
            
            # 随机取名设置已通过ConfigManager单独恢复，不需要从工作区状态中恢复
            
            # 恢复listbox项目
            try:
                import json
                listbox_items = {}
                for key in state_data:
                    if key.startswith('listbox_'):
                        listbox_name = key.replace('listbox_', '')
                        listbox_items[listbox_name] = json.loads(state_data[key])
                self.restore_all_listbox_items(listbox_items)
            except Exception as e:
                print(f"恢复listbox项目失败: {e}")
            
            # 恢复treeview项目
            try:
                import json
                treeview_items = {}
                for key in state_data:
                    if key.startswith('treeview_'):
                        treeview_name = key.replace('treeview_', '')
                        treeview_items[treeview_name] = json.loads(state_data[key])
                self.restore_all_treeview_items(treeview_items)
            except Exception as e:
                print(f"恢复treeview项目失败: {e}")
            
            # 恢复当前模块（延迟执行，确保所有界面都已加载）
            if 'current_module' in state_data and state_data['current_module']:
                current_module = state_data['current_module']
                self.root.after(200, lambda: self.restore_current_module(current_module))
            
            self.update_status("已恢复上次的工作区状态")
            
        except Exception as e:
            print(f"恢复工作区状态失败: {e}")
    
    def restore_current_module(self, module_name):
        """恢复当前选中的模块"""
        try:
            if hasattr(self, 'notebook'):
                for i in range(self.notebook.index("end")):
                    if self.notebook.tab(i, "text") == module_name:
                        self.notebook.select(i)
                        self.current_module = module_name
                        self.update_status(f"切换到 {self.current_module}")
                        break
        except Exception as e:
            print(f"恢复当前模块失败: {e}")
    
    def on_window_close(self):
        """窗口关闭事件处理"""
        try:
            # 停止自动保存
            self.stop_auto_save()
            
            # 保存当前书籍状态
            self.save_books_state()
            
            # 保存当前工作区状态
            self.save_workspace_state()
            self.update_status("已保存工作区状态")
            
        except Exception as e:
            print(f"保存工作区状态失败: {e}")
        
        # 销毁窗口
        self.root.destroy()
    
    def load_books_state(self):
        """加载书籍状态"""
        try:
            # 初始化书籍管理器
            books_manager = get_books_manager()
            
            # 如果有保存的当前书籍信息，加载它
            user_preferences = self.config_manager.get_user_preferences()
            current_book = user_preferences.get('current_book', None)
            if current_book and current_book in books_manager.get_all_books():
                books_manager.set_current_book(current_book)
                print(f"已加载当前书籍: {current_book}")
            
        except Exception as e:
            print(f"加载书籍状态失败: {e}")
    
    def save_books_state(self):
        """保存书籍状态"""
        try:
            # 获取当前书籍信息
            books_manager = get_books_manager()
            current_book = books_manager.get_current_book()
            
            # 保存当前书籍到配置文件
            if current_book:
                self.config_manager.save_user_preference('current_book', current_book)
                print(f"已保存当前书籍: {current_book}")
            
        except Exception as e:
            print(f"保存书籍状态失败: {e}")
    
    def save_book_state(self):
        """手动保存当前书籍的完整状态"""
        try:
            books_manager = get_books_manager()
            current_book = books_manager.get_current_book()
            
            if not current_book:
                result = messagebox.askyesno("提示", "当前没有打开的书籍，是否创建一本新书籍？")
                if result:
                    self.show_new_book_dialog()
                return
            
            book_dir = books_manager.get_current_book_dir()
            if not book_dir:
                messagebox.showerror("错误", "无法获取书籍目录")
                return
            
            book_dir = Path(book_dir)
            book_dir.mkdir(parents=True, exist_ok=True)
            
            saved_files = []
            
            generated_content = self.generated_text.get("1.0", tk.END).strip() if hasattr(self, 'generated_text') else ""
            if generated_content and generated_content != "正在生成...":
                content_file = book_dir / "生成内容.txt"
                with open(content_file, 'w', encoding='utf-8') as f:
                    f.write(generated_content)
                saved_files.append("生成内容.txt")
                self.generated_content = generated_content
            
            if hasattr(self, 'outline_content_text') and self.outline_content_text:
                outline_content = self.outline_content_text.get("1.0", tk.END).strip()
                if outline_content:
                    outline_file = book_dir / "大纲.txt"
                    with open(outline_file, 'w', encoding='utf-8') as f:
                        f.write(outline_content)
                    saved_files.append("大纲.txt")
            
            if hasattr(self, 'detailed_outline_content_text') and self.detailed_outline_content_text:
                detailed_content = self.detailed_outline_content_text.get("1.0", tk.END).strip()
                if detailed_content:
                    detailed_file = book_dir / "细纲.txt"
                    with open(detailed_file, 'w', encoding='utf-8') as f:
                        f.write(detailed_content)
                    saved_files.append("细纲.txt")
            
            if hasattr(self, 'writing_requirements_text') and self.writing_requirements_text:
                requirements = self.writing_requirements_text.get("1.0", tk.END).strip()
                if requirements:
                    req_file = book_dir / "写作要求.txt"
                    with open(req_file, 'w', encoding='utf-8') as f:
                        f.write(requirements)
                    saved_files.append("写作要求.txt")
            
            if hasattr(self, 'continuation_requirements_text') and self.continuation_requirements_text:
                cont_req = self.continuation_requirements_text.get("1.0", tk.END).strip()
                if cont_req:
                    cont_file = book_dir / "续写要求.txt"
                    with open(cont_file, 'w', encoding='utf-8') as f:
                        f.write(cont_req)
                    saved_files.append("续写要求.txt")
            
            if hasattr(self, 'continuation_existing_chapters_listbox') and self.continuation_existing_chapters_listbox:
                existing_chapters = []
                for i in range(self.continuation_existing_chapters_listbox.size()):
                    existing_chapters.append(self.continuation_existing_chapters_listbox.get(i))
                if existing_chapters:
                    chapters_file = book_dir / "已有章节列表.txt"
                    with open(chapters_file, 'w', encoding='utf-8') as f:
                        f.write('\n'.join(existing_chapters))
                    saved_files.append("已有章节列表.txt")
            
            if hasattr(self, 'current_chapter_data') and self.current_chapter_data:
                import json
                chapter_data_file = book_dir / "章节数据.json"
                with open(chapter_data_file, 'w', encoding='utf-8') as f:
                    json.dump(self.current_chapter_data, f, ensure_ascii=False, indent=2)
                saved_files.append("章节数据.json")
            
            book_info_file = book_dir / "书籍信息.txt"
            with open(book_info_file, 'w', encoding='utf-8') as f:
                f.write(f"保存时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                if hasattr(self, 'writing_style'):
                    f.write(f"写作风格: {self.writing_style.get()}\n")
                if hasattr(self, 'writing_genre'):
                    f.write(f"作品题材: {self.writing_genre.get()}\n")
            saved_files.append("书籍信息.txt")
            
            self.save_workspace_state()
            self.save_books_state()
            
            books_manager.update_book_info(current_book)
            
            current_book_info = books_manager.get_current_book_info()
            book_name = current_book_info['name'] if current_book_info else current_book
            
            self.update_status(f"已成功保存书籍: {book_name}")
            
            if saved_files:
                messagebox.showinfo("保存成功", f"书籍 '{book_name}' 已成功保存!\n\n保存的文件:\n" + "\n".join(f"• {f}" for f in saved_files))
            else:
                messagebox.showinfo("保存成功", f"书籍 '{book_name}' 状态已保存!")
                
        except Exception as e:
            print(f"保存书籍状态失败: {e}")
            import traceback
            traceback.print_exc()
            messagebox.showerror("保存失败", f"保存书籍状态时发生错误: {e}")
    
    def setup_keyboard_shortcuts(self):
        """设置键盘快捷键"""
        # Ctrl+S: 保存内容
        self.root.bind("<Control-s>", lambda event: self.save_content())
        
        # Ctrl+R: 重新生成
        self.root.bind("<Control-r>", lambda event: self.regenerate_content())
        
        # Ctrl+F: 查找文本
        self.root.bind("<Control-f>", lambda event: self.show_find_dialog())
        
        # Ctrl+Q: 退出程序
        self.root.bind("<Control-q>", lambda event: self.root.quit())
        
        # Ctrl+Z: 撤销（全局）
        self.root.bind("<Control-z>", lambda event: self.handle_global_undo())
        
        # Ctrl+Y: 重做（全局）
        self.root.bind("<Control-y>", lambda event: self.handle_global_redo())
        
        # 设置所有文本控件的撤销/重做功能
        self.setup_all_text_widgets_undo_redo()
    
    def handle_global_undo(self):
        """处理全局撤销操作"""
        try:
            # 获取当前焦点控件
            focus_widget = self.root.focus_get()
            
            # 检查是否是文本控件
            if isinstance(focus_widget, (tk.Text, scrolledtext.ScrolledText)):
                # 获取控件名称
                widget_name = "未知控件"
                text_widgets = self.get_all_text_widgets()
                for name, widget in text_widgets.items():
                    if widget == focus_widget:
                        widget_name = name
                        break
                
                # 执行撤销
                self.undo_text_widget(focus_widget, widget_name)
                return "break"
            
        except Exception as e:
            print(f"全局撤销失败: {e}")
        
        return None
    
    def handle_global_redo(self):
        """处理全局重做操作"""
        try:
            # 获取当前焦点控件
            focus_widget = self.root.focus_get()
            
            # 检查是否是文本控件
            if isinstance(focus_widget, (tk.Text, scrolledtext.ScrolledText)):
                # 获取控件名称
                widget_name = "未知控件"
                text_widgets = self.get_all_text_widgets()
                for name, widget in text_widgets.items():
                    if widget == focus_widget:
                        widget_name = name
                        break
                
                # 执行重做
                self.redo_text_widget(focus_widget, widget_name)
                return "break"
            
        except Exception as e:
            print(f"全局重做失败: {e}")
        
        return None
    
    def save_content(self):
        """保存内容快捷键处理"""
        if not self.generated_content:
            messagebox.showwarning("警告", "没有可保存的内容！")
            return
        
        self.save_generated_content()
    
    def show_books_manager_dialog(self):
        """显示书籍管理对话框"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        dialog = tk.Toplevel(self.root)
        dialog.title("书籍管理")
        dialog.geometry("600x500")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(bg=theme["bg"])
        
        saved_alpha = self.dialog_alpha_vars.get("input_window", tk.DoubleVar(value=0.97)).get()
        dialog.attributes('-alpha', saved_alpha)
        self.active_windows['input_window'] = dialog
        dialog.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('input_window', dialog))
        
        self.apply_dialog_background('input_window')
        
        # 创建书籍列表框架
        list_frame = tk.Frame(dialog, bg=theme["bg"])
        list_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        tk.Label(list_frame, text="书籍列表:", bg=theme["bg"], fg=theme["fg"]).pack(anchor=tk.W, padx=5, pady=(0, 10))
        
        # 创建书籍列表
        books_manager = get_books_manager()
        all_books = books_manager.get_all_books()
        current_book = books_manager.get_current_book()
        
        if not all_books:
            tk.Label(list_frame, text="暂无书籍，请先创建书籍", bg=theme["bg"], fg=theme["fg"]).pack(fill=tk.BOTH, expand=True, padx=5, pady=20)
        else:
            # 创建列表框
            book_listbox = tk.Listbox(list_frame, bg=theme["text_bg"], fg=theme["text_fg"], selectbackground=theme["highlight"])
            book_listbox.pack(fill=tk.BOTH, expand=True, padx=5, pady=(0, 15))
            
            # 添加书籍到列表框
            book_items = []
            current_index = -1
            for idx, (book_id, book_info) in enumerate(all_books.items()):
                is_current = "[当前] " if book_id == current_book else ""
                item_text = f"{is_current}{book_info['name']} ({book_info['type']}) - {book_info['created_at'][:10]}"
                book_listbox.insert(tk.END, item_text)
                book_items.append((book_id, book_info))
                if book_id == current_book:
                    current_index = idx
            
            # 选中当前书籍
            if current_index >= 0:
                book_listbox.selection_set(current_index)
            
            # 创建按钮框架
            button_frame = tk.Frame(dialog, bg=theme["bg"])
            button_frame.pack(fill=tk.X, padx=20, pady=(0, 20))
            
            # 刷新书籍列表
            def refresh_book_list():
                nonlocal book_items, current_index
                
                book_listbox.delete(0, tk.END)
                book_items = []
                current_index = -1
                
                all_books = books_manager.get_all_books()
                current_book = books_manager.get_current_book()
                
                for idx, (book_id, book_info) in enumerate(all_books.items()):
                    is_current = "[当前] " if book_id == current_book else ""
                    item_text = f"{is_current}{book_info['name']} ({book_info['type']}) - {book_info['created_at'][:10]}"
                    book_listbox.insert(tk.END, item_text)
                    book_items.append((book_id, book_info))
                    if book_id == current_book:
                        current_index = idx
                
                # 选中当前书籍
                if current_index >= 0:
                    book_listbox.selection_set(current_index)
            
