    def set_dialog_bg(self, dialog_key, action_type, parent_window=None):
        """设置弹窗背景"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        if action_type == "color":
            color = colorchooser.askcolor(title=f"选择{dialog_key}的背景颜色", initialcolor="#F5F5F5")
            if color[1]:
                if len(color[1]) == 7:
                    color_with_alpha = color[1] + "E6"
                else:
                    color_with_alpha = color[1]
                self.dialog_backgrounds[dialog_key] = {"type": "color", "value": color_with_alpha}
                self.config_manager.save_dialog_background(dialog_key, "color", color_with_alpha)
                self.apply_dialog_background(dialog_key)
                if parent_window:
                    parent_window.destroy()
        
        elif action_type == "image":
            filetypes = [
                ("图片文件", "*.png *.jpg *.jpeg *.gif *.bmp"),
                ("所有文件", "*.*")
            ]
            image_path = filedialog.askopenfilename(
                title="选择背景图片",
                filetypes=filetypes,
                initialdir=self.file_manager.backgrounds_dir
            )
            if image_path:
                try:
                    img = Image.open(image_path)
                    img = img.convert("RGBA")
                    photo_img = ImageTk.PhotoImage(img)
                    
                    self.dialog_backgrounds[dialog_key] = {"type": "image", "value": image_path, "image": photo_img}
                    self.config_manager.save_dialog_background(dialog_key, "image", image_path)
                    self.apply_dialog_background(dialog_key)
                    if parent_window:
                        parent_window.destroy()
                except Exception as e:
                    messagebox.showerror("错误", f"无法加载图片: {e}")
        
        elif action_type == "clear":
            if dialog_key in self.dialog_backgrounds:
                del self.dialog_backgrounds[dialog_key]
            self.config_manager.clear_dialog_background(dialog_key)
            self.apply_dialog_background(dialog_key)
            if parent_window:
                parent_window.destroy()
    
    def apply_dialog_background(self, dialog_key):
        """将背景设置应用到指定弹窗"""
        if dialog_key not in self.active_windows or not self.active_windows[dialog_key]:
            return
        
        window = self.active_windows[dialog_key]
        
        for widget in window.winfo_children():
            if hasattr(widget, '_bg_canvas') and widget._bg_canvas:
                try:
                    widget._bg_canvas.destroy()
                except:
                    pass
            if hasattr(widget, '_bg_overlay') and widget._bg_overlay:
                try:
                    widget._bg_overlay.destroy()
                except:
                    pass
        
        if dialog_key not in self.dialog_backgrounds:
            return
        
        bg_config = self.dialog_backgrounds[dialog_key]
        bg_type = bg_config.get("type")
        
        if bg_type == "color":
            color_value = bg_config.get("value", "#F5F5F5")
            # 移除透明度部分，Tkinter不支持透明度格式
            if len(color_value) == 9:  # 如果包含透明度，移除最后2位
                bg_color = color_value[:-2]
            else:
                bg_color = color_value
            
            window.configure(bg=bg_color)
            
            for widget in window.winfo_children():
                self._apply_bg_to_widget(widget, bg_color, None)
        
        elif bg_type == "image":
            bg_image = bg_config.get("image")
            if not bg_image:
                return
            
            window._bg_canvas = tk.Canvas(window, bg=window.cget("bg"), highlightthickness=0, relief="flat", bd=0)
            window._bg_canvas.place(x=0, y=0, relwidth=1, relheight=1)
            # 确保Canvas在底层 - 使用正确的Tkinter层级管理
            window._bg_canvas.lower("all")
            
            def on_configure(event):
                if hasattr(window, '_bg_canvas') and window._bg_canvas:
                    window._bg_canvas.delete("all")
                    canvas_width = window._bg_canvas.winfo_width()
                    canvas_height = window._bg_canvas.winfo_height()
                    
                    if canvas_width > 0 and canvas_height > 0:
                        img_width = bg_image.width()
                        img_height = bg_image.height()
                        
                        if img_width > 0 and img_height > 0:
                            scale = min(canvas_width / img_width, canvas_height / img_height) * 0.85
                            display_width = int(img_width * scale)
                            display_height = int(img_height * scale)
                            
                            x_offset = (canvas_width - display_width) // 2
                            y_offset = (canvas_height - display_height) // 2
                            
                            window._bg_canvas.create_image(
                                x_offset + display_width // 2,
                                y_offset + display_height // 2,
                                anchor=tk.CENTER,
                                image=bg_image
                            )
            
            window._bg_canvas.bind("<Configure>", on_configure)
            
            window._bg_overlay = tk.Frame(window, bg=bg_color if 'bg_color' in dir() else "#F5F5F5")
            window._bg_overlay.place(x=0, y=0, relwidth=1, relheight=1)
            
            def apply_overlay_theme(widget, overlay_color):
                try:
                    if isinstance(widget, tk.Frame):
                        widget.configure(bg=overlay_color)
                    elif isinstance(widget, tk.Label):
                        if widget.cget("bg") != overlay_color:
                            widget.configure(bg=overlay_color)
                    elif isinstance(widget, tk.Button):
                        pass
                    elif isinstance(widget, tk.Canvas):
                        pass
                    else:
                        pass
                except:
                    pass
                
                for child in widget.winfo_children():
                    self._apply_overlay_theme(child, overlay_color)
            
            def _apply_overlay_theme(widget, overlay_color):
                apply_overlay_theme(widget, overlay_color)
            
            window.bind("<Configure>", lambda e: None)
    
    def _apply_bg_to_widget(self, widget, bg_color, bg_image):
        """递归应用背景到子组件"""
        try:
            if isinstance(widget, tk.Frame):
                widget.configure(bg=bg_color)
            elif isinstance(widget, tk.Label):
                if widget.cget("bg") != bg_color:
                    widget.configure(bg=bg_color)
            elif isinstance(widget, tk.Canvas):
                widget.configure(bg=bg_color)
            elif isinstance(widget, tk.Entry):
                widget.configure(bg="#FFFFFF")
            elif isinstance(widget, tk.Text):
                widget.configure(bg="#FFFFFF")
            elif isinstance(widget, ttk.Entry):
                pass
            elif isinstance(widget, ttk.Combobox):
                pass
            else:
                pass
        except:
            pass
        
        for child in widget.winfo_children():
            self._apply_bg_to_widget(child, bg_color, bg_image)
    
    def on_dialog_close(self, key, window):
        """弹窗关闭时清理引用"""
        if key in self.active_windows:
            self.active_windows[key] = None
        try:
            window.destroy()
        except:
            pass
    
    def save_name_generation_settings(self, settings):
        """保存名字生成设置"""
        self.name_generation_settings.update(settings)
        
        # 同时保存到配置文件中
        try:
            self.config_manager.set_name_generation_settings(self.name_generation_settings)
        except Exception as e:
            print(f"保存名字生成设置失败: {e}")
    
    def choose_bg_color_from_settings(self):
        """从设置窗口选择背景颜色"""
        color = colorchooser.askcolor(title="选择背景颜色", initialcolor="#F5F5F5")
        if color[1]:
            if len(color[1]) == 7:
                color_with_alpha = color[1] + "E6"
            else:
                color_with_alpha = color[1]
            self.set_background_color(color_with_alpha)
            self.config_manager.save_background('color', color=color_with_alpha)
            self.current_bg_type = "color"
            self.update_bg_labels()
            self.update_bg_preview()
            self.update_settings_preview()
    
    def choose_bg_image_from_settings(self):
        """从设置窗口选择背景图片"""
        filetypes = [
            ("图片文件", "*.png *.jpg *.jpeg *.gif *.bmp"),
            ("所有文件", "*.*")
        ]
        image_path = filedialog.askopenfilename(
            title="选择背景图片",
            filetypes=filetypes,
            initialdir=self.file_manager.backgrounds_dir
        )
        if image_path:
            self.set_background_image(image_path)
            self.config_manager.save_background('image', image_path=image_path)
            self.current_bg_type = "image"
            self.update_bg_labels()
            self.update_bg_preview()
            self.update_settings_preview()
    
    def clear_bg_from_settings(self):
        """从设置窗口清除背景"""
        self.clear_background_image()
        self.current_bg_type = "color"
        self.update_bg_labels()
        self.update_bg_preview()
        self.update_settings_preview()
    
    def default_bg_from_settings(self):
        """从设置窗口恢复默认背景"""
        theme = self.theme_manager.get_theme(self.current_theme)
        self.set_background_color(theme["bg"])
        self.current_bg_type = "color"
        self.update_bg_labels()
        self.update_bg_preview()
        self.update_settings_preview()
    
    def update_bg_labels(self):
        """更新背景标签状态"""
        theme = self.theme_manager.get_theme(self.current_theme)
        if self.current_bg_type == "color":
            self.bg_color_btn.config(bg=theme["button_active_bg"])
            self.bg_image_btn.config(bg=theme["button_bg"])
        else:
            self.bg_color_btn.config(bg=theme["button_bg"])
            self.bg_image_btn.config(bg=theme["button_active_bg"])
    
    def update_bg_preview(self):
        """更新背景预览"""
        if self.current_background and self.current_background[0] == "image" and self.background_image:
            self.bg_preview.config(image=self.background_image, text="")
        else:
            theme = self.theme_manager.get_theme(self.current_theme)
            self.bg_preview.config(image="", bg=theme["bg"])
    
    def reset_window_settings(self, main_scale, dialog_scale):
        """重置窗口设置"""
        main_scale.set(1.25)
        dialog_scale.set(0.97)
        self.root.attributes('-alpha', 1.25)
    
    def create_card_frame(self, parent, title="", padding=12):
        """创建卡片容器 - 带圆角效果的卡片布局
        
        Args:
            parent: 父容器
            title: 卡片标题（可选）
            padding: 内边距
            
        Returns:
            卡片框架对象
        """
        theme = self.theme_manager.get_theme(self.current_theme)
        is_bamboo = self.current_theme == "bamboo"
        
        if is_bamboo:
            card_border = theme.get("card_border", "#A5D6A7")
            card_bg = theme.get("card_bg", "#FFFFFF")
            
            outer_frame = tk.Frame(parent, bg=card_border, bd=0)
            
            inner_frame = tk.Frame(outer_frame, bg=card_bg, bd=0)
            inner_frame.pack(fill=tk.BOTH, expand=True, padx=2, pady=2)
            
            if title:
                title_frame = tk.Frame(inner_frame, bg=card_bg)
                title_frame.pack(fill=tk.X, padx=padding, pady=(padding, 4))
                
                title_label = tk.Label(title_frame, text=title, 
                                      font=("微软雅黑", 11, "bold"),
                                      bg=card_bg, 
                                      fg=theme.get("accent_dark", "#388E3C"))
                title_label.pack(anchor=tk.W)
                
                separator = tk.Frame(title_frame, bg=card_border, height=1)
                separator.pack(fill=tk.X, pady=(8, 0))
                
                content_frame = tk.Frame(inner_frame, bg=card_bg)
                content_frame.pack(fill=tk.BOTH, expand=True, padx=padding, pady=(4, padding))
            else:
                content_frame = tk.Frame(inner_frame, bg=card_bg)
                content_frame.pack(fill=tk.BOTH, expand=True, padx=padding, pady=padding)
                content_frame._outer_frame = outer_frame
                return content_frame
            
            content_frame._outer_frame = outer_frame
            return content_frame
        else:
            if title:
                frame = tk.LabelFrame(parent, text=title, 
                                     bg=theme["frame_bg"], 
                                     fg=theme["fg"],
                                     font=("微软雅黑", 10, "bold"),
                                     padx=padding, pady=padding,
                                     relief="solid", bd=1)
            else:
                frame = tk.Frame(parent, bg=theme["frame_bg"])
            return frame
    
    def create_card_button(self, parent, text, command=None, **kwargs):
        """创建卡片风格按钮
        
        Args:
            parent: 父容器
            text: 按钮文字
            command: 点击回调
            **kwargs: 其他参数
            
        Returns:
            按钮对象
        """
        theme = self.theme_manager.get_theme(self.current_theme)
        is_bamboo = self.current_theme == "bamboo"
        
        if is_bamboo:
            btn = tk.Button(parent, text=text, command=command,
                          bg=theme["button_bg"],
                          fg=theme["button_fg"],
                          activebackground=theme["button_active_bg"],
                          activeforeground=theme.get("accent_dark", "#388E3C"),
                          relief="flat",
                          bd=0,
                          font=("微软雅黑", 10),
                          padx=16,
                          pady=8,
                          cursor="hand2",
                          **kwargs)
        else:
            btn = tk.Button(parent, text=text, command=command,
                          bg=theme["button_bg"],
                          fg=theme["button_fg"],
                          activebackground=theme["button_active_bg"],
                          activeforeground=theme["button_active_fg"],
                          relief="raised",
                          bd=1,
                          font=("微软雅黑", 10),
                          padx=10,
                          pady=5,
                          **kwargs)
        return btn
    
    def create_card_entry(self, parent, **kwargs):
        """创建卡片风格输入框
        
        Args:
            parent: 父容器
            **kwargs: 其他参数
            
        Returns:
            输入框对象
        """
        theme = self.theme_manager.get_theme(self.current_theme)
        is_bamboo = self.current_theme == "bamboo"
        
        if is_bamboo:
            entry = tk.Entry(parent,
                           bg=theme["entry_bg"],
                           fg=theme["entry_fg"],
                           insertbackground=theme.get("accent", "#4CAF50"),
                           relief="flat",
                           bd=0,
                           highlightbackground=theme.get("card_border", "#A5D6A7"),
                           highlightcolor=theme.get("accent", "#4CAF50"),
                           highlightthickness=1,
                           font=("微软雅黑", 10),
                           **kwargs)
        else:
            entry = tk.Entry(parent,
                           bg=theme["entry_bg"],
                           fg=theme["entry_fg"],
                           insertbackground=theme["fg"],
                           relief="solid",
                           bd=1,
                           highlightbackground=theme["entry_glow"],
                           highlightcolor=theme["entry_glow"],
                           highlightthickness=1,
                           **kwargs)
        return entry
    
    def create_card_text(self, parent, height=10, **kwargs):
        """创建卡片风格文本区域
        
        Args:
            parent: 父容器
            height: 高度
            **kwargs: 其他参数
            
        Returns:
            文本区域对象
        """
        theme = self.theme_manager.get_theme(self.current_theme)
        is_bamboo = self.current_theme == "bamboo"
        
        if is_bamboo:
            text = scrolledtext.ScrolledText(parent, height=height,
                                           bg=theme["text_bg"],
                                           fg=theme["text_fg"],
                                           insertbackground=theme.get("accent", "#4CAF50"),
                                           relief="flat",
                                           bd=0,
                                           highlightbackground=theme.get("card_border", "#A5D6A7"),
                                           highlightcolor=theme.get("accent", "#4CAF50"),
                                           highlightthickness=1,
                                           font=("微软雅黑", 10),
                                           padx=10,
                                           pady=10,
                                           wrap=tk.WORD,
                                           **kwargs)
        else:
            text = scrolledtext.ScrolledText(parent, height=height,
                                           bg=theme["text_bg"],
                                           fg=theme["text_fg"],
                                           insertbackground=theme["fg"],
                                           relief="solid",
                                           bd=1,
                                           highlightbackground=theme["entry_glow"],
                                           highlightcolor=theme["entry_glow"],
                                           highlightthickness=1,
                                           wrap=tk.WORD,
                                           **kwargs)
        return text
    
    def create_card_listbox(self, parent, height=10, **kwargs):
        """创建卡片风格列表框
        
        Args:
            parent: 父容器
            height: 高度
            **kwargs: 其他参数
            
        Returns:
            列表框对象
        """
        theme = self.theme_manager.get_theme(self.current_theme)
        is_bamboo = self.current_theme == "bamboo"
        
        if is_bamboo:
            listbox = tk.Listbox(parent, height=height,
                               bg=theme["text_bg"],
                               fg=theme["text_fg"],
                               selectbackground=theme["highlight"],
                               selectforeground=theme.get("accent_dark", "#388E3C"),
                               relief="flat",
                               bd=0,
                               highlightthickness=1,
                               highlightbackground=theme.get("card_border", "#A5D6A7"),
                               highlightcolor=theme.get("accent", "#4CAF50"),
                               font=("微软雅黑", 10),
                               **kwargs)
        else:
            listbox = tk.Listbox(parent, height=height,
                               bg=theme["text_bg"],
                               fg=theme["text_fg"],
                               selectbackground=theme["highlight"],
                               relief="solid",
                               bd=1,
                               **kwargs)
        return listbox
    
