    def apply_theme(self, theme_name):
        """应用主题"""
        self.current_theme = theme_name
        theme = self.theme_manager.get_theme(theme_name)
        
        self.config_manager.save_user_preference('theme', theme_name)
        
        style = ttk.Style()
        
        # 配置ttk按钮样式 - 半透明白色毛玻璃效果
        style.configure("Glass.TButton",
                       background=theme["button_bg"],
                       foreground=theme["button_fg"],
                       borderwidth=1,
                       relief="raised",
                       padding=8,
                       font=("微软雅黑", 10))
        
        style.map("Glass.TButton",
                 background=[('active', theme["button_active_bg"])],
                 foreground=[('active', theme["button_fg"])],
                 relief=[('pressed', 'sunken')])
        
        # 配置ttk输入框样式 - 添加光晕效果
        style.configure("Glass.TEntry",
                       fieldbackground=theme["entry_bg"],
                       foreground=theme["entry_fg"],
                       borderwidth=1,
                       relief="solid")
        
        style.map("Glass.TEntry",
                 fieldbackground=[('focus', theme["entry_glow"])],
                 bordercolor=[('focus', theme["entry_glow"])])
        
        # 配置ttk下拉框样式 - 添加光晕效果
        style.configure("Glass.TCombobox",
                       fieldbackground=theme["entry_bg"],
                       foreground=theme["entry_fg"],
                       borderwidth=1,
                       relief="solid",
                       arrowcolor=theme["fg"])
        
        style.map("Glass.TCombobox",
                 fieldbackground=[('focus', theme["entry_glow"])],
                 bordercolor=[('focus', theme["entry_glow"])])
        
        # 配置ttk框架样式
        style.configure("Glass.TFrame",
                       background=theme["frame_bg"])
        
        # 配置ttk标签样式
        style.configure("Glass.TLabel",
                       background=theme["label_bg"],
                       foreground=theme["label_fg"],
                       font=("宋体", 10))
        
        # 配置ttk标签框架样式
