            style.configure("Bamboo.TLabelframe.Label",
                           background=theme["frame_bg"],
                           foreground=accent_dark,
                           font=("微软雅黑", 10, "bold"))
            
            style.configure("Bamboo.Vertical.TScrollbar",
                           background=accent_light,
                           troughcolor=theme["scrollbar_trough"],
                           borderwidth=0,
                           relief="flat",
                           arrowsize=12)
            
            style.configure("Bamboo.Horizontal.TScrollbar",
                           background=accent_light,
                           troughcolor=theme["scrollbar_trough"],
                           borderwidth=0,
                           relief="flat",
                           arrowsize=12)
            
            style.configure("Bamboo.TNotebook",
                           background=theme["notebook_bg"],
                           tabmargins=[4, 4, 4, 0],
                           borderwidth=0)
            
            style.configure("Bamboo.TNotebook.Tab",
                           background=theme["tab_bg"],
                           foreground=theme["tab_fg"],
                           padding=[16, 8],
                           font=("微软雅黑", 10))
            
            style.map("Bamboo.TNotebook.Tab",
                     background=[('selected', theme["tab_active_bg"])],
                     foreground=[('selected', accent_dark)])
            
            style.configure("Bamboo.Treeview",
                           background=theme["tree_bg"],
                           foreground=theme["tree_fg"],
                           fieldbackground=theme["tree_bg"],
                           borderwidth=0,
                           font=("微软雅黑", 10),
                           rowheight=28)
            
            style.configure("Bamboo.Treeview.Heading",
                           background=theme["tree_heading_bg"],
                           foreground=accent_dark,
                           borderwidth=0,
                           font=("微软雅黑", 10, "bold"))
            
