    def load_template_list(self):
        """加载模板列表"""
        self.template_listbox.delete(0, tk.END)
        templates = self.config_manager.get_prompt_templates()
        for template_name in templates:
            self.template_listbox.insert(tk.END, template_name)
    
    def on_template_selected(self, event):
        """模板列表选择事件"""
        selection = self.template_listbox.curselection()
        if selection:
            template_name = self.template_listbox.get(selection[0])
            templates = self.config_manager.get_prompt_templates()
            if template_name in templates:
                self.template_name_entry.delete(0, tk.END)
                self.template_name_entry.insert(0, template_name)
                self.template_content_text.delete(1.0, tk.END)
                self.template_content_text.insert(1.0, templates[template_name])
    
    def save_prompt_template(self):
        """保存提示词模板"""
        template_name = self.template_name_entry.get().strip()
        template_content = self.template_content_text.get(1.0, tk.END).strip()
        
        if not template_name:
            messagebox.showerror("错误", "模板名称不能为空！")
            return
        
        if not template_content:
            messagebox.showerror("错误", "模板内容不能为空！")
            return
        
        self.config_manager.save_prompt_template(template_name, template_content)
        messagebox.showinfo("成功", "模板保存成功！")
        self.load_template_list()
    
    def load_prompt_template(self):
        """加载提示词模板"""
        selection = self.template_listbox.curselection()
        if not selection:
            messagebox.showerror("错误", "请先选择一个模板！")
            return
        
        template_name = self.template_listbox.get(selection[0])
        templates = self.config_manager.get_prompt_templates()
        if template_name in templates:
            self.template_name_entry.delete(0, tk.END)
            self.template_name_entry.insert(0, template_name)
            self.template_content_text.delete(1.0, tk.END)
            self.template_content_text.insert(1.0, templates[template_name])
    
    def show_template_context_menu(self, event):
        """显示模板列表右键菜单"""
        try:
            self.template_listbox.selection_clear(0, tk.END)
            self.template_listbox.selection_set(self.template_listbox.nearest(event.y))
        except:
            pass
        self.template_context_menu.tk_popup(event.x_root, event.y_root)
    
    def delete_prompt_template(self):
        """删除提示词模板"""
        selection = self.template_listbox.curselection()
        if not selection:
            messagebox.showerror("错误", "请先选择一个模板！")
            return
        
        template_name = self.template_listbox.get(selection[0])
        if messagebox.askyesno("确认删除", f"确定要删除模板 '{template_name}' 吗？"):
            self.config_manager.delete_prompt_template(template_name)
            messagebox.showinfo("成功", "模板删除成功！")
            self.load_template_list()
            self.clear_prompt_template()
    
    def clear_prompt_template(self):
        """清空模板编辑区域"""
        self.template_name_entry.delete(0, tk.END)
        self.template_content_text.delete(1.0, tk.END)
    
