        history_buttons_frame.pack(fill=tk.X, pady=8)
        
        self.load_history_button = tk.Button(history_buttons_frame, text="加载记录",
                                            command=self.load_history_record,
                                            bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                                            activeforeground=theme["button_fg"], relief="raised", bd=1)
        self.load_history_button.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 5))
        
        self.delete_history_button = tk.Button(history_buttons_frame, text="删除记录",
                                             command=self.delete_history_record,
                                             bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                                             activeforeground=theme["button_fg"], relief="raised", bd=1)
        self.delete_history_button.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 5))
        
        self.clear_history_button = tk.Button(history_buttons_frame, text="清空历史",
                                             command=self.clear_all_history,
                                             bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                                             activeforeground=theme["button_fg"], relief="raised", bd=1)
        self.clear_history_button.pack(side=tk.LEFT, fill=tk.X, expand=True)
        
        # 右侧历史记录内容
        right_frame = tk.LabelFrame(main_container, text="记录内容", bg=theme["frame_bg"], fg=theme["fg"],
                                  padx=12, pady=8, bd=1, relief="solid")
        right_frame.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)
        
        # 历史记录内容编辑框
        content_frame = tk.Frame(right_frame, bg=theme["frame_bg"])
        content_frame.pack(fill=tk.BOTH, expand=True)
        
        self.history_content_text = scrolledtext.ScrolledText(content_frame, height=25, font=("宋体", 10),
                                                             wrap=tk.WORD, bg=theme["text_bg"], fg=theme["text_fg"],
                                                             relief="solid", bd=1)
