    def create_continue_detailed_chapter_context_menu(self):
        """为续写细纲的章节列表创建右键菜单"""
        self.continue_detailed_chapter_context_menu = tk.Menu(self.root, tearoff=0)
        self.continue_detailed_chapter_context_menu.add_command(label="删除选中项", command=self.delete_selected_continue_detailed_chapters)
        self.continue_detailed_chapter_context_menu.add_separator()
        self.continue_detailed_chapter_context_menu.add_command(label="清空列表", command=self.clear_continue_existing_chapters)
        
        self.continue_existing_chapters_listbox.bind("<Button-3>", self.show_continue_detailed_chapter_context_menu)
    
    def show_continue_detailed_chapter_context_menu(self, event):
        """显示续写细纲章节列表的右键菜单"""
        try:
            self.continue_detailed_chapter_context_menu.tk_popup(event.x_root, event.y_root)
        finally:
            self.continue_detailed_chapter_context_menu.grab_release()
    
    def delete_selected_continue_detailed_chapters(self):
        """删除选中的续写细纲章节"""
        selected_indices = self.continue_existing_chapters_listbox.curselection()
        if selected_indices:
            # 倒序删除，避免索引变化
            for index in reversed(selected_indices):
                self.continue_existing_chapters_listbox.delete(index)
            self.check_continue_detailed_conditions()
    
    def select_outline_for_detailed(self):
        """选择用于生成细纲的大纲文件"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        outline_dir = self.file_manager.outline_dir
        outline_files = self.file_manager.get_files_in_dir(outline_dir)
        
        if not outline_files:
            result = messagebox.askyesno("提示", "大纲目录为空，是否上传大纲文件？")
            if result:
                self.upload_outline_for_detailed()
            return
        
        dialog = tk.Toplevel(self.root)
        dialog.title("选择大纲文件")
        dialog.geometry("800x600")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(bg=theme["bg"])
        
        saved_alpha = self.dialog_alpha_vars.get("input_window", tk.DoubleVar(value=0.97)).get()
        dialog.attributes('-alpha', saved_alpha)
        self.active_windows['input_window'] = dialog
        dialog.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('input_window', dialog))
        
        self.apply_dialog_background('input_window')
        
        tk.Label(dialog, text="请选择用于生成细纲的大纲文件:", 
                font=("微软雅黑", 12, "bold"), bg=theme["bg"], fg=theme["fg"]).pack(pady=10)
        
        list_frame = tk.Frame(dialog, bg=theme["bg"])
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        listbox = tk.Listbox(list_frame, selectmode=tk.SINGLE, height=15, font=("宋体", 11),
                           bg=theme["bg"], fg=theme["fg"], selectbackground=theme["highlight"],
                           relief="solid", bd=1)
        scrollbar = tk.Scrollbar(list_frame, orient=tk.VERTICAL, bg=theme["bg"],
                               troughcolor=theme["scrollbar_trough"], activebackground=theme["button_active_bg"])
        listbox.config(yscrollcommand=scrollbar.set)
        scrollbar.config(command=listbox.yview)
        
        for file in outline_files:
            listbox.insert(tk.END, file)
        
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        preview_frame = tk.LabelFrame(dialog, text="大纲预览", bg=theme["bg"], fg=theme["fg"],
                                    padx=10, pady=10, bd=1, relief="solid")
        preview_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        preview_text = scrolledtext.ScrolledText(preview_frame, height=10, width=80, font=("宋体", 10),
                                               bg=theme["bg"], fg=theme["fg"], relief="solid", bd=1)
        preview_text.pack(fill=tk.BOTH, expand=True)
        
        def on_select(event):
            """当选择文件时更新预览"""
            selection = listbox.curselection()
            if selection:
                filename = listbox.get(selection[0])
                content = self.file_manager.get_file_preview(outline_dir, filename, 1000)
                preview_text.delete(1.0, tk.END)
                preview_text.insert(1.0, content)
        
        listbox.bind('<<ListboxSelect>>', on_select)
        
        def on_ok():
            """确定选择"""
            selection = listbox.curselection()
            if selection:
                self.selected_outline_file = listbox.get(selection[0])
                self.selected_outline_label.config(text=self.selected_outline_file)
                
                content = self.file_manager.get_file_preview(outline_dir, self.selected_outline_file, 1000)
                self.outline_preview_text.delete(1.0, tk.END)
                self.outline_preview_text.insert(1.0, content)
                
                dialog.destroy()
                messagebox.showinfo("成功", f"已选择大纲文件: {self.selected_outline_file}")
            else:
                messagebox.showerror("错误", "请先选择一个大纲文件！")
        
        def on_cancel():
            """取消"""
            dialog.destroy()
        
        button_frame = tk.Frame(dialog, bg=theme["bg"])
        button_frame.pack(pady=10)
        
        tk.Button(button_frame, text="确定", command=on_ok, width=15,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(side=tk.LEFT, padx=10)
        tk.Button(button_frame, text="取消", command=on_cancel, width=15,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(side=tk.LEFT, padx=10)
    
    def upload_outline_for_detailed(self):
        """上传大纲文件用于生成细纲"""
        filepath = filedialog.askopenfilename(
            title="选择要上传的大纲文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if not filepath:
            return
        
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
            
            filename = os.path.basename(filepath)
            save_path = os.path.join(self.file_manager.outline_dir, filename)
            
            with open(save_path, 'w', encoding='utf-8') as f:
                f.write(content)
            
            messagebox.showinfo("成功", f"大纲文件已上传: {filename}")
            
            self.selected_outline_file = filename
            self.selected_outline_label.config(text=filename)
            
            content_preview = self.file_manager.get_file_preview(self.file_manager.outline_dir, filename, 1000)
            self.outline_preview_text.delete(1.0, tk.END)
            self.outline_preview_text.insert(1.0, content_preview)
            
        except Exception as e:
            messagebox.showerror("错误", f"上传大纲文件失败: {str(e)}")
    
    def select_detailed_outline_dir(self):
        """选择细纲目录"""
        directory = filedialog.askdirectory(
            title="选择细纲目录",
            initialdir=self.file_manager.detailed_outline_dir
        )
        if directory:
            self.detailed_outline_dir_var.set(directory)
            self.current_detailed_outline_dir = directory
    
