    def browse_batch_outline(self):
        """浏览批量生成的大纲文件"""
        filepath = filedialog.askopenfilename(
            title="选择大纲文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if filepath:
            self.batch_outline_path.set(filepath)
    
    def browse_batch_detailed_outline(self):
        """浏览批量生成的细纲文件"""
        filepath = filedialog.askopenfilename(
            title="选择细纲文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if filepath:
            self.batch_detailed_outline_path.set(filepath)
    
    def browse_batch_save_path(self):
        """浏览批量生成的保存路径"""
        directory = filedialog.askdirectory(
            title="选择保存路径",
            initialdir=self.file_manager.chapters_dir
        )
        if directory:
            self.batch_save_path.set(directory)
    
    def start_batch_generation(self):
        """开始批量生成章节"""
        # 检查必要条件
        outline_path = self.batch_outline_path.get()
        detailed_outline_path = self.batch_detailed_outline_path.get()
        start_chapter = self.batch_start_chapter.get()
        end_chapter = self.batch_end_chapter.get()
        save_path = self.batch_save_path.get()
        
        if not outline_path or not os.path.exists(outline_path):
            messagebox.showerror("错误", "请选择有效的大纲文件！")
            return
        
        if not detailed_outline_path or not os.path.exists(detailed_outline_path):
            messagebox.showerror("错误", "请选择有效的细纲文件！")
            return
        
        try:
            start = int(start_chapter)
            end = int(end_chapter)
            if start <= 0 or end < start:
                raise ValueError
        except ValueError:
            messagebox.showerror("错误", "请输入有效的章节范围！")
            return
        
        if not save_path or not os.path.exists(save_path):
            messagebox.showerror("错误", "请选择有效的保存路径！")
            return
        
        # 禁用生成按钮，防止重复点击
        self.batch_generate_button.config(state=tk.DISABLED)
        
        # 清空状态文本
        self.batch_status_text.config(state=tk.NORMAL)
        self.batch_status_text.delete(1.0, tk.END)
        self.batch_status_text.insert(1.0, f"开始批量生成章节...\n从第{start}章到第{end}章\n")
        self.batch_status_text.config(state=tk.DISABLED)
        
        # 读取大纲和细纲内容
        try:
            with open(outline_path, 'r', encoding='utf-8') as f:
                outline_content = f.read()
            
            with open(detailed_outline_path, 'r', encoding='utf-8') as f:
                detailed_outline_content = f.read()
        except Exception as e:
            messagebox.showerror("错误", f"读取文件失败: {str(e)}")
            self.batch_generate_button.config(state=tk.NORMAL)
            return
        
        requirements = self.batch_requirements_text.get(1.0, tk.END).strip()
        genre = self.batch_genre_var.get()
        style = self.batch_style_var.get()
        
        # 启动批量生成线程
        threading.Thread(target=self.batch_generate_thread, args=(
            outline_content, detailed_outline_content, start, end, 
            requirements, genre, style, save_path
        ), daemon=True).start()
    
    def batch_generate_thread(self, outline_content, detailed_outline_content, 
                          start_chapter, end_chapter, requirements, genre, style, save_path):
        """批量生成线程"""
        generation_mode = self.batch_generation_mode.get()
        erotic_direction = self.batch_erotic_direction_var.get() if generation_mode == "色情生成" else ""
        
        for chapter_num in range(start_chapter, end_chapter + 1):
            status_message = f"正在生成第{chapter_num}章...\n"
            self.root.after(0, self.update_batch_status, status_message)
            
            try:
                chapter_detailed_content = self.extract_chapter_from_detailed_outline(detailed_outline_content, chapter_num)
                
                if not chapter_detailed_content:
                    status_message = f"警告: 未找到第{chapter_num}章的细纲内容，跳过...\n"
                    self.root.after(0, self.update_batch_status, status_message)
                    continue
                
                if generation_mode == "正常生成":
                    processor = get_normal_chapter_processor()
                    chapter_content = processor.处理生成请求(
                        outline_content, chapter_detailed_content, requirements, genre, style,
                        self.ai_service.generate_content
                    )
                    
                    if not chapter_content:
                        chapter_content = self.ai_service.generate_chapter_content_top_author(
                            outline_content, chapter_detailed_content, requirements, genre, style
                        )
                else:
                    processor = get_erotic_chapter_processor()
                    chapter_content = processor.处理生成请求(
                        outline_content, chapter_detailed_content, requirements, genre, style,
                        self.ai_service.generate_content, direction=erotic_direction
                    )
                    
                    if not chapter_content:
                        chapter_content = self.ai_service.generate_chapter_content_top_author(
                            outline_content, chapter_detailed_content, requirements, genre, style
                        )
                
                title = f"第{chapter_num}章"
                filename = f"第{chapter_num}章.txt"
                filepath = os.path.join(save_path, filename)
                
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(chapter_content)
                
                status_message = f"成功: 第{chapter_num}章已生成并保存到 {filename}\n"
                self.root.after(0, self.update_batch_status, status_message)
                
                history_id = f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - 批量生成第{chapter_num}章"
                self.config_manager.save_generation_history(history_id, chapter_content)
                
                # 短暂延迟，避免API调用过于频繁
                time.sleep(2)
                
            except Exception as e:
                status_message = f"错误: 生成第{chapter_num}章时出错 - {str(e)}\n"
                self.root.after(0, self.update_batch_status, status_message)
        
        # 生成完成
        self.root.after(0, self.batch_generation_completed)
    
    def extract_chapter_from_detailed_outline(self, detailed_outline_content, chapter_num):
        """从细纲中提取指定章节的内容"""
        # 简单实现：查找包含"第X章"的部分
        lines = detailed_outline_content.split('\n')
        chapter_content = []
        in_chapter = False
        
        for line in lines:
            # 检查是否是目标章节
            if f"第{chapter_num}章" in line:
                in_chapter = True
            elif line.startswith("第") and f"第{chapter_num}章" not in line:
                # 遇到下一章，停止收集
                if in_chapter:
                    break
            
            if in_chapter:
                chapter_content.append(line)
        
        return '\n'.join(chapter_content)
    
    def update_batch_status(self, message):
        """更新批量生成状态"""
        self.batch_status_text.config(state=tk.NORMAL)
        self.batch_status_text.insert(tk.END, message)
        self.batch_status_text.see(tk.END)
        self.batch_status_text.config(state=tk.DISABLED)
    
    def batch_generation_completed(self):
        """批量生成完成"""
        status_message = "\n批量生成完成！\n"
        self.batch_status_text.config(state=tk.NORMAL)
        self.batch_status_text.insert(tk.END, status_message)
        self.batch_status_text.see(tk.END)
        self.batch_status_text.config(state=tk.DISABLED)
        
        # 启用生成按钮
        self.batch_generate_button.config(state=tk.NORMAL)
        
        # 显示完成消息
