    def browse_rewrite_file(self):
        """浏览选择需要改写的文件"""
        file_path = filedialog.askopenfilename(
            title="选择需要改写的文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if file_path:
            self.rewrite_file_path.set(file_path)
            # 读取文件内容到输入框
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                self.rewrite_input_text.delete(1.0, tk.END)
                self.rewrite_input_text.insert(tk.END, content)
            except Exception as e:
                messagebox.showerror("错误", f"读取文件失败: {str(e)}")
    
    def clear_rewrite_input(self):
        """清空改写输入"""
        self.rewrite_input_text.delete(1.0, tk.END)
        self.rewrite_file_path.set("")
        self.rewrite_result_text.delete(1.0, tk.END)
        self.rewrite_result_text.insert(tk.END, "改写结果将在这里显示...\n\n格式：\n【原文】\n...\n\n【改写】\n...")
        self.config_manager.save_rewrite_content("")
    
    def on_rewrite_file_drop(self, event):
        """处理拖入到改写输入框的文件"""
        try:
            files = self.root.tk.splitlist(event.data)
            if files:
                file_path = files[0].strip('{}')
                if os.path.isfile(file_path):
                    # 检查文件类型
                    if file_path.lower().endswith(('.txt', '.md', '.docx', '.doc')):
                        # 读取文件内容
                        content = ""
                        if file_path.lower().endswith('.txt'):
                            with open(file_path, 'r', encoding='utf-8') as f:
                                content = f.read()
                        elif file_path.lower().endswith('.md'):
                            with open(file_path, 'r', encoding='utf-8') as f:
                                content = f.read()
                        elif file_path.lower().endswith('.docx'):
                            try:
                                import docx
                                doc = docx.Document(file_path)
                                content = '\n'.join([paragraph.text for paragraph in doc.paragraphs])
                            except ImportError:
                                messagebox.showwarning("警告", "需要安装python-docx库来读取Word文件")
                                return
                        elif file_path.lower().endswith('.doc'):
                            messagebox.showwarning("警告", "不支持旧版Word格式，请转换为docx格式")
                            return
                        
                        # 清空当前内容并插入新内容
                        self.rewrite_input_text.delete(1.0, tk.END)
                        self.rewrite_input_text.insert(tk.END, content)
                        
                        # 更新文件路径变量
                        self.rewrite_file_path.set(file_path)
                        
                        # 同时添加到已有章节列表（如果尚未存在）
                        existing_files = list(self.rewrite_existing_chapters_listbox.get(0, tk.END))
                        if file_path not in existing_files:
                            self.add_rewrite_chapter_to_list(file_path)
                        
                        # 显示成功消息
                        file_name = os.path.basename(file_path)
                        messagebox.showinfo("成功", f"已加载文件: {file_name}\n文件大小: {len(content)} 字符")
                        
                    else:
                        messagebox.showwarning("警告", "仅支持以下文件格式:\n.txt, .md, .docx")
                else:
                    messagebox.showwarning("警告", "拖入的不是有效的文件")
        except Exception as e:
            messagebox.showerror("错误", f"读取文件失败: {str(e)}")
    
