    def edit_rewrite_result_content(self):
        """编辑改写结果内容弹窗"""
        content = self.rewrite_result_text.get(1.0, tk.END).strip()
        
        dialog = tk.Toplevel(self.root)
        dialog.title("编辑改写结果")
        dialog.geometry("800x600")
        
        dialog_bg = self.config_manager.get_background()
        if dialog_bg:
            bg_type = dialog_bg.get('type', 'color')
            bg_value = dialog_bg.get('value', '#FFFFFF')
            if bg_type == 'color':
                dialog.configure(bg=bg_value)
            elif bg_type == 'image' and os.path.exists(bg_value):
                try:
                    from PIL import Image, ImageTk
                    img = Image.open(bg_value)
                    img = img.resize((800, 600), Image.Resampling.LANCZOS)
                    photo = ImageTk.PhotoImage(img)
                    bg_label = tk.Label(dialog, image=photo)
                    bg_label.image = photo
                    bg_label.place(x=0, y=0, relwidth=1, relheight=1)
                except Exception as e:
                    print(f"加载背景图片失败: {e}")
        
        text_area = scrolledtext.ScrolledText(dialog, wrap=tk.WORD, font=("宋体", 11))
        text_area.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        text_area.insert(tk.END, content)
        
        def save_content():
            new_content = text_area.get(1.0, tk.END).strip()
            self.rewrite_result_text.delete(1.0, tk.END)
            self.rewrite_result_text.insert(tk.END, new_content)
            dialog.destroy()
        
        button_frame = tk.Frame(dialog)
        button_frame.pack(fill=tk.X, padx=10, pady=10)
        
        tk.Button(button_frame, text="保存", command=save_content, width=10).pack(side=tk.RIGHT, padx=5)
        tk.Button(button_frame, text="取消", command=dialog.destroy, width=10).pack(side=tk.RIGHT, padx=5)
    
