    def browse_file_for_rewrite_input(self):
        """浏览文件并加载到改写输入框"""
        filepath = filedialog.askopenfilename(
            title="选择要改写的文件",
            filetypes=[
                ("文本文件", "*.txt"),
                ("Markdown文件", "*.md"),
                ("Word文档", "*.docx"),
                ("所有文件", "*.*")
            ]
        )
        if filepath:
            try:
                content = ""
                if filepath.lower().endswith('.txt'):
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                elif filepath.lower().endswith('.md'):
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                elif filepath.lower().endswith('.docx'):
                    try:
                        import docx
                        doc = docx.Document(filepath)
                        content = '\n'.join([paragraph.text for paragraph in doc.paragraphs])
                    except ImportError:
                        messagebox.showwarning("警告", "需要安装python-docx库来读取Word文件")
                        return
                elif filepath.lower().endswith('.doc'):
                    messagebox.showwarning("警告", "不支持旧版Word格式，请转换为docx格式")
                    return
                
                # 清空当前内容并插入新内容
                self.rewrite_input_text.delete(1.0, tk.END)
                self.rewrite_input_text.insert(tk.END, content)
                
                # 更新文件路径变量
                self.rewrite_file_path.set(filepath)
                
                # 同时添加到已有章节列表（如果尚未存在）
                existing_files = list(self.rewrite_existing_chapters_listbox.get(0, tk.END))
                if filepath not in existing_files:
                    self.add_rewrite_chapter_to_list(filepath)
                
                # 显示成功消息
                file_name = os.path.basename(filepath)
                messagebox.showinfo("成功", f"已加载文件: {file_name}\n文件大小: {len(content)} 字符")
                
            except Exception as e:
                messagebox.showerror("错误", f"读取文件失败: {str(e)}")
    
