    def on_rewrite_mode_change(self, event=None):
        """
        改写模式切换事件处理
        根据选择的模式动态调整改写风格和改写方向选项
        并保存用户的选择
        """
        current_mode = self.rewrite_mode.get()
        
        if current_mode == "正常改写":
            self.rewrite_mode_hint.config(text="当前：正常改写模式，纯文学改写，不含成人内容")
            self.rewrite_style.set("出版小说")
            self.style_combobox_widget['values'] = ["出版小说", "网文", "轻小说", "古风", "玄幻", "武侠", "仙侠", "历史", "悬疑", "科幻", "奇幻", "恐怖", "网游", "末世", "异能"]
            self.rewrite_direction.set("文学润色")
            self.direction_combobox_widget['values'] = self._normal_directions
            print("[改写模式] 已切换到正常改写模式")
        else:
            self.rewrite_mode_hint.config(text="当前：色情改写模式，支持成人内容改写")
            self.rewrite_style.set("色情")
            self.style_combobox_widget['values'] = ["色情"]
            self.rewrite_direction.set("色情描写")
            self.direction_combobox_widget['values'] = self._erotic_directions
            print("[改写模式] 已切换到色情改写模式")
        
        # 保存用户的设置
        self.config_manager.save_rewrite_mode(current_mode)
        self.config_manager.save_rewrite_style(self.rewrite_style.get())
        self.config_manager.save_rewrite_direction(self.rewrite_direction.get())
    
    def _update_rewrite_mode_hint(self, mode):
        """更新改写模式说明标签"""
        if mode == "正常改写":
            self.rewrite_mode_hint.config(text="当前：正常改写模式，纯文学改写，不含成人内容")
        else:
            self.rewrite_mode_hint.config(text="当前：色情改写模式，支持成人内容改写")
    
