    def _schedule_rewrite_input_save(self, event=None):
        """延迟保存待改写内容（避免频繁保存）"""
        if self._rewrite_input_save_timer:
            self.root.after_cancel(self._rewrite_input_save_timer)
        self._rewrite_input_save_timer = self.root.after(2000, self._save_rewrite_input_immediately)
    
    def _save_rewrite_input_immediately(self, event=None):
        """立即保存待改写内容"""
        try:
            content = self.rewrite_input_text.get(1.0, tk.END).strip()
            placeholder = "在此输入需要改写的章节内容，或拖入文件..."
            if content and content != placeholder:
                self.config_manager.save_rewrite_input_content(content)
            self._rewrite_input_save_timer = None
        except Exception as e:
            print(f"[保存待改写内容] 保存失败: {e}")
    
    def _save_rewrite_result_to_file(self):
        """保存改写结果到指定文件夹"""
        try:
            content = self.rewrite_result_text.get(1.0, tk.END).strip()
            placeholder = "改写结果将在这里显示"
            
            if not content or placeholder in content:
                messagebox.showwarning("提示", "没有可保存的改写结果，请先进行改写")
                return
            
            # 获取程序根目录的上一级目录
            program_dir = os.path.dirname(os.path.abspath(__file__))
            parent_dir = os.path.dirname(program_dir)
            
            # 改写文件夹路径
            rewrite_folder = os.path.join(parent_dir, "改写")
            
            # 如果文件夹不存在则创建
            if not os.path.exists(rewrite_folder):
                os.makedirs(rewrite_folder)
            
            # 生成文件名（使用时间戳）
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            rewrite_mode = self.rewrite_mode.get()
            direction = self.rewrite_direction.get()
            
            # 根据改写模式生成不同的文件名前缀
            if rewrite_mode == "正常改写":
                prefix = "正常改写"
            else:
                prefix = f"色情改写_{direction}"
            
            filename = f"{prefix}_{timestamp}.txt"
            filepath = os.path.join(rewrite_folder, filename)
            
            # 写入文件
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(f"改写模式: {rewrite_mode}\n")
                f.write(f"改写方向: {direction}\n")
                f.write(f"改写风格: {self.rewrite_style.get()}\n")
                f.write(f"保存时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.write("=" * 50 + "\n\n")
                f.write(content)
            
            messagebox.showinfo("保存成功", f"改写结果已保存到:\n{filepath}")
            
        except Exception as e:
            messagebox.showerror("保存失败", f"保存失败: {e}")
    
    def regenerate_rewrite(self):
        """重新生成改写结果"""
        self.start_chapter_rewrite()
    
    def start_chapter_rewrite(self):
        """开始章节改写"""
        try:
            # 获取输入内容
            input_content = self.rewrite_input_text.get(1.0, tk.END).strip()
            
            if not input_content:
                messagebox.showwarning("警告", "请输入需要改写的内容或选择文件！")
                return
            
            # 获取改写模式
            rewrite_mode = self.rewrite_mode.get()
            
            # 获取改写风格
            style = self.rewrite_style.get()
            
            # 获取改写方向
            direction = self.rewrite_direction.get()
            
            # 获取自定义改写要求
            custom_requirement = self.rewrite_custom_requirement.get(1.0, tk.END).strip()
            
            # 获取下一章开头
            next_chapter = self.rewrite_next_chapter.get(1.0, tk.END).strip()
            
            # 读取已有章节内容
            existing_chapters_content = ""
            existing_chapters_files = list(self.rewrite_existing_chapters_listbox.get(0, tk.END))
            if existing_chapters_files:
                print(f"[改写系统] 读取已有章节内容，共 {len(existing_chapters_files)} 个文件")
                for i, filepath in enumerate(existing_chapters_files):
                    try:
                        if os.path.exists(filepath):
                            with open(filepath, 'r', encoding='utf-8') as f:
                                chapter_content = f.read().strip()
                                existing_chapters_content += f"\n\n========== 已有章节 {i+1}: {os.path.basename(filepath)} ==========\n\n{chapter_content}"
                    except Exception as e:
                        print(f"[改写系统] 读取已有章节失败 {filepath}: {e}")
            
            # 禁用改写按钮
            self.rewrite_button.config(state=tk.DISABLED)
            
            # 显示正在改写
            self.rewrite_result_text.delete(1.0, tk.END)
            self.rewrite_result_text.insert(tk.END, f"正在改写中（{rewrite_mode}），请稍候...\n")
            
            # 在后台线程中执行改写
            def rewrite_thread():
                try:
                    # 调用AI服务进行改写，传入改写模式、改写风格、改写方向、自定义改写要求、下一章开头和已有章节内容
                    result = self.ai_service.rewrite_chapter(input_content, style, custom_requirement, next_chapter, direction, rewrite_mode=rewrite_mode, existing_chapters=existing_chapters_content)
                    
                    # 在主线程中更新UI
                    self.root.after(0, self.display_rewrite_result, input_content, result)
                except Exception as e:
                    error_msg = f"改写失败: {str(e)}"
                    self.root.after(0, self.display_rewrite_error, error_msg)
            
            thread = threading.Thread(target=rewrite_thread)
            thread.daemon = True
            thread.start()
        except Exception as e:
            messagebox.showerror("错误", f"启动改写失败: {str(e)}\n\n请检查输入是否正确。")
    
    def display_rewrite_result(self, original_content, rewritten_content):
        """显示改写结果"""
        self.rewrite_result_text.delete(1.0, tk.END)
        
        # 配置文本标签颜色
        self.rewrite_result_text.tag_configure("label", font=("宋体", 11, "bold"))
        self.rewrite_result_text.tag_configure("content", foreground="#008000")
        
        # 显示改写内容（绿色高亮）
        self.rewrite_result_text.insert(tk.END, "【改写结果】\n", "label")
        self.rewrite_result_text.insert(tk.END, rewritten_content, "content")
        
        # 保存改写内容
        self.config_manager.save_rewrite_content(rewritten_content)
        
        # 启用改写按钮
        self.rewrite_button.config(state=tk.NORMAL)
        
        # 显示完成消息
        messagebox.showinfo("完成", "章节改写完成！")
    
    def display_rewrite_error(self, error_msg):
        """显示改写错误"""
        self.rewrite_result_text.delete(1.0, tk.END)
        self.rewrite_result_text.insert(tk.END, error_msg)
        
        # 启用改写按钮
        self.rewrite_button.config(state=tk.NORMAL)
        
        # 显示错误消息
        messagebox.showerror("错误", error_msg)
    
    def create_generation_module(self):
        """创建生成内容模块界面"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        # 创建主容器
        main_container = tk.Frame(self.generation_frame, bg=theme["bg"])
        main_container.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        
        # 标题
        title_frame = tk.Frame(main_container, bg=theme["bg"])
        title_frame.pack(fill=tk.X, pady=(0, 8))
        
        tk.Label(title_frame, text="AI生成内容", font=("微软雅黑", 14, "bold"), 
                bg=theme["bg"], fg=theme["fg"], padx=15, pady=3).pack(fill=tk.X)
        
        # 主要内容区域
