    def count_generated_words(self, event=None):
        """统计生成内容字数"""
        content = self.generated_text.get(1.0, tk.END)
        chinese_chars = sum(1 for c in content if '\u4e00' <= c <= '\u9fff')
        other_chars = sum(1 for c in content if c.isprintable() and c != ' ' and not ('\u4e00' <= c <= '\u9fff'))
        word_count = chinese_chars + other_chars
        
        # 更新字数显示
        self.generated_word_count_label.config(text=f"字数: {word_count}")
    
    def show_generated_context_menu(self, event=None):
        """显示生成内容文本的右键菜单"""
        # 根据是否有选中内容来启用/禁用复制和剪切菜单项
        try:
            selected = self.generated_text.get(tk.SEL_FIRST, tk.SEL_LAST)
            has_selection = bool(selected)
        except tk.TclError:
            has_selection = False
        
        self.generated_context_menu.entryconfig("复制", state=tk.NORMAL if has_selection else tk.DISABLED)
        self.generated_context_menu.entryconfig("剪切", state=tk.NORMAL if has_selection else tk.DISABLED)
        
        # 显示右键菜单
        self.generated_context_menu.tk_popup(event.x_root, event.y_root)
    
    def select_all_generated_text(self, event=None):
        """全选生成内容"""
        self.generated_text.tag_add(tk.SEL, "1.0", tk.END)
        self.generated_text.mark_set(tk.INSERT, "1.0")
        self.generated_text.see(tk.INSERT)
        return "break"
    
    def copy_generated_text(self, event=None):
        """复制生成内容"""
        try:
            selected = self.generated_text.get(tk.SEL_FIRST, tk.SEL_LAST)
            self.root.clipboard_clear()
            self.root.clipboard_append(selected)
        except tk.TclError:
            pass
        return "break"
    
    def cut_generated_text(self, event=None):
        """剪切生成内容"""
        try:
            selected = self.generated_text.get(tk.SEL_FIRST, tk.SEL_LAST)
            self.root.clipboard_clear()
            self.root.clipboard_append(selected)
            self.generated_text.delete(tk.SEL_FIRST, tk.SEL_LAST)
        except tk.TclError:
            pass
        return "break"
    
    def paste_generated_text(self, event=None):
        """粘贴生成内容"""
        try:
            clipboard = self.root.clipboard_get()
            if clipboard:
                self.generated_text.insert(tk.INSERT, clipboard)
        except tk.TclError:
            pass
        return "break"
    
    def undo_generated_text(self, event=None):
        """撤销"""
        try:
            self.generated_text.edit_undo()
        except tk.TclError:
            # 如果内置撤销失败，使用我们的管理器
            self.undo_redo_manager.undo(self.generated_text)
        return "break"
    
    def redo_generated_text(self, event=None):
        """重做"""
        try:
            self.generated_text.edit_redo()
        except tk.TclError:
            # 如果内置重做失败，使用我们的管理器
            self.undo_redo_manager.redo(self.generated_text)
        return "break"
    
    def undo_text_widget(self, widget, widget_name="文本控件"):
        """通用撤销方法，适用于所有文本控件"""
        try:
            # 首先尝试使用内置的撤销功能
            widget.edit_undo()
            return True
        except tk.TclError:
            # 如果内置撤销失败，使用我们的管理器
            return self.undo_redo_manager.undo(widget)
        except Exception as e:
            print(f"撤销失败: {e}")
            return False
    
    def redo_text_widget(self, widget, widget_name="文本控件"):
        """通用重做方法，适用于所有文本控件"""
        try:
            # 首先尝试使用内置的重做功能
            widget.edit_redo()
            return True
        except tk.TclError:
            # 如果内置重做失败，使用我们的管理器
            return self.undo_redo_manager.redo(widget)
        except Exception as e:
            print(f"重做失败: {e}")
            return False
    
    def setup_text_widget_undo_redo(self, widget, widget_name=""):
        """为文本控件设置撤销/重做功能"""
        try:
            # 启用文本控件的撤销功能
            widget.config(undo=True, maxundo=100)
            
            # 记录初始状态
            self.undo_redo_manager.record_state(widget, widget_name)
            
            # 绑定内容变化事件
            def on_text_change(event=None):
                """文本内容变化时记录状态"""
                widget.after_idle(lambda: self.undo_redo_manager.record_state(widget, widget_name))
            
            # 绑定文本变化事件
            widget.bind("<KeyRelease>", on_text_change)
            widget.bind("<Button-1>", lambda e: widget.after(100, lambda: self.undo_redo_manager.record_state(widget, widget_name)))
            
            # 绑定撤销/重做快捷键
            widget.bind("<Control-z>", lambda e: self.undo_text_widget(widget, widget_name))
            widget.bind("<Control-y>", lambda e: self.redo_text_widget(widget, widget_name))
            
            # 绑定右键菜单
            self.create_text_widget_context_menu(widget, widget_name)
            
        except Exception as e:
            print(f"设置文本控件撤销/重做功能失败: {e}")
    
    def create_text_widget_context_menu(self, widget, widget_name=""):
        """为文本控件创建右键菜单"""
        try:
            # 创建右键菜单
            context_menu = tk.Menu(widget, tearoff=0)
            
            def show_context_menu(event):
                """显示右键菜单"""
                context_menu.delete(0, tk.END)
                
                # 添加撤销/重做选项
                history_info = self.undo_redo_manager.get_history_info(widget)
                
                context_menu.add_command(
                    label="撤销 (Ctrl+Z)",
                    command=lambda: self.undo_text_widget(widget, widget_name),
                    state="normal" if history_info["can_undo"] else "disabled"
                )
                
                context_menu.add_command(
                    label="重做 (Ctrl+Y)",
                    command=lambda: self.redo_text_widget(widget, widget_name),
                    state="normal" if history_info["can_redo"] else "disabled"
                )
                
                context_menu.add_separator()
                
                # 添加标准编辑选项
                context_menu.add_command(label="剪切", command=lambda: widget.event_generate("<<Cut>>"))
                context_menu.add_command(label="复制", command=lambda: widget.event_generate("<<Copy>>"))
                context_menu.add_command(label="粘贴", command=lambda: widget.event_generate("<<Paste>>"))
                context_menu.add_command(label="全选", command=lambda: widget.event_generate("<<SelectAll>>"))
                
                # 显示菜单
                context_menu.tk_popup(event.x_root, event.y_root)
            
            # 绑定右键点击事件
            widget.bind("<Button-3>", show_context_menu)
            
        except Exception as e:
            print(f"创建右键菜单失败: {e}")
    
    def setup_all_text_widgets_undo_redo(self):
        """为所有文本控件设置撤销/重做功能"""
        try:
            # 获取所有文本控件
            text_widgets = self.get_all_text_widgets()
            
            for widget_name, widget in text_widgets.items():
                self.setup_text_widget_undo_redo(widget, widget_name)
                
        except Exception as e:
            print(f"设置所有文本控件撤销/重做功能失败: {e}")
    
    def get_undo_redo_status(self):
        """获取所有文本控件的撤销/重做状态"""
        try:
            text_widgets = self.get_all_text_widgets()
            status = {}
            
            for widget_name, widget in text_widgets.items():
                history_info = self.undo_redo_manager.get_history_info(widget)
                status[widget_name] = history_info
                
            return status
            
        except Exception as e:
            print(f"获取撤销/重做状态失败: {e}")
            return {}
    
    def edit_generated_content(self):
        """编辑生成的内容（弹窗形式）"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        content = self.generated_text.get(1.0, tk.END).strip()
        if not content:
            messagebox.showinfo("提示", "没有可编辑的内容！")
            return
        
        content_type_map = {
            "outline": "大纲",
            "detailed_outline": "细纲",
            "chapter": "章节",
            "continuation": "续写内容"
        }
        content_type_name = content_type_map.get(self.generated_content_type, "生成内容")
        
        edit_window = tk.Toplevel(self.root)
        edit_window.title(f"编辑{content_type_name}")
        edit_window.geometry("900x700")
        edit_window.configure(bg=theme["bg"])
        edit_window.transient(self.root)
        edit_window.grab_set()
        
        saved_alpha = self.dialog_alpha_vars.get("edit_window", tk.DoubleVar(value=0.85)).get()
        edit_window.attributes('-alpha', saved_alpha)
        self.active_windows['edit_window'] = edit_window
        edit_window.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('edit_window', edit_window))
        
        self.apply_dialog_background('edit_window')
        
        title_frame = tk.Frame(edit_window, bg=theme["bg"])
        title_frame.pack(fill=tk.X, padx=10, pady=(10, 5))
        
        tk.Label(title_frame, text=f"编辑{content_type_name}", font=("微软雅黑", 12, "bold"),
                bg=theme["bg"], fg=theme["fg"]).pack(side=tk.LEFT)
        
        word_count_label = tk.Label(title_frame, text="", font=("宋体", 9),
                                   fg=theme["fg"], bg=theme["bg"])
        word_count_label.pack(side=tk.RIGHT)
        
        text_frame = tk.Frame(edit_window, bg=theme["bg"])
        text_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        text_widget = scrolledtext.ScrolledText(text_frame, wrap=tk.WORD, font=("宋体", 11),
                                               bg=theme["text_bg"], fg=theme["text_fg"],
                                               relief="solid", bd=1, undo=True)
        text_widget.pack(fill=tk.BOTH, expand=True)
        text_widget.insert(tk.END, content)
        
        def update_word_count():
            edit_content = text_widget.get(1.0, tk.END)
            chinese_chars = sum(1 for c in edit_content if '\u4e00' <= c <= '\u9fff')
            other_chars = sum(1 for c in edit_content if c.isprintable() and c != ' ' and not ('\u4e00' <= c <= '\u9fff'))
            word_count = chinese_chars + other_chars
            word_count_label.config(text=f"字数: {word_count}")
        
        text_widget.bind("<KeyRelease>", lambda e: update_word_count())
        update_word_count()
        
        button_frame = tk.Frame(edit_window, bg=theme["bg"])
        button_frame.pack(fill=tk.X, padx=10, pady=10)
        
        def save_changes():
            new_content = text_widget.get(1.0, tk.END).strip()
            
            if not new_content:
                messagebox.showwarning("警告", "内容不能为空！")
                return
            
            self.generated_content = new_content
            self.generated_text.delete(1.0, tk.END)
            self.generated_text.insert(1.0, new_content)
            self.count_generated_words()
            
            messagebox.showinfo("成功", "内容已更新！")
            edit_window.destroy()
        
        def cancel_changes():
            if messagebox.askyesno("确认", "确定要放弃修改吗？"):
                edit_window.destroy()
        
        tk.Button(button_frame, text="保存修改", command=save_changes,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_fg"], relief="raised", bd=1,
                 font=("宋体", 9)).pack(side=tk.RIGHT, padx=(5, 0))
        
        tk.Button(button_frame, text="取消", command=cancel_changes,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_fg"], relief="raised", bd=1,
                 font=("宋体", 9)).pack(side=tk.RIGHT, padx=5)
        
        tk.Button(button_frame, text="全选", command=lambda: text_widget.tag_add(tk.SEL, "1.0", tk.END),
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_fg"], relief="raised", bd=1,
                 font=("宋体", 9)).pack(side=tk.LEFT)
    
