    def collect_hotspots(self):
        """收集热点素材"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        dialog = tk.Toplevel(self.root)
        dialog.title("收集热点素材")
        dialog.geometry("600x500")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(bg=theme["bg"])
        
        saved_alpha = self.dialog_alpha_vars.get("input_window", tk.DoubleVar(value=0.97)).get()
        dialog.attributes('-alpha', saved_alpha)
        self.active_windows['input_window'] = dialog
        dialog.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('input_window', dialog))
        
        type_frame = tk.Frame(dialog, bg=theme["bg"])
        type_frame.pack(fill=tk.X, padx=10, pady=10)
        
        tk.Label(type_frame, text="素材类型:", font=("宋体", 9), bg=theme["bg"], fg=theme["fg"]).pack(side=tk.LEFT)
        
        material_type = tk.StringVar(value="热点事件")
        type_combo = ttk.Combobox(type_frame, textvariable=material_type,
                                 values=["热点事件", "好文好句", "优质评论", "金句名言", "情感语录", "励志语录"],
                                 state="readonly", width=15)
        type_combo.pack(side=tk.LEFT, padx=10)
        
        result_frame = tk.LabelFrame(dialog, text="收集结果", bg=theme["frame_bg"], fg=theme["fg"],
                                    padx=10, pady=5)
        result_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        result_text = tk.Text(result_frame, height=20, font=("宋体", 10),
                             bg=theme["text_bg"], fg=theme["text_fg"], wrap=tk.WORD)
        result_text.pack(fill=tk.BOTH, expand=True)
        
        def start_collect():
            result_text.delete(1.0, tk.END)
            result_text.insert(tk.END, f"正在收集【{material_type.get()}】素材，请稍候...\n\n")
            
            def collect_thread():
                try:
                    result = self.ai_service.collect_hotspots_with_fallback(material_type.get())
                    self.root.after(0, lambda: display_result(result))
                except Exception as e:
                    self.root.after(0, lambda: display_result(f"收集失败: {str(e)}"))
            
            thread = threading.Thread(target=collect_thread)
            thread.daemon = True
            thread.start()
        
        def display_result(result):
            result_text.delete(1.0, tk.END)
            result_text.insert(tk.END, result)
        
        def save_to_materials():
            content = result_text.get(1.0, tk.END).strip()
            if not content or "正在收集" in content:
                messagebox.showwarning("提示", "请先收集素材！")
                return
            
            material = {
                "id": datetime.now().strftime('%Y%m%d%H%M%S%f'),
                "type": material_type.get(),
                "source": "AI收集",
                "content": content,
                "tags": [material_type.get()],
                "created_at": datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            }
            
            self.copywriting_materials.append(material)
            self.save_copywriting_materials()
            self.update_materials_count()
            
            messagebox.showinfo("成功", "素材已保存到素材库！")
        
        btn_frame = tk.Frame(dialog, bg=theme["bg"])
        btn_frame.pack(fill=tk.X, pady=10)
        
        tk.Button(btn_frame, text="开始收集", command=start_collect,
                 bg=theme["button_bg"], fg=theme["button_fg"], width=12).pack(side=tk.LEFT, padx=5)
        tk.Button(btn_frame, text="保存到素材库", command=save_to_materials,
                 bg="#27AE60", fg="white", width=12).pack(side=tk.LEFT, padx=5)
        tk.Button(btn_frame, text="关闭", command=dialog.destroy,
                 bg=theme["button_bg"], fg=theme["button_fg"], width=12).pack(side=tk.RIGHT, padx=5)
    
    def view_materials(self):
        """查看已收集的素材"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        dialog = tk.Toplevel(self.root)
        dialog.title("素材库管理")
        dialog.geometry("800x600")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(bg=theme["bg"])
        
        saved_alpha = self.dialog_alpha_vars.get("input_window", tk.DoubleVar(value=0.97)).get()
        dialog.attributes('-alpha', saved_alpha)
        self.active_windows['input_window'] = dialog
        dialog.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('input_window', dialog))
        
        filter_frame = tk.Frame(dialog, bg=theme["bg"])
        filter_frame.pack(fill=tk.X, padx=10, pady=10)
        
        tk.Label(filter_frame, text="筛选类型:", font=("宋体", 9), bg=theme["bg"], fg=theme["fg"]).pack(side=tk.LEFT)
        
        filter_type = tk.StringVar(value="全部")
        filter_combo = ttk.Combobox(filter_frame, textvariable=filter_type,
                                   values=["全部", "热点事件", "好文好句", "优质评论", "金句名言", "情感语录", "励志语录"],
                                   state="readonly", width=12)
        filter_combo.pack(side=tk.LEFT, padx=10)
        
        tk.Label(filter_frame, text="搜索:", font=("宋体", 9), bg=theme["bg"], fg=theme["fg"]).pack(side=tk.LEFT, padx=(20, 5))
        
        search_var = tk.StringVar()
        search_entry = tk.Entry(filter_frame, textvariable=search_var, width=20,
                               bg=theme["entry_bg"], fg=theme["entry_fg"])
        search_entry.pack(side=tk.LEFT)
        
        list_frame = tk.Frame(dialog, bg=theme["bg"])
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        list_scrollbar = tk.Scrollbar(list_frame, orient=tk.VERTICAL, bg=theme.get("scrollbar_bg", "#E0E0E0"))
        list_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        materials_listbox = tk.Listbox(list_frame, font=("宋体", 10),
                                       bg=theme["entry_bg"], fg=theme["entry_fg"],
                                       yscrollcommand=list_scrollbar.set, selectmode=tk.EXTENDED)
        materials_listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        list_scrollbar.config(command=materials_listbox.yview)
        
        detail_frame = tk.LabelFrame(dialog, text="素材详情", bg=theme["frame_bg"], fg=theme["fg"],
                                    padx=10, pady=5)
        detail_frame.pack(fill=tk.X, padx=10, pady=5)
        
        detail_text = tk.Text(detail_frame, height=6, font=("宋体", 10),
                             bg=theme["text_bg"], fg=theme["text_fg"], wrap=tk.WORD)
        detail_text.pack(fill=tk.X)
        
        def refresh_list():
            materials_listbox.delete(0, tk.END)
            current_filter = filter_type.get()
            search_keyword = search_var.get().lower()
            
            for i, m in enumerate(self.copywriting_materials):
                if current_filter != "全部" and m.get("type") != current_filter:
                    continue
                if search_keyword and search_keyword not in m.get("content", "").lower():
                    continue
                materials_listbox.insert(tk.END, f"[{m.get('type')}] {m.get('content', '')[:50]}...")
        
        def show_detail(event):
            selection = materials_listbox.curselection()
            if selection:
                idx = selection[0]
                current_filter = filter_type.get()
                search_keyword = search_var.get().lower()
                
                filtered = []
                for m in self.copywriting_materials:
                    if current_filter != "全部" and m.get("type") != current_filter:
                        continue
                    if search_keyword and search_keyword not in m.get("content", "").lower():
                        continue
                    filtered.append(m)
                
                if idx < len(filtered):
                    m = filtered[idx]
                    detail_text.delete(1.0, tk.END)
                    detail_text.insert(tk.END, f"类型: {m.get('type')}\n")
                    detail_text.insert(tk.END, f"来源: {m.get('source')}\n")
                    detail_text.insert(tk.END, f"标签: {', '.join(m.get('tags', []))}\n")
                    detail_text.insert(tk.END, f"时间: {m.get('created_at')}\n")
                    detail_text.insert(tk.END, f"\n内容:\n{m.get('content')}")
        
        def delete_selected():
            selection = materials_listbox.curselection()
            if not selection:
                messagebox.showwarning("提示", "请先选择要删除的素材！")
                return
            
            if messagebox.askyesno("确认", f"确定要删除选中的 {len(selection)} 条素材吗？"):
                current_filter = filter_type.get()
                search_keyword = search_var.get().lower()
                
                filtered_indices = []
                for i, m in enumerate(self.copywriting_materials):
                    if current_filter != "全部" and m.get("type") != current_filter:
                        continue
                    if search_keyword and search_keyword not in m.get("content", "").lower():
                        continue
                    filtered_indices.append(i)
                
                indices_to_delete = [filtered_indices[i] for i in selection if i < len(filtered_indices)]
                for idx in sorted(indices_to_delete, reverse=True):
                    if idx < len(self.copywriting_materials):
                        del self.copywriting_materials[idx]
                
                self.save_copywriting_materials()
                refresh_list()
                detail_text.delete(1.0, tk.END)
        
        materials_listbox.bind('<<ListboxSelect>>', show_detail)
        filter_combo.bind('<<ComboboxSelected>>', lambda e: refresh_list())
        search_entry.bind('<KeyRelease>', lambda e: refresh_list())
        
        btn_frame = tk.Frame(dialog, bg=theme["bg"])
        btn_frame.pack(fill=tk.X, pady=10)
        
        tk.Button(btn_frame, text="删除选中", command=delete_selected,
                 bg="#E74C3C", fg="white", width=12).pack(side=tk.LEFT, padx=10)
        tk.Button(btn_frame, text="清空全部", command=lambda: [self.copywriting_materials.clear(), self.save_copywriting_materials(), refresh_list()],
                 bg="#E74C3C", fg="white", width=12).pack(side=tk.LEFT, padx=10)
        tk.Button(btn_frame, text="关闭", command=dialog.destroy,
                 bg=theme["button_bg"], fg=theme["button_fg"], width=12).pack(side=tk.RIGHT, padx=10)
        
        refresh_list()
    
    def generate_copywriting_inspirations(self):
        """生成文案灵感(10条)"""
        copywriting_type = self.copywriting_type.get()
        style = self.copywriting_style.get()
        topic = self.copywriting_topic.get()
        keywords = self.copywriting_keywords.get()
        target = self.copywriting_target.get()
        requirements = self.copywriting_requirements.get()
        
        if not topic:
            messagebox.showwarning("提示", "请输入文案主题！")
            return
        
        self.inspiration_listbox.delete(0, tk.END)
        self.inspiration_listbox.insert(tk.END, "正在生成文案灵感，请稍候...")
        
        def generate_thread():
            try:
                inspirations = self.ai_service.generate_copywriting_inspirations(
                    copywriting_type=copywriting_type,
                    style=style,
                    topic=topic,
                    keywords=keywords,
                    target=target,
                    requirements=requirements,
                    materials=self.copywriting_materials
                )
                self.root.after(0, self.display_inspirations, inspirations)
            except Exception as e:
                self.root.after(0, self.show_inspiration_error, str(e))
        
        thread = threading.Thread(target=generate_thread)
        thread.daemon = True
        thread.start()
    
    def display_inspirations(self, inspirations):
        """显示生成的灵感"""
        self.inspiration_listbox.delete(0, tk.END)
        
        if not inspirations:
            self.inspiration_listbox.insert(tk.END, "未能生成灵感，请重试")
            return
        
        for i, insp in enumerate(inspirations, 1):
            self.inspiration_listbox.insert(tk.END, f"{i}. {insp[:80]}..." if len(insp) > 80 else f"{i}. {insp}")
        
        self.current_inspirations = inspirations
    
    def show_inspiration_error(self, error_msg):
        """显示灵感生成错误"""
        self.inspiration_listbox.delete(0, tk.END)
        self.inspiration_listbox.insert(tk.END, f"生成失败: {error_msg}")
        messagebox.showerror("错误", f"生成文案灵感失败: {error_msg}")
    
    def select_inspiration(self, event):
        """选择灵感作为基础"""
        selection = self.inspiration_listbox.curselection()
        if selection:
            idx = selection[0]
            if hasattr(self, 'current_inspirations') and idx < len(self.current_inspirations):
                self.selected_inspiration = self.current_inspirations[idx]
                self.copywriting_result_text.delete(1.0, tk.END)
                self.copywriting_result_text.insert(tk.END, f"已选择灵感:\n\n{self.selected_inspiration}\n\n点击\"直接生成完整文案\"按钮生成完整文案。")
    
    def generate_full_copywriting(self):
        """生成完整文案"""
        copywriting_type = self.copywriting_type.get()
        style = self.copywriting_style.get()
        topic = self.copywriting_topic.get()
        keywords = self.copywriting_keywords.get()
        target = self.copywriting_target.get()
        length = self.copywriting_length.get()
        requirements = self.copywriting_requirements.get()
        
        if not topic:
            messagebox.showwarning("提示", "请输入文案主题！")
            return
        
        self.copywriting_result_text.delete(1.0, tk.END)
        self.copywriting_result_text.insert(tk.END, "正在生成文案，请稍候...")
        
        def generate_thread():
            try:
                result = self.ai_service.generate_full_copywriting(
                    copywriting_type=copywriting_type,
                    style=style,
                    topic=topic,
                    keywords=keywords,
                    target=target,
                    length=length,
                    requirements=requirements,
                    materials=self.copywriting_materials,
                    selected_inspiration=getattr(self, 'selected_inspiration', '')
                )
                self.root.after(0, self.display_copywriting_result, result)
            except Exception as e:
                self.root.after(0, self.show_copywriting_error, str(e))
        
        thread = threading.Thread(target=generate_thread)
        thread.daemon = True
        thread.start()
    
    def display_copywriting_result(self, result):
        """显示文案结果"""
        self.copywriting_result_text.delete(1.0, tk.END)
        self.copywriting_result_text.insert(tk.END, result)
        self.current_copywriting = result
        messagebox.showinfo("完成", "文案生成完成！")
    
    def show_copywriting_error(self, error_msg):
        """显示文案生成错误"""
        self.copywriting_result_text.delete(1.0, tk.END)
        self.copywriting_result_text.insert(tk.END, f"生成失败: {error_msg}")
        messagebox.showerror("错误", f"生成文案失败: {error_msg}")
    
    def copy_copywriting_result(self):
        """复制文案结果"""
        content = self.copywriting_result_text.get(1.0, tk.END).strip()
        if content:
            self.root.clipboard_clear()
            self.root.clipboard_append(content)
            messagebox.showinfo("成功", "文案已复制到剪贴板！")
        else:
            messagebox.showwarning("提示", "没有可复制的内容！")
    
    def save_copywriting_result(self):
        """保存文案结果"""
        content = self.copywriting_result_text.get(1.0, tk.END).strip()
        if not content:
            messagebox.showwarning("提示", "没有可保存的内容！")
            return
        
        filepath = filedialog.asksaveasfilename(
            title="保存文案",
            initialdir=self.file_manager.data_dir,
            defaultextension=".txt",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        
        if filepath:
            try:
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(content)
                messagebox.showinfo("成功", f"文案已保存到: {filepath}")
            except Exception as e:
                messagebox.showerror("错误", f"保存失败: {str(e)}")
    
    def regenerate_copywriting(self):
        """重新生成文案"""
        self.generate_full_copywriting()
    
    def polish_copywriting(self):
        """优化润色文案"""
        content = self.copywriting_result_text.get(1.0, tk.END).strip()
        if not content:
            messagebox.showwarning("提示", "请先生成文案！")
            return
        
        self.copywriting_result_text.delete(1.0, tk.END)
        self.copywriting_result_text.insert(tk.END, "正在优化润色文案，请稍候...")
        
        def polish_thread():
            try:
                result = self.ai_service.polish_copywriting(
                    content=content,
                    style=self.copywriting_style.get()
                )
                self.root.after(0, self.display_copywriting_result, result)
            except Exception as e:
                self.root.after(0, self.show_copywriting_error, str(e))
        
        thread = threading.Thread(target=polish_thread)
        thread.daemon = True
        thread.start()
    
    def load_copywriting_materials(self):
        """加载文案素材"""
        try:
            materials_file = os.path.join(self.file_manager.data_dir, "copywriting_materials.json")
            if os.path.exists(materials_file):
                with open(materials_file, 'r', encoding='utf-8') as f:
                    self.copywriting_materials = json.load(f)
            self.update_materials_count()
        except Exception as e:
            print(f"加载文案素材失败: {e}")
            self.copywriting_materials = []
    
    def save_copywriting_materials(self):
        """保存文案素材"""
        try:
            materials_file = os.path.join(self.file_manager.data_dir, "copywriting_materials.json")
            with open(materials_file, 'w', encoding='utf-8') as f:
                json.dump(self.copywriting_materials, f, ensure_ascii=False, indent=2)
            self.update_materials_count()
        except Exception as e:
            print(f"保存文案素材失败: {e}")
    
    def update_materials_count(self):
        """更新素材计数"""
        if hasattr(self, 'materials_count_label'):
            self.materials_count_label.config(text=f"已收集素材: {len(self.copywriting_materials)}条")
    
