    def open_chapters_dir(self):
        """打开章节目录"""
        import subprocess
        import platform
        
        chapters_dir = self.file_manager.chapters_dir
        
        if os.path.exists(chapters_dir):
            if platform.system() == "Windows":
                os.startfile(chapters_dir)
            elif platform.system() == "Darwin":  # macOS
                subprocess.Popen(["open", chapters_dir])
            else:  # Linux
                subprocess.Popen(["xdg-open", chapters_dir])
        else:
            messagebox.showerror("错误", "章节目录不存在！")
            
    def extract_chapter_number(self, filename):
        """从文件名中提取章节号（支持中文数字和阿拉伯数字）"""
        # 中文数字映射
        chinese_nums = {'零': 0, '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, 
                       '六': 6, '七': 7, '八': 8, '九': 9, '十': 10,
                       '壹': 1, '贰': 2, '叁': 3, '肆': 4, '伍': 5, 
                       '陆': 6, '柒': 7, '捌': 8, '玖': 9, '拾': 10}
        
        # 去掉文件扩展名
        name = os.path.splitext(filename)[0]
        
        # 尝试匹配阿拉伯数字（如：第1章、第10章、1、10）
        import re
        arabic_match = re.search(r'第?(\d+)[章节期集卷]', name)
        if arabic_match:
            return int(arabic_match.group(1))
        
        # 尝试匹配纯阿拉伯数字（如：1.txt、10.txt）
        arabic_match = re.search(r'^(\d+)', name)
        if arabic_match:
            return int(arabic_match.group(1))
        
        # 尝试匹配中文数字（如：第一章、第二章）
        chinese_match = re.search(r'第([零一二三四五六七八九十壹贰叁肆伍陆柒捌玖拾]+)[章节期集卷]', name)
        if chinese_match:
            chinese_num = chinese_match.group(1)
            return self.chinese_to_arabic(chinese_num)
        
        # 如果都匹配不到，返回一个很大的数字，使其排在最后
        return 999999
    
    def chinese_to_arabic(self, chinese_num):
        """将中文数字转换为阿拉伯数字"""
        chinese_nums = {'零': 0, '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, 
                       '六': 6, '七': 7, '八': 8, '九': 9, '十': 10,
                       '壹': 1, '贰': 2, '叁': 3, '肆': 4, '伍': 5, 
                       '陆': 6, '柒': 7, '捌': 8, '玖': 9, '拾': 10}
        
        if len(chinese_num) == 1:
            return chinese_nums.get(chinese_num, 0)
        
        # 处理两位数（如：十一、十二、二十、二十一）
        if len(chinese_num) == 2:
            if chinese_num[0] == '十':
                return 10 + chinese_nums.get(chinese_num[1], 0)
            else:
                return chinese_nums.get(chinese_num[0], 0) * 10 + chinese_nums.get(chinese_num[1], 0)
        
        # 处理三位数（如：一百、一百零一、一百一十）
        if len(chinese_num) == 3:
            if chinese_num[1] == '百':
                return chinese_nums.get(chinese_num[0], 0) * 100 + chinese_nums.get(chinese_num[2], 0)
            elif chinese_num[1] == '十':
                return chinese_nums.get(chinese_num[0], 0) * 10 + chinese_nums.get(chinese_num[2], 0)
        
        # 处理更复杂的数字
        result = 0
        i = 0
        while i < len(chinese_num):
            if i + 1 < len(chinese_num) and chinese_num[i + 1] in ['百', '千', '万']:
                unit = chinese_nums.get(chinese_num[i + 1], 0)
                if unit == 100:
                    result += chinese_nums.get(chinese_num[i], 0) * 100
                elif unit == 1000:
                    result += chinese_nums.get(chinese_num[i], 0) * 1000
                elif unit == 10000:
                    result += chinese_nums.get(chinese_num[i], 0) * 10000
                i += 2
            elif chinese_num[i] == '十':
                result += 10
                i += 1
            else:
                result += chinese_nums.get(chinese_num[i], 0)
                i += 1
        
        return result
    
    def refresh_chapter_list(self):
        """刷新章节列表"""
        # 清空现有章节树
        for item in self.chapter_tree.get_children():
            self.chapter_tree.delete(item)
        
        # 获取章节目录下的所有文件
        chapters_dir = self.file_manager.chapters_dir
        chapter_files = self.file_manager.get_files_in_dir(chapters_dir)
        
        # 过滤出.txt文件
        chapter_files = [f for f in chapter_files if f.lower().endswith('.txt')]
        
        # 按章节号智能排序
        chapter_files.sort(key=self.extract_chapter_number)
        
        total_chapters = 0
        total_words = 0
        
        # 添加章节到树形视图
        for idx, filename in enumerate(chapter_files, 1):
            # 从文件名提取章节标题（去掉.txt后缀）
            chapter_title = os.path.splitext(filename)[0]
            
            # 获取文件的创建时间
            filepath = os.path.join(chapters_dir, filename)
            creation_time = os.path.getctime(filepath)
            formatted_time = datetime.fromtimestamp(creation_time).strftime("%Y-%m-%d %H:%M")
            
            # 计算文件字数
            content = self.file_manager.get_file_content(chapters_dir, filename)
            chinese_chars = sum(1 for c in content if '\u4e00' <= c <= '\u9fff')
            other_chars = sum(1 for c in content if c.isprintable() and c != ' ' and not ('\u4e00' <= c <= '\u9fff'))
            word_count = chinese_chars + other_chars
            
            # 更新统计
            total_chapters += 1
            total_words += word_count
            
            # 添加到树形视图
            self.chapter_tree.insert("", tk.END, values=(idx, chapter_title, filename, formatted_time, word_count))
        
        # 更新统计信息
        self.stats_label.config(text=f"章节: {total_chapters} | 字数: {total_words}")
        
    def import_chapter(self):
        """导入章节"""
        files = filedialog.askopenfilenames(
            title="选择章节文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        
        if files:
            chapters_dir = self.file_manager.chapters_dir
            imported_count = 0
            
            for file_path in files:
                # 获取文件名
                filename = os.path.basename(file_path)
                
                # 确保是.txt文件
                if not filename.lower().endswith('.txt'):
                    filename += '.txt'
                
                # 复制文件到章节目录
                target_path = os.path.join(chapters_dir, filename)
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                with open(target_path, 'w', encoding='utf-8') as f:
                    f.write(content)
                
                imported_count += 1
            
            messagebox.showinfo("成功", f"成功导入 {imported_count} 个章节！")
            self.refresh_chapter_list()
        
    def open_selected_chapter(self):
        """打开选中的章节"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        selected_items = self.chapter_tree.selection()
        if selected_items:
            item = selected_items[0]
            values = self.chapter_tree.item(item, "values")
            if values and len(values) >= 3:
                filename = values[2]
                chapters_dir = self.file_manager.chapters_dir
                filepath = os.path.join(chapters_dir, filename)
                
                if os.path.exists(filepath):
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                    
                    preview_window = tk.Toplevel(self.root)
                    preview_window.title(f"章节预览 - {values[1]}")
                    preview_window.geometry("800x600")
                    preview_window.configure(bg=theme["bg"])
                    preview_window.transient(self.root)
                    preview_window.grab_set()
                    
                    saved_alpha = self.dialog_alpha_vars.get("preview_window", tk.DoubleVar(value=0.85)).get()
                    preview_window.attributes('-alpha', saved_alpha)
                    self.active_windows['preview_window'] = preview_window
                    preview_window.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('preview_window', preview_window))
                    
                    self.apply_dialog_background('preview_window')
                    
                    text_widget = scrolledtext.ScrolledText(preview_window, wrap=tk.WORD, font=("宋体", 10),
                                                         bg=theme["bg"], fg=theme["fg"])
                    text_widget.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
                    
                    text_widget.insert(tk.END, content)
                    text_widget.config(state=tk.DISABLED)
        else:
            messagebox.showinfo("提示", "请先选择一个章节！")
        
    def delete_selected_chapter(self):
        """删除选中的章节（支持单个或多个）"""
        selected_items = self.chapter_tree.selection()
        
        if not selected_items:
            messagebox.showinfo("提示", "请先选择要删除的章节！")
            return
        
        # 获取所有选中的章节信息
        selected_chapters = []
        for item in selected_items:
            values = self.chapter_tree.item(item, "values")
            if values and len(values) >= 3:
                selected_chapters.append({
                    'filename': values[2],
                    'title': values[1],
                    'item': item
                })
        
        if not selected_chapters:
            messagebox.showinfo("提示", "未找到有效的章节信息！")
            return
        
        # 构建确认消息
        if len(selected_chapters) == 1:
            message = f"确定要删除章节 '{selected_chapters[0]['title']}' 吗？"
        else:
            chapter_titles = '\n'.join([f"  • {ch['title']}" for ch in selected_chapters])
            message = f"确定要删除以下 {len(selected_chapters)} 个章节吗？\n\n{chapter_titles}"
        
        if messagebox.askyesno("确认删除", message):
            chapters_dir = self.file_manager.chapters_dir
            deleted_count = 0
            failed_count = 0
            failed_files = []
            
            for chapter in selected_chapters:
                filepath = os.path.join(chapters_dir, chapter['filename'])
                
                try:
                    if os.path.exists(filepath):
                        os.remove(filepath)
                        deleted_count += 1
                    else:
                        failed_count += 1
                        failed_files.append(chapter['title'])
                except Exception as e:
                    failed_count += 1
                    failed_files.append(f"{chapter['title']} ({str(e)})")
            
            # 显示删除结果
            if failed_count == 0:
                messagebox.showinfo("成功", f"成功删除 {deleted_count} 个章节！")
            else:
                failed_list = '\n'.join([f"  • {f}" for f in failed_files])
                messagebox.showwarning("部分成功", 
                    f"成功删除 {deleted_count} 个章节\n\n"
                    f"失败 {failed_count} 个章节：\n{failed_list}")
            
            # 刷新章节列表
            self.refresh_chapter_list()
    
    def create_chapter_context_menu(self):
        """为章节树创建右键菜单"""
        self.chapter_context_menu = tk.Menu(self.root, tearoff=0)
        self.chapter_context_menu.add_command(label="修改章节", command=self.edit_selected_chapter)
        self.chapter_context_menu.add_command(label="删除章节", command=self.delete_selected_chapter)
        self.chapter_context_menu.add_separator()
        self.chapter_context_menu.add_command(label="预览章节", command=self.open_selected_chapter)
    
    def show_chapter_context_menu(self, event):
        """显示章节树的右键菜单"""
        try:
            self.chapter_context_menu.tk_popup(event.x_root, event.y_root)
        except Exception as e:
            print(f"显示右键菜单失败: {e}")
        finally:
            self.chapter_context_menu.grab_release()
    
    def edit_selected_chapter(self):
        """修改选中的章节内容"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        selected_items = self.chapter_tree.selection()
        if not selected_items:
            messagebox.showinfo("提示", "请先选择一个章节！")
            return
        
        if len(selected_items) > 1:
            messagebox.showinfo("提示", "修改章节只能选择一个章节！")
            return
        
        item = selected_items[0]
        values = self.chapter_tree.item(item, "values")
        if not values or len(values) < 3:
            messagebox.showinfo("提示", "未找到有效的章节信息！")
            return
        
        filename = values[2]
        chapter_title = values[1]
        chapters_dir = self.file_manager.chapters_dir
        filepath = os.path.join(chapters_dir, filename)
        
        if not os.path.exists(filepath):
            messagebox.showerror("错误", f"章节文件不存在: {filepath}")
            return
        
        # 读取章节内容
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
        
        # 创建编辑窗口
        edit_window = tk.Toplevel(self.root)
        edit_window.title(f"修改章节 - {chapter_title}")
        edit_window.geometry("900x700")
        edit_window.configure(bg=theme["bg"])
        edit_window.transient(self.root)
        edit_window.grab_set()
        
        saved_alpha = self.dialog_alpha_vars.get("chapter_edit_window", tk.DoubleVar(value=0.85)).get()
        edit_window.attributes('-alpha', saved_alpha)
        self.active_windows['chapter_edit_window'] = edit_window
        edit_window.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('chapter_edit_window', edit_window))
        
        self.apply_dialog_background('chapter_edit_window')
        
        # 标题栏
        title_frame = tk.Frame(edit_window, bg=theme["bg"])
        title_frame.pack(fill=tk.X, padx=10, pady=(10, 5))
        
        tk.Label(title_frame, text=f"章节标题: {chapter_title}", font=("微软雅黑", 12, "bold"),
                bg=theme["bg"], fg=theme["fg"]).pack(side=tk.LEFT)
        
        # 字数统计标签
        word_count_label = tk.Label(title_frame, text="", font=("宋体", 9),
                                   fg=theme["fg"], bg=theme["bg"])
        word_count_label.pack(side=tk.RIGHT)
        
        # 文本编辑区域
        text_frame = tk.Frame(edit_window, bg=theme["bg"])
        text_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        text_widget = scrolledtext.ScrolledText(text_frame, wrap=tk.WORD, font=("宋体", 11),
                                               bg=theme["text_bg"], fg=theme["text_fg"],
                                               relief="solid", bd=1)
        text_widget.pack(fill=tk.BOTH, expand=True)
        text_widget.insert(tk.END, content)
        
        # 更新字数统计
        def update_word_count():
            content = text_widget.get(1.0, tk.END)
            chinese_chars = sum(1 for c in content if '\u4e00' <= c <= '\u9fff')
            other_chars = sum(1 for c in content if c.isprintable() and c != ' ' and not ('\u4e00' <= c <= '\u9fff'))
            word_count = chinese_chars + other_chars
            word_count_label.config(text=f"字数: {word_count}")
        
        text_widget.bind("<KeyRelease>", lambda e: update_word_count())
        update_word_count()
        
        # 按钮区域
        button_frame = tk.Frame(edit_window, bg=theme["bg"])
        button_frame.pack(fill=tk.X, padx=10, pady=10)
        
        def save_changes():
            new_content = text_widget.get(1.0, tk.END).strip()
            
            if not new_content:
                messagebox.showwarning("警告", "章节内容不能为空！")
                return
            
            try:
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(new_content)
                messagebox.showinfo("成功", "章节内容已保存！")
                self.refresh_chapter_list()
                edit_window.destroy()
            except Exception as e:
                messagebox.showerror("错误", f"保存失败: {str(e)}")
        
        def cancel_changes():
            if messagebox.askyesno("确认", "确定要放弃修改吗？"):
                edit_window.destroy()
        
        tk.Button(button_frame, text="保存修改", command=save_changes,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_fg"], relief="raised", bd=1, width=15).pack(side=tk.RIGHT, padx=5)
        tk.Button(button_frame, text="取消", command=cancel_changes,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_fg"], relief="raised", bd=1, width=10).pack(side=tk.RIGHT, padx=5)
        
    def handle_chapter_drop(self, file_list):
        """处理拖放到章节树的文件（支持多文件批量导入）"""
        try:
            if not file_list:
                return
            
            chapters_dir = self.file_manager.chapters_dir
            
            # 分析所有文件
            valid_files = []
            non_txt_files = []
            existing_files = []
            
            for file_path in file_list:
                if not os.path.exists(file_path):
                    messagebox.showerror("错误", f"文件不存在: {file_path}")
                    continue
                
                if not os.path.isfile(file_path):
                    messagebox.showerror("错误", "请拖入文件，不是文件夹！")
                    continue
                
                filename = os.path.basename(file_path)
                
                # 检查文件扩展名
                if not filename.lower().endswith('.txt'):
                    non_txt_files.append(filename)
                    filename = os.path.splitext(filename)[0] + '.txt'
                
                # 检查目标文件是否已存在
                target_path = os.path.join(chapters_dir, filename)
                if os.path.exists(target_path):
                    existing_files.append(filename)
                
                valid_files.append({
                    'source_path': file_path,
                    'filename': filename,
                    'target_path': target_path
                })
            
            if not valid_files:
                return
            
            # 如果有非.txt文件，询问是否继续
            if non_txt_files:
                file_list_str = '\n'.join([f"  • {f}" for f in non_txt_files[:5]])
                if len(non_txt_files) > 5:
                    file_list_str += f"\n  ... 还有 {len(non_txt_files) - 5} 个文件"
                
                message = f"以下文件不是.txt文件，将自动添加.txt扩展名：\n\n{file_list_str}\n\n是否继续导入？"
                if not messagebox.askyesno("确认", message):
                    return
            
            # 如果有已存在的文件，询问是否覆盖
            if existing_files:
                file_list_str = '\n'.join([f"  • {f}" for f in existing_files[:5]])
                if len(existing_files) > 5:
                    file_list_str += f"\n  ... 还有 {len(existing_files) - 5} 个文件"
                
                message = f"以下章节文件已存在：\n\n{file_list_str}\n\n是否覆盖这些文件？"
                if not messagebox.askyesno("确认", message):
                    return
            
            # 批量导入文件
            success_count = 0
            failed_count = 0
            failed_files = []
            
            for file_info in valid_files:
                try:
                    # 读取文件内容
                    try:
                        with open(file_info['source_path'], 'r', encoding='utf-8') as f:
                            content = f.read()
                    except UnicodeDecodeError:
                        try:
                            with open(file_info['source_path'], 'r', encoding='gbk') as f:
                                content = f.read()
                        except:
                            raise Exception(f"无法读取文件，编码可能不是UTF-8或GBK")
                    
                    # 写入到章节目录
                    with open(file_info['target_path'], 'w', encoding='utf-8') as f:
                        f.write(content)
                    
                    success_count += 1
                except Exception as e:
                    failed_count += 1
                    failed_files.append(f"{file_info['filename']}: {str(e)}")
            
            # 显示导入结果
            if failed_count == 0:
                messagebox.showinfo("成功", f"成功导入 {success_count} 个章节！")
            else:
                failed_list = '\n'.join([f"  • {f}" for f in failed_files[:5]])
                if len(failed_files) > 5:
                    failed_list += f"\n  ... 还有 {len(failed_files) - 5} 个文件"
                
                messagebox.showwarning("部分成功", 
                    f"成功导入 {success_count} 个章节\n\n"
                    f"失败 {failed_count} 个章节：\n{failed_list}")
            
            self.refresh_chapter_list()
            
        except Exception as e:
            messagebox.showerror("错误", f"导入章节失败: {str(e)}")
    
