    def browse_outline_file(self):
        """浏览大纲文件"""
        filepath = filedialog.askopenfilename(
            title="选择大纲文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if filepath:
            self.outline_file_path.set(filepath)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
                    self.outline_text.delete(1.0, tk.END)
                    self.outline_text.insert(1.0, content)
            except:
                pass
    def clear_outline_text(self):
        """清空大纲编辑框"""
        self.outline_text.delete(1.0, tk.END)
        self.outline_file_path.set("")
    
    def save_user_outline(self):
        """保存用户提供的大纲"""
        if self.outline_file_path.get():
            source_file = self.outline_file_path.get()
            if not os.path.exists(source_file):
                messagebox.showerror("错误", "文件不存在！")
                return
            
            save_dir = filedialog.askdirectory(
                title="选择大纲保存目录",
                initialdir=self.file_manager.outline_dir
            )
            if not save_dir:
                return
            
            filename = os.path.basename(source_file)
            try:
                with open(source_file, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception as e:
                messagebox.showerror("错误", f"读取文件失败: {str(e)}")
                return
            
        elif self.outline_text.get(1.0, tk.END).strip():
            content = self.outline_text.get(1.0, tk.END).strip()
            save_dir = filedialog.askdirectory(
                title="选择大纲保存目录",
                initialdir=self.file_manager.outline_dir
            )
            if not save_dir:
                return
            
            filename = filedialog.asksaveasfilename(
                title="保存大纲文件",
                initialdir=save_dir,
                defaultextension=".txt",
                filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
            )
            if not filename:
                return
            
            filename = os.path.basename(filename)
        else:
            messagebox.showerror("错误", "请先提供大纲内容或选择大纲文件！")
            return
        
        try:
            # 调用AI规整大纲格式，严格保留所有原始内容
            self.status_label.config(text="正在规整大纲格式...")
            self.status_label.update()
            refined_content = self.ai_service.refine_outline(content)
            formatted_content = self.format_outline(refined_content)
            
            save_path = os.path.join(save_dir, filename)
            with open(save_path, 'w', encoding='utf-8') as f:
                f.write(formatted_content)
            
            self.status_label.config(text="就绪")
            messagebox.showinfo("成功", f"大纲已保存到:\n{save_path}")
        except Exception as e:
            self.status_label.config(text="就绪")
            messagebox.showerror("错误", f"保存失败: {str(e)}")
    
    def format_outline(self, content):
        """格式化大纲内容"""
        formatted = "=" * 40 + " 小说大纲 " + "=" * 40 + "\n\n"
        formatted += content.strip()
        formatted += "\n\n" + "=" * 40 + " 大纲结束 " + "=" * 40 + "\n"
        formatted += f"生成时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
        return formatted
    
    def ai_generate_outline(self):
        """AI生成大纲"""
        if not self.ai_service.api_key:
            messagebox.showerror("错误", "请先设置API Key！")
            self.show_api_key_dialog()
            return
        
        outline_dir = self.outline_dir_var.get()
        if not outline_dir:
            outline_dir = self.file_manager.outline_dir
            self.outline_dir_var.set(outline_dir)
        
        self.current_outline_dir = outline_dir
        existing_files = self.file_manager.get_files_in_dir(outline_dir)
        
        if existing_files:
            response = messagebox.askyesno(
                "提示", 
                f"大纲目录下已有 {len(existing_files)} 个大纲文件。\n是否继续生成新大纲？"
            )
            if not response:
                return
        
        self.notebook.select(3)
        self.current_module = "大纲模块"
        self.show_generation_requirements_dialog("outline")
    
