    def sort_writing_chapters(self):
        """按照章节顺序排列新建章节模块的已有章节列表"""
        file_count = self.writing_existing_chapters_listbox.size()
        if file_count == 0:
            return
        
        files = []
        for i in range(file_count):
            filepath = self.writing_existing_chapters_listbox.get(i)
            filename = os.path.basename(filepath)
            chapter_num = self.extract_chapter_number(filename)
            files.append({
                'filepath': filepath,
                'filename': filename,
                'chapter_num': chapter_num
            })
        
        files.sort(key=lambda x: x['chapter_num'] if x['chapter_num'] is not None else float('inf'))
        
        self.writing_existing_chapters_listbox.delete(0, tk.END)
        for file_info in files:
            self.writing_existing_chapters_listbox.insert(tk.END, file_info['filepath'])
    
