    def generate_continuation_content_async(self, outline_content, detailed_outline_content, 
                                          existing_chapters_content, extracted_content, requirements="", genre="都市情感", style="出版小说", tracking_info="", existing_chapters_paths=None):
        """异步生成续写内容 - 根据风格调用对应方法"""
        
        self.start_progress_animation("正在生成续写内容")
        
        # 检查AI追踪系统状态
        ai_tracking_enabled = self.ai_service.narrative_tracker.use_ai_tracking if hasattr(self.ai_service, 'narrative_tracker') else False
        if ai_tracking_enabled:
            print(f"[INFO] AI追踪系统已启动")
            
            # 检查数据库是否有数据
            has_data = False
            if hasattr(self.ai_service.narrative_tracker, 'character_tracker') and hasattr(self.ai_service.narrative_tracker.character_tracker, 'character_data'):
                has_data = len(self.ai_service.narrative_tracker.character_tracker.character_data) > 0
            
            if has_data:
                self.generation_status_label.config(text="AI追踪系统已启动，数据库有数据，准备生成续写内容...", fg="green")
                print(f"[INFO] AI追踪系统数据库有数据")
            else:
                self.generation_status_label.config(text="AI追踪系统已启动，但数据库为空，准备生成续写内容...", fg="orange")
                print(f"[INFO] AI追踪系统数据库为空")
        else:
            print(f"[INFO] AI追踪系统未启动")
            self.generation_status_label.config(text="AI追踪系统未启动，准备生成续写内容...", fg="orange")
        self.root.update()
        
        # 用已有章节内容更新追踪系统 - 在后台线程中执行
        def update_trackers_and_generate():
            if existing_chapters_content and existing_chapters_paths:
                try:
                    print(f"[DEBUG] 开始更新追踪器，内容长度: {len(existing_chapters_content)}")
                    print(f"[DEBUG] 共有 {len(existing_chapters_paths)} 个章节文件")
                    
                    # 对每个章节文件分别检查是否已分析
                    for chapter_path in existing_chapters_paths:
                        print(f"[DEBUG] 检查章节: {chapter_path}")
                        if not self.ai_service.narrative_tracker._is_file_analyzed(chapter_path):
                            print(f"[DEBUG] 章节 {chapter_path} 未分析，开始分析")
                            # 读取章节内容
                            with open(chapter_path, 'r', encoding='utf-8') as f:
                                chapter_content = f.read()
                            # 分析该章节
                            result = self.ai_service.narrative_tracker.analyze_all_trackers_with_ai(chapter_content, file_path=chapter_path)
                            if result:
                                print(f"[DEBUG] 章节 {chapter_path} 分析成功")
                            else:
                                print(f"[DEBUG] 章节 {chapter_path} 分析未返回结果")
                        else:
                            print(f"[DEBUG] 章节 {chapter_path} 已分析，跳过")
                    
                    print(f"[DEBUG] 所有追踪器更新完成")
                except Exception as e:
                    print(f"[ERROR] 追踪器更新出错: {str(e)}")
                    import traceback
                    traceback.print_exc()
                    # 在主线程中显示错误
                    self.root.after(0, lambda: messagebox.showerror("错误", f"追踪器更新失败: {str(e)}"))
                    return
            
            # 追踪器更新完成，在主线程中开始生成内容
            print(f"[DEBUG] 追踪器更新完成，开始生成内容")
            self.root.after(0, lambda: self.generation_status_label.config(text="AI追踪系统全部完成，开始生成续写内容...", fg="green"))
            self.root.after(0, lambda: print(f"[INFO] AI追踪系统全部完成，开始生成续写内容"))
            self.root.after(0, lambda: self._start_continuation_generation(outline_content, detailed_outline_content, 
                                                                           existing_chapters_content, extracted_content, 
                                                                           requirements, genre, style, tracking_info))
        
        # 在后台线程中更新追踪器（不阻塞UI）
        if existing_chapters_content and existing_chapters_paths:
            self.generation_status_label.config(text="正在分析已有章节并更新追踪器...", fg="blue")
            self.root.update()
            print(f"[DEBUG] 启动追踪器更新线程")
            update_thread = threading.Thread(target=update_trackers_and_generate)
            update_thread.daemon = True
            update_thread.start()
            print(f"[DEBUG] 追踪器更新线程已启动")
        else:
            # 没有已有章节内容，直接开始生成
            print(f"[INFO] 没有已有章节内容，直接开始生成续写内容")
            self.generation_status_label.config(text="没有已有章节内容，直接开始生成续写内容...", fg="blue")
            self.root.update()
            self._start_continuation_generation(outline_content, detailed_outline_content, 
                                               existing_chapters_content, extracted_content, 
                                               requirements, genre, style, tracking_info)
    
    def _start_continuation_generation(self, outline_content, detailed_outline_content, 
                                      existing_chapters_content, extracted_content, 
                                      requirements, genre, style, tracking_info):
        """开始生成续写内容（在主线程中调用）"""
        print(f"[DEBUG] 开始生成内容，风格: {style}")
        
        # 获取续写模式和色情方向
        continuation_mode = self.continuation_mode_var.get() if hasattr(self, 'continuation_mode_var') else "正常续写"
        erotic_direction = self.continuation_erotic_direction_var.get() if hasattr(self, 'continuation_erotic_direction_var') and continuation_mode == "色情续写" else ""
        
        # 检查AI追踪系统是否有数据，如果有，获取tracking_info
        if hasattr(self.ai_service, 'narrative_tracker') and self.ai_service.narrative_tracker.use_ai_tracking:
            if hasattr(self.ai_service.narrative_tracker, 'character_tracker') and hasattr(self.ai_service.narrative_tracker.character_tracker, 'character_data'):
                if len(self.ai_service.narrative_tracker.character_tracker.character_data) > 0:
                    print(f"[INFO] AI追踪系统数据库有数据，正在获取追踪信息...")
                    try:
                        tracking_info = self.ai_service.narrative_tracker.get_tracking_summary()
                        print(f"[INFO] 成功获取追踪信息，长度: {len(tracking_info)}")
                        self.generation_status_label.config(text="AI追踪系统数据已加载，开始生成续写内容...", fg="green")
                        self.root.update()
                    except Exception as e:
                        print(f"[ERROR] 获取追踪信息失败: {str(e)}")
                        tracking_info = ""
        
        # 使用续写处理器
        if continuation_mode == "色情续写":
            processor = get_erotic_continuation_processor()
            result = processor.处理续写请求(
                outline_content, detailed_outline_content, existing_chapters_content,
                extracted_content, requirements, genre, style,
                self.ai_service.generate_content, direction=erotic_direction, tracking_info=tracking_info
            )
            if result:
                self.generated_text.delete(1.0, tk.END)
                self.generated_text.insert(1.0, result)
                self.generation_status_label.config(text="色情续写生成完成！", fg="green")
                self.save_content_button.config(state=tk.NORMAL)
                self.regenerate_button.config(state=tk.NORMAL)
                return
        
        # 正常续写或处理器失败时使用原有逻辑
        if style == "出版小说":
            self.generate_published_novel_continuation_async(outline_content, detailed_outline_content, 
                                                           existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "网文":
            self.generate_webnovel_continuation_async(outline_content, detailed_outline_content, 
                                                     existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "轻小说":
            self.generate_light_novel_continuation_async(outline_content, detailed_outline_content, 
                                                        existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "剧本":
            self.generate_script_continuation_async(outline_content, detailed_outline_content, 
                                                   existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "散文":
            self.generate_prose_continuation_async(outline_content, detailed_outline_content, 
                                                   existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "诗歌":
            self.generate_poetry_continuation_async(outline_content, detailed_outline_content, 
                                                   existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "霸道总裁":
            self.generate_boss_continuation_async(outline_content, detailed_outline_content, 
                                                 existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "古风":
            self.generate_ancient_continuation_async(outline_content, detailed_outline_content, 
                                                     existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "玄幻":
            self.generate_fantasy_continuation_async(outline_content, detailed_outline_content, 
                                                          existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "武侠":
            self.generate_martial_continuation_async(outline_content, detailed_outline_content, 
                                                          existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "仙侠":
            self.generate_xianxia_continuation_async(outline_content, detailed_outline_content, 
                                                          existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "历史":
            self.generate_history_continuation_async(outline_content, detailed_outline_content, 
                                                     existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "悬疑":
            self.generate_suspense_continuation_async(outline_content, detailed_outline_content, 
                                                     existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "科幻":
            self.generate_scifi_continuation_async(outline_content, detailed_outline_content, 
                                                   existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "奇幻":
            self.generate_fantasy_continuation_async(outline_content, detailed_outline_content, 
                                                     existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "恐怖":
            self.generate_horror_continuation_async(outline_content, detailed_outline_content, 
                                                   existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "网游":
            self.generate_game_continuation_async(outline_content, detailed_outline_content, 
                                                  existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "末世":
            self.generate_apocalypse_continuation_async(outline_content, detailed_outline_content, 
                                                       existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "异能":
            self.generate_superpower_continuation_async(outline_content, detailed_outline_content, 
                                                       existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        elif style == "色情":
            self.generate_erotic_continuation_async(outline_content, detailed_outline_content, 
                                                   existing_chapters_content, extracted_content, requirements, genre, tracking_info)
        else:
            self.generate_traditional_continuation_async(
                outline_content, detailed_outline_content, 
                existing_chapters_content, extracted_content, requirements, genre, style, tracking_info
            )
