    def ask_overwrite_or_new(self, file_type, existing_files):
        """询问用户是覆盖还是新建"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        dialog = tk.Toplevel(self.root)
        dialog.title(f"保存{file_type}")
        dialog.geometry("400x200")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(bg=theme["bg"])
        
        saved_alpha = self.dialog_alpha_vars.get("message_window", tk.DoubleVar(value=0.97)).get()
        dialog.attributes('-alpha', saved_alpha)
        self.active_windows['message_window'] = dialog
        dialog.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('message_window', dialog))
        
        self.apply_dialog_background('message_window')
        
        tk.Label(dialog, text=f"检测到已有 {len(existing_files)} 个{file_type}文件", 
                font=("微软雅黑", 12, "bold"), bg=theme["bg"], fg=theme["fg"]).pack(pady=20)
        tk.Label(dialog, text="请选择操作:", bg=theme["bg"], fg=theme["fg"]).pack(pady=10)
        
        result = {"choice": None}
        
        def on_overwrite():
            result["choice"] = "overwrite"
            dialog.destroy()
        
        def on_new():
            result["choice"] = "new"
            dialog.destroy()
        
        def on_cancel():
            result["choice"] = "cancel"
            dialog.destroy()
        
        button_frame = tk.Frame(dialog, bg=theme["bg"])
        button_frame.pack(pady=10)
        
        tk.Button(button_frame, text=f"覆盖原有{file_type}", command=on_overwrite, width=20,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(pady=5)
        tk.Button(button_frame, text=f"生成新的{file_type}文件", command=on_new, width=20,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(pady=5)
        tk.Button(button_frame, text="取消", command=on_cancel, width=20,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(pady=5)
        
        self.root.wait_window(dialog)
        return result["choice"]
    
    def select_file_to_overwrite(self, directory, files, content, file_type):
        """选择要覆盖的文件"""
        theme = self.theme_manager.get_theme(self.current_theme)
        
        dialog = tk.Toplevel(self.root)
        dialog.title(f"选择要覆盖的{file_type}文件")
        dialog.geometry("800x600")
        dialog.transient(self.root)
        dialog.grab_set()
        dialog.configure(bg=theme["bg"])
        
        saved_alpha = self.dialog_alpha_vars.get("input_window", tk.DoubleVar(value=0.97)).get()
        dialog.attributes('-alpha', saved_alpha)
        self.active_windows['input_window'] = dialog
        dialog.protocol("WM_DELETE_WINDOW", lambda: self.on_dialog_close('input_window', dialog))
        
        self.apply_dialog_background('input_window')
        
        tk.Label(dialog, text=f"请选择要覆盖的{file_type}文件:", 
                font=("微软雅黑", 12, "bold"), bg=theme["bg"], fg=theme["fg"]).pack(pady=10)
        
        list_frame = tk.Frame(dialog, bg=theme["bg"])
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        listbox = tk.Listbox(list_frame, selectmode=tk.SINGLE, height=15, font=("宋体", 11),
                           bg=theme["bg"], fg=theme["fg"], selectbackground=theme["highlight"],
                           relief="solid", bd=1)
        scrollbar = tk.Scrollbar(list_frame, orient=tk.VERTICAL, bg=theme["bg"],
                               troughcolor=theme["scrollbar_trough"], activebackground=theme["button_active_bg"])
        listbox.config(yscrollcommand=scrollbar.set)
        scrollbar.config(command=listbox.yview)
        
        for file in files:
            listbox.insert(tk.END, file)
        
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        preview_frame = tk.LabelFrame(dialog, text="文件预览", bg=theme["bg"], fg=theme["fg"],
                                    padx=10, pady=10, bd=1, relief="solid")
        preview_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        preview_text = scrolledtext.ScrolledText(preview_frame, height=10, width=80, font=("宋体", 10),
                                               bg=theme["bg"], fg=theme["fg"], relief="solid", bd=1)
        preview_text.pack(fill=tk.BOTH, expand=True)
        
        def on_select(event):
            selection = listbox.curselection()
            if selection:
                filename = listbox.get(selection[0])
                file_content = self.file_manager.get_file_preview(directory, filename)
                preview_text.delete(1.0, tk.END)
                preview_text.insert(1.0, file_content)
        
        listbox.bind('<<ListboxSelect>>', on_select)
        
        def on_ok():
            selection = listbox.curselection()
            if selection:
                filename = listbox.get(selection[0])
                filepath = os.path.join(directory, filename)
                
                if messagebox.askyesno("确认", f"确定要覆盖文件 '{filename}' 吗？"):
                    try:
                        if file_type == "outline":
                            formatted_content = self.format_outline(content)
                        else:
                            formatted_content = self.format_detailed_outline(content)
                        
                        with open(filepath, 'w', encoding='utf-8') as f:
                            f.write(formatted_content)
                        
                        messagebox.showinfo("成功", f"{file_type}已覆盖保存到:\n{filepath}")
                        dialog.destroy()
                    except Exception as e:
                        messagebox.showerror("错误", f"保存失败: {str(e)}")
            else:
                messagebox.showerror("错误", "请先选择一个文件！")
        
        def on_cancel():
            dialog.destroy()
        
        button_frame = tk.Frame(dialog, bg=theme["bg"])
        button_frame.pack(pady=10)
        
        tk.Button(button_frame, text="覆盖", command=on_ok, width=15,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(side=tk.LEFT, padx=10)
        tk.Button(button_frame, text="取消", command=on_cancel, width=15,
                 bg=theme["button_bg"], fg=theme["button_fg"], activebackground=theme["button_active_bg"],
                 activeforeground=theme["button_active_fg"], relief="raised", bd=1).pack(side=tk.LEFT, padx=10)
    
    def save_as_new_file(self, directory, content, file_type):
        """保存为新文件"""
        filename = filedialog.asksaveasfilename(
            title=f"保存{file_type}",
            initialdir=directory,
            defaultextension=".txt",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        
        if filename:
            if not filename.startswith(directory):
                filename = os.path.join(directory, os.path.basename(filename))
            
            if file_type == "大纲":
                formatted_content = self.format_outline(content)
            else:
                formatted_content = self.format_detailed_outline(content)
            
            try:
                with open(filename, 'w', encoding='utf-8') as f:
                    f.write(formatted_content)
                messagebox.showinfo("成功", f"{file_type}已保存到:\n{filename}")
            except Exception as e:
                messagebox.showerror("错误", f"保存失败: {str(e)}")

    def regenerate_content(self):
        """重新生成内容"""
        # 检查是否有生成的内容
        if not hasattr(self, 'generated_content_type'):
            messagebox.showwarning("提示", "请先生成内容后再使用重新生成功能！")
            return
        
        # 检查是否有生成的内容
        if not self.generated_content:
            messagebox.showwarning("提示", "没有可重新生成的内容！")
            return
        
        # 添加时间戳确保每次都生成新内容
        timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
        
        if self.generated_content_type == "outline":
            # 重新生成大纲时，传递空字符串，让函数自己合并创作要求
            self.generate_outline_content_async("")
        elif self.generated_content_type == "detailed_outline":
            # 重新生成细纲时，传递空字符串，让函数自己合并创作要求
            if hasattr(self, 'selected_outline_file') and self.selected_outline_file:
                outline_dir = self.file_manager.outline_dir
                outline_content = self.file_manager.get_file_content(outline_dir, self.selected_outline_file)
                self.generate_detailed_outline_content_async(outline_content, "")
            elif hasattr(self, 'temp_outline_content'):
                self.generate_detailed_outline_content_async(self.temp_outline_content, "")
            else:
                messagebox.showerror("错误", "未找到大纲内容，无法重新生成细纲！")
        elif self.generated_content_type == "chapter":
            if hasattr(self, 'current_package_path') and self.current_package_path:
                self.generate_from_package(self.current_package_path)
            elif hasattr(self, 'current_chapter_data'):
                data = self.current_chapter_data
                mode = data.get('mode', 'traditional')
                
                # 添加时间戳到requirements
                requirements_with_timestamp = data['requirements'] + f"\n\n[重新生成时间戳: {timestamp}]"
                
                if mode == 'webnovel':
                    self.generate_webnovel_chapter_async(
                        data['outline_content'],
                        data['detailed_outline_content'],
                        requirements_with_timestamp,
                        data['genre'],
                        data['style']
                    )
                else:
                    self.generate_traditional_chapter_async(
                        data['outline_content'],
                        data['detailed_outline_content'],
                        requirements_with_timestamp,
                        data['genre'],
                        data['style']
                    )
            else:
                messagebox.showerror("错误", "未找到章节数据，无法重新生成！\n请重新生成章节。")
        elif self.generated_content_type == "continuation":
            if hasattr(self, 'current_continuation_data'):
                data = self.current_continuation_data
                mode = data.get('mode', 'traditional')
                
                # 添加时间戳到requirements
                requirements_with_timestamp = data['requirements'] + f"\n\n[重新生成时间戳: {timestamp}]"
                
                if mode == 'webnovel':
                    self.generate_webnovel_continuation_async(
                        data['outline_content'],
                        data['detailed_outline_content'],
                        data['existing_chapters_content'],
                        data['extracted_content'],
                        requirements_with_timestamp,
                        data.get('genre', '都市情感'),
                        data.get('style', '出版小说')
                    )
                else:
                    self.generate_traditional_continuation_async(
                        data['outline_content'],
                        data['detailed_outline_content'],
                        data['existing_chapters_content'],
                        data['extracted_content'],
                        requirements_with_timestamp,
                        data.get('genre', '都市情感'),
                        data.get('style', '出版小说')
                    )
            else:
                messagebox.showerror("错误", "未找到续写数据，无法重新生成！\n请重新生成续写。")
        else:
            messagebox.showinfo("提示", f"当前内容类型: {self.generated_content_type}\n重新生成功能暂不支持此类型。")
    
    

    def browse_rewrite_existing_chapters(self):
        """浏览选择改写用已有章节文件（多选）"""
        filepaths = filedialog.askopenfilenames(
            title="选择已有章节文件",
            initialdir=self.file_manager.chapters_dir,
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if filepaths:
            added_count = 0
            for filepath in filepaths:
                # 检查文件是否已存在
                existing_files = list(self.rewrite_existing_chapters_listbox.get(0, tk.END))
                if filepath not in existing_files:
                    self.rewrite_existing_chapters_listbox.insert(tk.END, filepath)
                    added_count += 1
            
            # 保存更新后的列表
            self.save_rewrite_existing_chapters_list()
            
            # 显示添加成功消息
            if added_count > 0:
                messagebox.showinfo("成功", f"已添加 {added_count} 个文件")
            else:
                messagebox.showinfo("提示", "所选文件已存在于列表中")

    def add_rewrite_chapter_to_list(self, filepath):
        """添加章节到改写列表（用于拖放）"""
        # 检查文件是否已存在
        existing_files = list(self.rewrite_existing_chapters_listbox.get(0, tk.END))
        if filepath not in existing_files:
            self.rewrite_existing_chapters_listbox.insert(tk.END, filepath)
            self.save_rewrite_existing_chapters_list()
            messagebox.showinfo("成功", f"已添加文件: {os.path.basename(filepath)}")
        else:
            messagebox.showinfo("提示", f"文件已存在: {os.path.basename(filepath)}")

    def save_rewrite_existing_chapters_list(self):
        """保存当前改写已有章节列表到配置"""
        chapters_list = list(self.rewrite_existing_chapters_listbox.get(0, tk.END))
        self.config_manager.save_rewrite_existing_chapters(chapters_list)

    def clear_rewrite_existing_chapters(self):
        """清空改写已有章节列表"""
        self.rewrite_existing_chapters_listbox.delete(0, tk.END)
        self.save_rewrite_existing_chapters_list()
        messagebox.showinfo("成功", "改写已有章节列表已清空")

    def delete_selected_rewrite_chapters(self):
        """删除选中的改写章节（支持多个）"""
        selected_indices = self.rewrite_existing_chapters_listbox.curselection()
        
        if not selected_indices:
            messagebox.showinfo("提示", "请先选择要删除的章节！")
            return
        
        # 获取要删除的文件名用于显示
        deleted_files = []
        for idx in selected_indices:
            filepath = self.rewrite_existing_chapters_listbox.get(idx)
            deleted_files.append(os.path.basename(filepath))
        
        # 从后往前删除，避免索引变化导致错误
        for idx in reversed(selected_indices):
            self.rewrite_existing_chapters_listbox.delete(idx)
        
        # 保存更新后的列表
        self.save_rewrite_existing_chapters_list()
        
        # 显示删除成功消息
        if len(deleted_files) == 1:
            messagebox.showinfo("成功", f"已删除 '{deleted_files[0]}'")
        else:
            messagebox.showinfo("成功", f"已删除 {len(deleted_files)} 个文件")

    def sort_rewrite_chapters_by_name(self):
        """按照文件名排序改写章节列表"""
        file_count = self.rewrite_existing_chapters_listbox.size()
        if file_count == 0:
            return
        
        files = []
        for i in range(file_count):
            filepath = self.rewrite_existing_chapters_listbox.get(i)
            files.append(filepath)
        
        # 按文件名排序
        files.sort(key=os.path.basename)
        
        # 重新插入排序后的文件
        self.rewrite_existing_chapters_listbox.delete(0, tk.END)
        for filepath in files:
            self.rewrite_existing_chapters_listbox.insert(tk.END, filepath)
        
        # 保存排序后的列表
        self.save_rewrite_existing_chapters_list()
        messagebox.showinfo("成功", "已按文件名排序")

    def sort_rewrite_chapters_by_chapter(self):
        """按照章节顺序排序改写章节列表"""
        file_count = self.rewrite_existing_chapters_listbox.size()
        if file_count == 0:
            return
        
        files = []
        for i in range(file_count):
            filepath = self.rewrite_existing_chapters_listbox.get(i)
            filename = os.path.basename(filepath)
            chapter_num = self.extract_chapter_number(filename)
            files.append({
                'filepath': filepath,
                'chapter_num': chapter_num
            })
        
        # 按章节号排序
        files.sort(key=lambda x: x['chapter_num'] if x['chapter_num'] is not None else float('inf'))
        
        # 重新插入排序后的文件
        self.rewrite_existing_chapters_listbox.delete(0, tk.END)
        for file_info in files:
            self.rewrite_existing_chapters_listbox.insert(tk.END, file_info['filepath'])
        
        # 保存排序后的列表
        self.save_rewrite_existing_chapters_list()
        messagebox.showinfo("成功", "已按章节顺序排序")

    def open_rewrite_chapter_location(self):
        """打开选中章节的文件位置"""
        selected_indices = self.rewrite_existing_chapters_listbox.curselection()
        
        if not selected_indices:
            messagebox.showinfo("提示", "请先选择要打开的章节！")
            return
        
        filepath = self.rewrite_existing_chapters_listbox.get(selected_indices[0])
        directory = os.path.dirname(filepath)
        
        try:
            if os.name == 'nt':  # Windows
                os.startfile(directory)
            elif os.name == 'posix':  # macOS or Linux
                subprocess.run(['open', directory] if sys.platform == 'darwin' else ['xdg-open', directory])
        except Exception as e:
            messagebox.showerror("错误", f"无法打开文件位置：{str(e)}")

    def load_saved_rewrite_existing_chapters(self):
        """加载保存的改写已有章节文件列表"""
        try:
            saved_chapters = self.config_manager.get_rewrite_existing_chapters()
            if saved_chapters:
                # 检查文件是否仍然存在
                valid_chapters = []
                invalid_chapters = []
                
                for chapter_path in saved_chapters:
                    if os.path.exists(chapter_path):
                        valid_chapters.append(chapter_path)
                    else:
                        invalid_chapters.append(chapter_path)
                
                # 添加有效的文件到列表框
                for chapter_path in valid_chapters:
                    self.rewrite_existing_chapters_listbox.insert(tk.END, chapter_path)
                
                # 如果有无效的文件，显示提示
                if invalid_chapters:
                    invalid_files = '\n'.join([os.path.basename(path) for path in invalid_chapters[:5]])
                    if len(invalid_chapters) > 5:
                        invalid_files += f'\n...还有{len(invalid_chapters) - 5}个文件'
                    messagebox.showwarning("提示", f"以下文件已不存在，已从列表中移除：\n{invalid_files}")
                    
                    # 更新保存的列表（移除无效文件）
                    self.config_manager.save_rewrite_existing_chapters(valid_chapters)
                
                if valid_chapters:
                    print(f"[改写] 已加载 {len(valid_chapters)} 个保存的章节文件")
        except Exception as e:
            print(f"[改写] 加载保存的章节文件失败: {e}")
    
