    def show_rewrite_tracking_status(self):
        """显示改写追踪状态窗口"""
        status = self.get_rewrite_tracking_status()
        
        # 创建状态窗口
        status_window = tk.Toplevel(self.root)
        status_window.title("改写追踪系统状态")
        status_window.geometry("800x600")
        
        # 创建文本框显示状态
        text_widget = scrolledtext.ScrolledText(status_window, wrap=tk.WORD, width=80, height=30)
        text_widget.pack(padx=10, pady=10, fill=tk.BOTH, expand=True)
        
        # 格式化显示状态信息
        def format_dict(d, indent=0):
            result = ""
            for key, value in d.items():
                if isinstance(value, dict):
                    result += "  " * indent + f"{key}:\n"
                    result += format_dict(value, indent + 1)
                elif isinstance(value, list):
                    result += "  " * indent + f"{key}:\n"
                    for item in value:
                        if isinstance(item, dict):
                            result += format_dict(item, indent + 2)
                        else:
                            result += "  " * (indent + 1) + f"- {item}\n"
                else:
                    result += "  " * indent + f"{key}: {value}\n"
            return result
        
        status_text = format_dict(status)
        text_widget.insert(tk.END, status_text)
        text_widget.config(state=tk.DISABLED)
        
        # 添加刷新按钮
        def refresh_status():
            new_status = self.get_rewrite_tracking_status()
            text_widget.config(state=tk.NORMAL)
            text_widget.delete(1.0, tk.END)
            text_widget.insert(tk.END, format_dict(new_status))
            text_widget.config(state=tk.DISABLED)
        
        refresh_button = ttk.Button(status_window, text="刷新状态", command=refresh_status)
        refresh_button.pack(pady=5)
        
        # 添加清除缓存按钮
        def clear_cache():
            ai_processor = get_rewrite_ai_processor()
            ai_processor.清除缓存()
            refresh_status()
            messagebox.showinfo("成功", "改写系统缓存已清除")
        
        clear_cache_button = ttk.Button(status_window, text="清除缓存", command=clear_cache)
        clear_cache_button.pack(pady=5)
    
