    # 增强版追踪系统集成方法
    def start_enhanced_rewrite_session(self, original_content, style="出版小说", direction="色情描写", custom_requirement=""):
        """开始增强版改写会话"""
        if not HAS_ENHANCED_TRACKING:
            messagebox.showwarning("警告", "增强版追踪系统未安装或导入失败")
            return None
            
        try:
            integration = get_rewrite_tracking_integration()
            session_id = integration.start_enhanced_session(
                original_content=original_content,
                style=style,
                direction=direction,
                custom_requirement=custom_requirement
            )
            
            if session_id:
                self.log_message(f"增强版改写会话已开始: {session_id}")
                return session_id
            else:
                messagebox.showerror("错误", "开始增强版改写会话失败")
                return None
                
        except Exception as e:
            messagebox.showerror("错误", f"开始增强版改写会话失败: {str(e)}")
            return None
    
    def track_enhanced_rewrite_operation(self, session_id, operation_type, data, context=None):
        """追踪增强版改写操作"""
        if not HAS_ENHANCED_TRACKING:
            return False
            
        try:
            integration = get_rewrite_tracking_integration()
            return integration.track_rewrite_operation(
                session_id=session_id,
                operation_type=operation_type,
                data=data,
                context=context
            )
        except Exception as e:
            print(f"追踪增强版改写操作失败: {str(e)}")
            return False
    
    def end_enhanced_rewrite_session(self, session_id, success=True, final_content="", error_message=""):
        """结束增强版改写会话"""
        if not HAS_ENHANCED_TRACKING:
            return {"success": False, "error": "增强版追踪系统不可用"}
            
        try:
            integration = get_rewrite_tracking_integration()
            result = integration.end_enhanced_session(
                session_id=session_id,
                success=success,
                final_content=final_content,
                error_message=error_message
            )
            
            if result.get("success"):
                self.log_message(f"增强版改写会话已结束: {session_id}")
                
                # 显示分析报告
                if "analytics_report" in result:
                    self.show_enhanced_analytics_report(result["analytics_report"])
            
            return result
            
        except Exception as e:
            return {"success": False, "error": str(e)}
    
